-- ALL TEN SOCIAL MIGRATIONS IN ONE PASTE (website branch feat/social-backend, same bytes as apps/bottles-up-website-main/supabase/migrations/20261101100000 .. 20261110100000):
-- feature switches, social profiles (usernames, following, blocking), posts and stories and comments and the private media bucket, explore and reviews and venue facts, messages
-- and notifications, safety and moderation (reports, the staff queue, suspending a person, the community rules text).
-- GENERATED by supabase/go-live/build_social.py: do not edit it by hand (python3 -I supabase/go-live/build_social.py --check says whether it is current).
-- EVERYTHING IS ADDITIVE and every feature starts SWITCHED OFF: nothing in the apps changes until a switch is turned on in the website's CMS (Social settings).
-- HOW: run supabase/audit/22_preflight_social.sql FIRST (it must return no rows), then paste this whole file into the Supabase dashboard > SQL editor (production project) and Run.
-- Each migration is wrapped in its own begin/commit, in this order, so an error rolls back THAT migration and stops the rest (the earlier ones stay applied; send the error
-- text, do not edit a file). Then run supabase/audit/23_postflight_social.sql: every row ok = true. THEN deploy the edge functions and schedule the clean-up
-- (supabase/go-live/README.md, "Going live: the social side").
-- UNDO: supabase/go-live/rollback_social.sql. Never use `supabase db push`.

-- ====================================================================================================
-- 20261101100000_feature_flags
-- ====================================================================================================
begin;
-- Feature switches (customer app completion plan, M0): "Features ship dark". Each part of the client's social and marketplace plan that still
-- needs a business decision (money, subscriptions, rankings, split payments...) is built, tested and then switched on by BottlesUp here, not
-- by shipping a new app.
--
--   * Every switch starts OFF. The apps ask site_features() which are on and hide the rest.
--   * A switch only changes what the apps SHOW. Every database function of a feature that is off still enforces its own rules, so nothing
--     here is a security control; the functions of money features additionally refuse while their switch is off (they call feature_enabled()).
--   * Only a BottlesUp admin (cms_admins) changes a switch, and each change is written to the audit log.
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

create table public.site_feature_flags (
  key text primary key check (key ~ '^[a-z][a-z0-9_]{1,40}$'),
  enabled boolean not null default false,
  note text check (note is null or char_length(note) <= 300),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null
);
alter table public.site_feature_flags enable row level security;
revoke all on table public.site_feature_flags from public, anon, authenticated;

insert into public.site_feature_flags (key, note) values
  ('social', 'Profiles, following, the home feed, posts, likes and comments'),
  ('stories', 'Stories that last 24 hours'),
  ('reels', 'Short videos and the reels viewer'),
  ('members_only', 'Posts only a creator''s chosen members can see'),
  ('inbox', 'Direct, group and booking conversations between customers'),
  ('reviews', 'Reviews of venues and of events'),
  ('split_payments', 'Guests paying their share of a table or an order'),
  ('marketplace', 'Hiring DJs, photographers and other professionals; quotes and payments'),
  ('venue_hire', 'Event organizers asking venues to host an event; the event workspace'),
  ('referrals', 'Referral links and commissions'),
  ('subscriptions', 'Paid business subscriptions'),
  ('advertising', 'Sponsored placements'),
  ('creator_earnings', 'Creator income and payouts'),
  ('ranks', 'Follower-based verification ranks and awards'),
  ('jobs', 'Jobs and opportunities'),
  ('ai_captions', 'Caption ideas written by an AI for a post, which the person reads and changes before posting');

-- What is switched on. Anyone may ask, signed in or not (the app asks before it knows who is using it); it shows no person, only names of features.
create function public.site_features()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_object_agg(f.key, f.enabled), '{}'::jsonb) from public.site_feature_flags f
$$;

-- For other functions: is this feature on right now?
create function public.feature_enabled(p_key text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select coalesce((select f.enabled from public.site_feature_flags f where f.key = p_key), false)
$$;

-- A BottlesUp admin turns a feature on or off.
create function public.cms_set_feature(p_key text, p_enabled boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_old boolean;
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can change this.'; end if;
  if p_enabled is null then raise exception 'Choose on or off.'; end if;
  select f.enabled into v_old from public.site_feature_flags f where f.key = p_key for update;
  if not found then raise exception 'There is no such feature.'; end if;
  if v_old is distinct from p_enabled then
    update public.site_feature_flags set enabled = p_enabled, updated_at = now(), updated_by = auth.uid() where key = p_key;
    insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
    values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'feature_switched', 'feature', p_key,
            jsonb_build_object('from', v_old, 'to', p_enabled));
  end if;
  return public.site_features();
end;
$$;

-- The admin list with notes, for the CMS page.
create function public.cms_list_features()
returns table (key text, enabled boolean, note text, updated_at timestamptz)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  return query select f.key, f.enabled, f.note, f.updated_at from public.site_feature_flags f order by f.key;
end;
$$;

revoke all on function public.site_features(), public.feature_enabled(text), public.cms_set_feature(text, boolean), public.cms_list_features()
  from public, anon, authenticated;
grant execute on function public.site_features() to anon, authenticated, service_role;
grant execute on function public.cms_set_feature(text, boolean), public.cms_list_features() to authenticated, service_role;
grant execute on function public.feature_enabled(text) to service_role;
commit;

-- ====================================================================================================
-- 20261101110000_social_profiles
-- ====================================================================================================
begin;
-- Social profiles (customer app completion plan, M1; client plan pages 3 and 4): one login can hold a personal profile and several business
-- profiles (a venue, an event group, a DJ, a photographer...), follow other profiles, ask to follow a private one, and block.
--
--   * A PERSONAL profile is one row per login. Its name, username, bio, city, picture and links stay where they already are (profiles, saved by
--     save_my_profile); this table adds what social needs: public or private, interests. A BUSINESS profile is its own row: a venue's (owned by the
--     venue's business, edited by its owner or that venue's manager), an event group's (optionally tied to an organizer business), or a professional's
--     (owned by one login). Business profiles are always public.
--   * USERNAMES are one list. The handle of a personal profile is profiles.username and of a business profile its own handle; site_handles keeps both in
--     ONE table with a primary key, so the two kinds can never take the same name, even at the same moment. Business handles do not change.
--   * WHO MAY ACT as a profile is worked out from the caller's CURRENT state on every call (the login, or the business role / venue manager role), not
--     from a stored list. Every function that does something takes the profile it is done AS (p_actor) and checks it. Revoke a manager and they are out
--     at once.
--   * PRIVATE profiles (personal only): anyone may see the header and the counts; the followers, following and (later) posts only the profile's owner
--     and approved followers see. A follow of a private profile waits as a request until the owner accepts. Turning a private profile public accepts
--     the waiting requests. Turning a public profile private keeps the people who follow already.
--   * BLOCKING hides two PEOPLE from each other both ways (search, profile page, lists), removes the follows between them and refuses a new one. The
--     refusal says "This profile isn't available." and so never tells someone they were blocked. A person is the login behind a personal profile and the
--     professional profiles it owns (a DJ's, a photographer's): blocking any of them blocks all of them, and unblocking any lifts it. A venue's or an event
--     group's profile is run by a team, so it is blocked, and blocks, on its own.
--   * Following is slowed: at most 200 new follows an hour from one profile.
--   * Everything that CREATES or CHANGES something social (a profile, a follow) refuses with "Profiles are not open yet." until BottlesUp switches the `social`
--     feature on (20261101100000), so a dark launch is dark on the server too, not only in the app. Reading, unfollowing and blocking always work.
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table public.site_profiles (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('personal', 'business')),
  -- Personal: the person. Business without a venue business behind it: the one login that owns it.
  user_id uuid references auth.users (id) on delete cascade,
  -- Business tied to a venue business (a venue's profile, or an organizer's event group).
  org_id uuid references public.site_organizations (id) on delete cascade,
  venue_id uuid references public.site_venues (id) on delete cascade,
  -- Business only; a personal profile's handle is profiles.username.
  handle text check (handle is null or handle ~ '^[a-z0-9._]{3,30}$'),
  display_name text check (display_name is null or char_length(btrim(display_name)) between 1 and 100),
  category text check (category in ('venue', 'event_group', 'dj', 'mc', 'artist', 'instrumentalist', 'photographer', 'videographer',
                                    'influencer', 'promoter', 'other')),
  bio text check (bio is null or char_length(bio) <= 280),
  city text check (city is null or char_length(city) <= 80),
  avatar_url text check (avatar_url is null or (avatar_url ~ '^https://' and char_length(avatar_url) <= 500)),
  cover_url text check (cover_url is null or (cover_url ~ '^https://' and char_length(cover_url) <= 500)),
  social_links jsonb not null default '{}'::jsonb check (jsonb_typeof(social_links) = 'object'),
  privacy text not null default 'public' check (privacy in ('public', 'private')),
  interests text[] not null default '{}' check (cardinality(interests) <= 10),
  status text not null default 'active' check (status in ('active', 'suspended')),
  -- The moment it was written, so a person's profiles list in the order they were made.
  created_at timestamptz not null default clock_timestamp(),
  constraint site_profiles_shape check (
    (kind = 'personal' and user_id is not null and org_id is null and venue_id is null
       and handle is null and display_name is null and category is null)
    or
    (kind = 'business' and handle is not null and display_name is not null and category is not null and privacy = 'public'
       and ((org_id is not null and user_id is null) or (org_id is null and user_id is not null and venue_id is null)))
  ),
  constraint site_profiles_venue_category check (kind = 'personal' or ((category = 'venue') = (venue_id is not null)))
);
create unique index site_profiles_one_personal on public.site_profiles (user_id) where kind = 'personal';
create unique index site_profiles_one_per_venue on public.site_profiles (venue_id) where venue_id is not null;
create unique index site_profiles_one_per_org_group on public.site_profiles (org_id) where org_id is not null and venue_id is null;
create index site_profiles_owner_idx on public.site_profiles (user_id) where user_id is not null;
create index site_profiles_org_idx on public.site_profiles (org_id) where org_id is not null;
create index site_profiles_handle_prefix on public.site_profiles (handle text_pattern_ops) where handle is not null;
create index site_profiles_name_prefix on public.site_profiles (lower(display_name) text_pattern_ops) where display_name is not null;

-- Search by the start of a name or username on the person's own record.
create index profiles_username_prefix_idx on public.profiles (username text_pattern_ops) where username is not null;
create index profiles_name_prefix_idx on public.profiles (lower(name) text_pattern_ops) where name is not null;

-- One list of usernames for both kinds.
create table public.site_handles (
  handle text primary key check (handle ~ '^[a-z0-9._]{3,30}$'),
  profile_id uuid unique references public.profiles (id) on delete cascade,
  business_id uuid unique references public.site_profiles (id) on delete cascade,
  constraint site_handles_one_owner check ((profile_id is null) <> (business_id is null))
);

create table public.site_follows (
  follower uuid not null references public.site_profiles (id) on delete cascade,
  followed uuid not null references public.site_profiles (id) on delete cascade,
  status text not null default 'active' check (status in ('active', 'pending')),
  -- The moment it was written, so a page of followers ordered by it has no ties.
  created_at timestamptz not null default clock_timestamp(),
  primary key (follower, followed),
  check (follower <> followed)
);
create index site_follows_followed_idx on public.site_follows (followed, status, created_at desc);
create index site_follows_follower_idx on public.site_follows (follower, status, created_at desc);

-- A block holds between PEOPLE, so switching to another of their profiles does not get round it. blocker_key / blocked_key say who each side is: the login behind a personal
-- or professional profile, or the profile itself for a venue's or an event group's (those are run by a team, not one person). See profile_key().
create table public.site_blocks (
  blocker uuid not null references public.site_profiles (id) on delete cascade,
  blocked uuid not null references public.site_profiles (id) on delete cascade,
  blocker_key uuid not null,
  blocked_key uuid not null,
  created_at timestamptz not null default clock_timestamp(),
  primary key (blocker, blocked),
  check (blocker <> blocked),
  check (blocker_key <> blocked_key)
);
create index site_blocks_blocked_idx on public.site_blocks (blocked);
create index site_blocks_keys_idx on public.site_blocks (blocker_key, blocked_key);
create index site_blocks_blocked_key_idx on public.site_blocks (blocked_key);

-- The people an owner has let act as a business profile of their own (a DJ, a photographer...), each with a role and the permissions that go with it. Only a row that is 'active' counts:
-- revoking, leaving or being declined ends access at once. A profile run by a venue business is run by that business's own roles instead (see profile_is_owner). Managed by the
-- functions in 20261108100000 (invite, answer, revoke, change a role); the access checks below read it.
create table public.site_profile_team (
  id uuid primary key default gen_random_uuid(),
  profile uuid not null references public.site_profiles (id) on delete cascade,
  member uuid not null references auth.users (id) on delete cascade,
  role text not null check (role in ('manager', 'booking_agent', 'content_manager', 'finance_assistant', 'door_staff', 'custom')),
  permissions text[] not null default '{}' check (permissions <@ array['bookings', 'content', 'finance']::text[]),
  status text not null default 'invited' check (status in ('invited', 'active', 'declined', 'revoked', 'left')),
  invited_by uuid references auth.users (id) on delete set null,
  invited_at timestamptz not null default clock_timestamp(),
  answered_at timestamptz,
  unique (profile, member)
);
create index site_profile_team_member_idx on public.site_profile_team (member, status);

alter table public.site_profiles enable row level security;
alter table public.site_handles enable row level security;
alter table public.site_follows enable row level security;
alter table public.site_blocks enable row level security;
alter table public.site_profile_team enable row level security;
revoke all on table public.site_profiles, public.site_handles, public.site_follows, public.site_blocks, public.site_profile_team from public, anon, authenticated;

-- Every username already in use goes on the one list (the profiles table keeps them unique, so nothing can clash here), and from now on the
-- list follows profiles.username.
insert into public.site_handles (handle, profile_id) select p.username, p.id from public.profiles p where p.username is not null;

create function public.site_handles_follow_profile()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.username is null then
    delete from public.site_handles where profile_id = new.id;
  else
    -- A business profile that already has the name makes this a unique violation, which save_my_profile reports as "username is not available".
    insert into public.site_handles (handle, profile_id) values (new.username, new.id)
    on conflict (profile_id) do update set handle = excluded.handle;
  end if;
  return new;
end;
$$;
create trigger site_handles_follow_profile
after insert or update of username on public.profiles
for each row execute function public.site_handles_follow_profile();

-- ---------------------------------------------------------------------------
-- 2. Internal helpers (the app cannot call these)
-- ---------------------------------------------------------------------------
-- Names nobody may take: staff-sounding, brand and the app's own screens.
create function public.handle_reserved(p_handle text)
returns boolean
language sql
immutable
set search_path = public
as $$
  select p_handle in (
    'admin', 'administrator', 'support', 'help', 'staff', 'bottlesup', 'bottles.up', 'bottles_up', 'bottlesupapp', 'official', 'root', 'system',
    'moderator', 'security', 'safety', 'team', 'press', 'billing', 'payments', 'payouts', 'null', 'undefined', 'api', 'www', 'explore', 'create',
    'inbox', 'home', 'settings', 'privacy', 'terms', 'venues', 'events', 'tickets', 'tables', 'jobs', 'awards', 'verified', 'about', 'contact', 'login',
    'logout', 'signup', 'search'
  )
$$;

-- Does the caller OWN this profile: the login behind a professional's own profile, or the owner or organizer of the business behind a venue's or an event group's (and a venue's manager)?
create function public.profile_is_owner(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and exists (
    select 1 from public.site_profiles p
    where p.id = p_profile
      and (
        p.user_id = auth.uid()
        or (p.org_id is not null and (
              public.is_org_member(p.org_id, array['owner', 'organizer'])
              or (p.venue_id is not null and public.can_access_venue(p.venue_id, array['manager']))
        ))
      )
  )
$$;

-- Is the caller one of the people who may act as this profile (ignoring whether it is suspended): its owner, or somebody the owner has let in who has accepted?
create function public.profile_is_mine(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_is_owner(p_profile)
      or (auth.uid() is not null and exists (select 1 from public.site_profile_team t where t.profile = p_profile and t.member = auth.uid() and t.status = 'active'))
$$;

-- May the caller do this KIND of thing as the profile ('bookings': services, requests, quotes, hires; 'content': posts and the profile's own details; 'finance': earnings)? The owner
-- may do everything; a team member only what their role carries. This says nothing about the profile being in good standing: use it after profile_require_actor.
create function public.profile_has_permission(p_profile uuid, p_permission text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_is_owner(p_profile)
      or (auth.uid() is not null and exists (
            select 1 from public.site_profile_team t
            where t.profile = p_profile and t.member = auth.uid() and t.status = 'active' and p_permission = any (t.permissions)))
$$;

-- Every profile the caller may act as (suspended ones included), found through the indexes instead of by asking about every profile. Must say the same as profile_is_mine:
-- a test compares the two.
create function public.profile_my_ids()
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select p.id from public.site_profiles p where auth.uid() is not null and p.user_id = auth.uid()
  union
  select p.id
  from public.active_memberships() m
  join public.site_profiles p on p.org_id = m.org_id
  where m.role in ('owner', 'organizer') or (m.role = 'manager' and p.venue_id is not null and m.venue_id = p.venue_id)
  union
  select t.profile from public.site_profile_team t where auth.uid() is not null and t.member = auth.uid() and t.status = 'active'
$$;

-- ...and is that profile in good standing?
create function public.profile_can_act_as(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_is_mine(p_profile)
     and exists (select 1 from public.site_profiles p where p.id = p_profile and p.status = 'active')
$$;

-- WHO a profile is, for blocking: the login behind a personal profile or a professional's business profile, the profile itself for a venue's or an event group's.
create function public.profile_key(p_profile uuid)
returns uuid
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(p.user_id, p.id) from public.site_profiles p where p.id = p_profile
$$;

-- Has either person blocked the other? (Any of a person's profiles counts as the person.)
create function public.profile_blocked_between(p_a uuid, p_b uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.site_blocks b
    where (b.blocker_key = public.profile_key(p_a) and b.blocked_key = public.profile_key(p_b))
       or (b.blocker_key = public.profile_key(p_b) and b.blocked_key = public.profile_key(p_a))
  )
$$;

-- May the profile p_viewer (or nobody, when null) see that profile exists at all?
create function public.profile_visible(p_viewer uuid, p_target uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.site_profiles p where p.id = p_target and p.status = 'active')
     and (p_viewer is null or not public.profile_blocked_between(p_viewer, p_target))
$$;

-- May p_viewer see the followers, following and posts of p_target? Public: yes. Private: its owner and approved followers.
create function public.profile_content_visible(p_viewer uuid, p_target uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_visible(p_viewer, p_target)
     and (
       exists (select 1 from public.site_profiles p where p.id = p_target and p.privacy = 'public')
       or public.profile_is_mine(p_target)
       or exists (select 1 from public.site_follows f where f.follower = p_viewer and f.followed = p_target and f.status = 'active')
     )
$$;

-- The badge on a profile: whether it is verified and which rank it holds (the name of a rank, or null). Here a profile is verified when its business account is; the recognition
-- migration (20261110100000) replaces this with the full answer (a person's own verification, and the ranks that were awarded). profile_card and profile_mini only ever ask this.
create function public.profile_badge(p_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'verified', v.verified,
    'rank', case when v.verified then 'verified' else null end)
  from (
    select exists (select 1 from public.site_profiles p where p.id = p_id and p.org_id is not null
                    and exists (select 1 from public.site_verifications x where x.org_id = p.org_id and x.state = 'verified')) as verified
  ) v
$$;

-- What the app shows about one profile, as seen by p_viewer. Does not check that the viewer may see it: the callers do.
create function public.profile_card(p_viewer uuid, p_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  p public.site_profiles;
  pr public.profiles;
  v_follow text := 'none';
  v_follows_me boolean := false;
  v_blocked boolean := false;
  v_mine boolean := public.profile_is_mine(p_id);
  v_content boolean;
begin
  select * into p from public.site_profiles where id = p_id;
  if not found then return null; end if;
  if p.kind = 'personal' then
    select * into pr from public.profiles where id = p.user_id;
  end if;

  if p_viewer is not null and p_viewer <> p_id then
    select f.status into v_follow from public.site_follows f where f.follower = p_viewer and f.followed = p_id;
    v_follow := coalesce(v_follow, 'none');
    v_follows_me := exists (select 1 from public.site_follows f where f.follower = p_id and f.followed = p_viewer and f.status = 'active');
    v_blocked := exists (select 1 from public.site_blocks b where b.blocker_key = public.profile_key(p_viewer) and b.blocked_key = public.profile_key(p_id));
  end if;
  v_content := p.privacy = 'public' or v_mine or v_follow = 'active';

  return jsonb_build_object(
    'id', p.id,
    'kind', p.kind,
    'handle', case p.kind when 'personal' then pr.username else p.handle end,
    'display_name', case p.kind when 'personal' then coalesce(nullif(btrim(pr.name), ''), pr.username) else p.display_name end,
    'category', p.category,
    'bio', case p.kind when 'personal' then pr.bio else p.bio end,
    'city', case p.kind when 'personal' then pr.city else p.city end,
    'avatar_url', case p.kind when 'personal' then pr.avatar_url else p.avatar_url end,
    'cover_url', p.cover_url,
    'social_links', case p.kind when 'personal' then pr.social_links else p.social_links end,
    'privacy', p.privacy,
    'status', p.status,
    'verified', (public.profile_badge(p.id) ->> 'verified')::boolean,
    'rank', public.profile_badge(p.id) -> 'rank',
    'interests', case when v_mine then to_jsonb(p.interests) else '[]'::jsonb end,
    'followers', (select count(*) from public.site_follows f join public.site_profiles s on s.id = f.follower
                  where f.followed = p.id and f.status = 'active' and s.status = 'active'),
    'following', (select count(*) from public.site_follows f join public.site_profiles s on s.id = f.followed
                  where f.follower = p.id and f.status = 'active' and s.status = 'active'),
    'is_mine', v_mine,
    'relation', jsonb_build_object('follow', v_follow, 'follows_me', v_follows_me, 'blocked', v_blocked),
    'can_see_content', v_content
  );
end;
$$;

-- Every profile the caller may act as is checked here, with the same sentence.
create function public.profile_require_actor(p_actor uuid)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if p_actor is null or not public.profile_can_act_as(p_actor) then
    raise exception 'You cannot act as this profile.';
  end if;
end;
$$;

-- Acting as the profile AND allowed this kind of thing by the role (see profile_has_permission).
create function public.profile_require_permission(p_actor uuid, p_permission text)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not public.profile_has_permission(p_actor, p_permission) then
    raise exception 'Your role on this profile does not allow this.';
  end if;
end;
$$;

create function public.profile_clean_interests(p_interests text[])
returns text[]
language plpgsql
immutable
set search_path = public
as $$
declare
  v_item text;
  v_out text[] := '{}';
begin
  if p_interests is null then return v_out; end if;
  foreach v_item in array p_interests loop
    v_item := lower(regexp_replace(btrim(coalesce(v_item, '')), '\s+', ' ', 'g'));
    if v_item = '' then continue; end if;
    if char_length(v_item) < 2 or char_length(v_item) > 30 then raise exception 'An interest must be 2 to 30 characters.'; end if;
    if not (v_item = any (v_out)) then v_out := v_out || v_item; end if;
  end loop;
  if cardinality(v_out) > 10 then raise exception 'Choose up to 10 interests.'; end if;
  return v_out;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Usernames
-- ---------------------------------------------------------------------------
-- Can the caller take this username (for their own profile or a new business profile)? Their own current one counts as free.
create function public.handle_available(p_handle text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v text := lower(btrim(coalesce(p_handle, '')));
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if v !~ '^[a-z0-9._]{3,30}$' then return false; end if;
  if public.handle_reserved(v) then return false; end if;
  return not exists (select 1 from public.site_handles h where h.handle = v and h.profile_id is distinct from auth.uid());
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. The caller's own profiles
-- ---------------------------------------------------------------------------
-- Create or update the caller's personal profile after they have saved their name and username (save_my_profile).
create function public.profile_save_personal(p_privacy text, p_interests text[] default '{}')
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_privacy text := lower(btrim(coalesce(p_privacy, '')));
  v_interests text[] := public.profile_clean_interests(p_interests);
  v_before text;
  v_id uuid;
begin
  if v_uid is null then raise exception 'Sign in first.'; end if;
  if not public.feature_enabled('social') then raise exception 'Profiles are not open yet.'; end if;
  if v_privacy not in ('public', 'private') then raise exception 'Choose public or private.'; end if;
  if not exists (select 1 from public.profiles p where p.id = v_uid and p.username is not null and p.profile_completed_at is not null) then
    raise exception 'Finish your name and username first.';
  end if;

  select s.privacy, s.id into v_before, v_id from public.site_profiles s where s.user_id = v_uid and s.kind = 'personal' for update;
  if not found then
    begin
      insert into public.site_profiles (kind, user_id, privacy, interests) values ('personal', v_uid, v_privacy, v_interests) returning id into v_id;
    exception when unique_violation then
      -- Two taps at once: the other one created it.
      select s.id into v_id from public.site_profiles s where s.user_id = v_uid and s.kind = 'personal';
      update public.site_profiles set privacy = v_privacy, interests = v_interests where id = v_id;
    end;
  else
    update public.site_profiles set privacy = v_privacy, interests = v_interests where id = v_id;
    if v_before = 'private' and v_privacy = 'public' then
      update public.site_follows set status = 'active' where followed = v_id and status = 'pending';
    end if;
  end if;
  return public.profile_card(v_id, v_id);
end;
$$;

-- A venue's profile, an event group's, or a professional's.
create function public.profile_create_business(
  p_category text,
  p_display_name text,
  p_handle text,
  p_bio text default null,
  p_city text default null,
  p_org uuid default null,
  p_venue uuid default null,
  p_avatar_url text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_category text := lower(btrim(coalesce(p_category, '')));
  v_name text := btrim(coalesce(p_display_name, ''));
  v_handle text := lower(btrim(coalesce(p_handle, '')));
  v_bio text := nullif(btrim(coalesce(p_bio, '')), '');
  v_city text := nullif(btrim(coalesce(p_city, '')), '');
  v_avatar text := nullif(btrim(coalesce(p_avatar_url, '')), '');
  v_org uuid;
  v_venue uuid;
  v_owner uuid;
  v_id uuid;
begin
  if v_uid is null then raise exception 'Sign in first.'; end if;
  if not public.feature_enabled('social') then raise exception 'Profiles are not open yet.'; end if;
  if v_category not in ('venue', 'event_group', 'dj', 'mc', 'artist', 'instrumentalist', 'photographer', 'videographer', 'influencer', 'promoter', 'other') then
    raise exception 'Choose what kind of profile this is.';
  end if;
  if char_length(v_name) < 1 or char_length(v_name) > 100 then raise exception 'The name is required (100 characters at most).'; end if;
  if v_bio is not null and char_length(v_bio) > 280 then raise exception 'The description must be 280 characters or fewer.'; end if;
  if v_city is not null and char_length(v_city) > 80 then raise exception 'The city must be 80 characters or fewer.'; end if;
  if v_avatar is not null and (v_avatar !~ '^https://' or char_length(v_avatar) > 500) then raise exception 'The photo must be an https link.'; end if;
  if not exists (select 1 from public.profiles p where p.id = v_uid and p.username is not null and p.profile_completed_at is not null) then
    raise exception 'Finish your own profile first.';
  end if;
  if not public.handle_available(v_handle) then raise exception 'That username is not available.'; end if;

  if v_category = 'venue' then
    if p_venue is null then raise exception 'Choose the venue.'; end if;
    if not public.can_access_venue(p_venue, array['owner', 'manager']) then
      raise exception 'You can only create a profile for a venue you own or manage.';
    end if;
    select v.org_id into v_org from public.site_venues v where v.id = p_venue;
    v_venue := p_venue;
  elsif v_category = 'event_group' and p_org is not null then
    if p_venue is not null then raise exception 'A venue only goes with a venue profile.'; end if;
    if not public.is_org_member(p_org, array['owner', 'organizer']) then
      raise exception 'You can only create a profile for a business you own or organize for.';
    end if;
    v_org := p_org;
  else
    if p_org is not null or p_venue is not null then raise exception 'This kind of profile does not belong to a venue business.'; end if;
    v_owner := v_uid;
    if (select count(*) from public.site_profiles s where s.user_id = v_uid and s.kind = 'business') >= 5 then
      raise exception 'You can have up to 5 business profiles.';
    end if;
  end if;

  begin
    insert into public.site_profiles (kind, user_id, org_id, venue_id, handle, display_name, category, bio, city, avatar_url)
    values ('business', v_owner, v_org, v_venue, v_handle, v_name, v_category, v_bio, v_city, v_avatar)
    returning id into v_id;
    insert into public.site_handles (handle, business_id) values (v_handle, v_id);
  exception when unique_violation then
    -- Another profile took the username, or this venue / business already has its profile.
    if v_venue is not null and exists (select 1 from public.site_profiles s where s.venue_id = v_venue) then
      raise exception 'This venue already has a profile.';
    elsif v_org is not null and v_venue is null and exists (select 1 from public.site_profiles s where s.org_id = v_org and s.venue_id is null) then
      raise exception 'This business already has an event group profile.';
    end if;
    raise exception 'That username is not available.';
  end;
  return public.profile_card(v_id, v_id);
end;
$$;

-- Edit a business profile. A photo or cover left out (null) stays; an empty one removes it.
create function public.profile_update_business(
  p_profile uuid,
  p_display_name text,
  p_bio text default null,
  p_city text default null,
  p_avatar_url text default null,
  p_cover_url text default null,
  p_social jsonb default '{}'::jsonb
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_name text := btrim(coalesce(p_display_name, ''));
  v_bio text := nullif(btrim(coalesce(p_bio, '')), '');
  v_city text := nullif(btrim(coalesce(p_city, '')), '');
begin
  perform public.profile_require_permission(p_profile, 'content');
  if not exists (select 1 from public.site_profiles s where s.id = p_profile and s.kind = 'business') then
    raise exception 'Edit your own details in your profile settings.';
  end if;
  if char_length(v_name) < 1 or char_length(v_name) > 100 then raise exception 'The name is required (100 characters at most).'; end if;
  if v_bio is not null and char_length(v_bio) > 280 then raise exception 'The description must be 280 characters or fewer.'; end if;
  if v_city is not null and char_length(v_city) > 80 then raise exception 'The city must be 80 characters or fewer.'; end if;
  if p_avatar_url is not null and btrim(p_avatar_url) <> '' and (btrim(p_avatar_url) !~ '^https://' or char_length(btrim(p_avatar_url)) > 500) then
    raise exception 'The photo must be an https link.';
  end if;
  if p_cover_url is not null and btrim(p_cover_url) <> '' and (btrim(p_cover_url) !~ '^https://' or char_length(btrim(p_cover_url)) > 500) then
    raise exception 'The cover must be an https link.';
  end if;

  update public.site_profiles s set
    display_name = v_name,
    bio = v_bio,
    city = v_city,
    avatar_url = case when p_avatar_url is null then s.avatar_url else nullif(btrim(p_avatar_url), '') end,
    cover_url = case when p_cover_url is null then s.cover_url else nullif(btrim(p_cover_url), '') end,
    social_links = public.clean_social_links(p_social)
  where s.id = p_profile;
  return public.profile_card(p_profile, p_profile);
end;
$$;

-- Every profile the caller may act as, their own first. Includes a suspended one, marked, so the owner can see why it is quiet.
create function public.profile_my_profiles()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  return coalesce((
    select jsonb_agg(public.profile_card(p.id, p.id) order by (p.kind = 'personal') desc, p.created_at, p.id)
    from public.site_profiles p
    where p.id in (select public.profile_my_ids())
  ), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Finding and viewing profiles
-- ---------------------------------------------------------------------------
-- One profile by username (p_handle) or by id, as seen by p_actor.
create function public.profile_get(p_actor uuid, p_handle text default null, p_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_id uuid := p_id;
  v_handle text := lower(btrim(coalesce(p_handle, '')));
begin
  perform public.profile_require_actor(p_actor);
  if v_id is null then
    if v_handle = '' then raise exception 'Say which profile.'; end if;
    select s.id into v_id
    from public.site_profiles s
    left join public.profiles pr on pr.id = s.user_id and s.kind = 'personal'
    where (s.kind = 'business' and s.handle = v_handle) or (s.kind = 'personal' and pr.username = v_handle);
  end if;
  if v_id is null or not (public.profile_visible(p_actor, v_id) or public.profile_is_mine(v_id)) then
    raise exception 'This profile isn''t available.';
  end if;
  return public.profile_card(p_actor, v_id);
end;
$$;

-- People and businesses whose username or name starts with the text.
create function public.profile_search(p_actor uuid, p_query text, p_limit int default 20)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_q text := lower(btrim(coalesce(p_query, '')));
  v_like text;
  v_limit int := least(greatest(coalesce(p_limit, 20), 1), 30);
begin
  perform public.profile_require_actor(p_actor);
  if char_length(v_q) < 2 then raise exception 'Type at least 2 letters.'; end if;
  if char_length(v_q) > 40 then raise exception 'That search is too long.'; end if;
  v_like := replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';

  return coalesce((
    select jsonb_agg(public.profile_card(p_actor, m.id) order by m.exact desc, m.followers desc, m.sort_name, m.id)
    from (
      select s.id,
             (coalesce(s.handle, pr.username) = v_q) as exact,
             (select count(*) from public.site_follows f where f.followed = s.id and f.status = 'active') as followers,
             lower(coalesce(s.display_name, pr.name, pr.username)) as sort_name
      from (
        select b.id from public.site_profiles b
        where b.kind = 'business' and (b.handle like v_like or lower(b.display_name) like v_like)
        union
        select x.id from public.profiles u
        join public.site_profiles x on x.user_id = u.id and x.kind = 'personal'
        where u.username like v_like or lower(u.name) like v_like
      ) c
      join public.site_profiles s on s.id = c.id
      left join public.profiles pr on pr.id = s.user_id and s.kind = 'personal'
      where s.status = 'active'
        and s.id <> p_actor
        and not public.profile_blocked_between(p_actor, s.id)
      order by (coalesce(s.handle, pr.username) = v_q) desc, lower(coalesce(s.display_name, pr.name, pr.username))
      limit v_limit
    ) m
  ), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. Following
-- ---------------------------------------------------------------------------
-- Follow (or ask to follow, when the profile is private) and unfollow. Returns the target as the actor now sees it.
create function public.follow_set(p_actor uuid, p_target uuid, p_follow boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_private boolean;
begin
  perform public.profile_require_actor(p_actor);
  if p_target is null or p_follow is null then raise exception 'Say which profile.'; end if;
  if p_target = p_actor or public.profile_is_mine(p_target) then raise exception 'You cannot follow your own profile.'; end if;

  if p_follow then
    if not public.feature_enabled('social') then raise exception 'Profiles are not open yet.'; end if;
    if not public.profile_visible(p_actor, p_target) then raise exception 'This profile isn''t available.'; end if;
    if exists (select 1 from public.site_follows f where f.follower = p_actor and f.followed = p_target) then
      return public.profile_card(p_actor, p_target);
    end if;
    if (select count(*) from public.site_follows f where f.follower = p_actor and f.created_at > now() - interval '1 hour') >= 200 then
      raise exception 'You are following people too quickly. Try again later.';
    end if;
    select s.privacy = 'private' into v_private from public.site_profiles s where s.id = p_target;
    insert into public.site_follows (follower, followed, status)
    values (p_actor, p_target, case when v_private then 'pending' else 'active' end)
    on conflict do nothing;
  else
    delete from public.site_follows where follower = p_actor and followed = p_target;
  end if;
  return public.profile_card(p_actor, p_target);
end;
$$;

-- The owner of a private profile answers a request ('accept' or 'decline') or removes a follower ('remove').
create function public.follow_respond(p_actor uuid, p_other uuid, p_action text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_action text := lower(btrim(coalesce(p_action, '')));
  n int;
begin
  perform public.profile_require_actor(p_actor);
  if p_other is null then raise exception 'Say which profile.'; end if;
  if v_action = 'accept' then
    update public.site_follows set status = 'active' where follower = p_other and followed = p_actor and status = 'pending';
    get diagnostics n = row_count;
    if n = 0 then raise exception 'There is no request from this profile.'; end if;
  elsif v_action = 'decline' then
    delete from public.site_follows where follower = p_other and followed = p_actor and status = 'pending';
    get diagnostics n = row_count;
    if n = 0 then raise exception 'There is no request from this profile.'; end if;
  elsif v_action = 'remove' then
    delete from public.site_follows where follower = p_other and followed = p_actor and status = 'active';
  else
    raise exception 'Choose accept, decline or remove.';
  end if;
  return jsonb_build_object(
    'followers', (select count(*) from public.site_follows f where f.followed = p_actor and f.status = 'active'),
    'requests', (select count(*) from public.site_follows f where f.followed = p_actor and f.status = 'pending')
  );
end;
$$;

-- Who is waiting for the actor to accept them, newest first.
create function public.follow_requests(p_actor uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.profile_card(p_actor, r.follower) || jsonb_build_object('requested_at', r.created_at) order by r.created_at desc)
    from (
      select f.follower, f.created_at
      from public.site_follows f
      join public.site_profiles s on s.id = f.follower and s.status = 'active'
      where f.followed = p_actor and f.status = 'pending' and not public.profile_blocked_between(p_actor, f.follower)
      order by f.created_at desc
      limit 100
    ) r
  ), '[]'::jsonb);
end;
$$;

-- A page of someone's followers (p_kind 'followers') or the profiles they follow ('following'), newest first. p_before is the 'followed_at' of the last row seen.
create function public.follow_list(p_actor uuid, p_profile uuid, p_kind text, p_limit int default 30, p_before timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if v_kind not in ('followers', 'following') then raise exception 'Choose followers or following.'; end if;
  if not (public.profile_visible(p_actor, p_profile) or public.profile_is_mine(p_profile)) then raise exception 'This profile isn''t available.'; end if;
  if not (public.profile_content_visible(p_actor, p_profile) or p_profile = p_actor) then
    raise exception 'Follow this profile to see its people.';
  end if;

  return coalesce((
    select jsonb_agg(public.profile_card(p_actor, r.other) || jsonb_build_object('followed_at', r.at) order by r.at desc)
    from (
      select case when v_kind = 'followers' then f.follower else f.followed end as other, f.created_at as at
      from public.site_follows f
      join public.site_profiles s on s.id = case when v_kind = 'followers' then f.follower else f.followed end and s.status = 'active'
      where f.status = 'active'
        and ((v_kind = 'followers' and f.followed = p_profile) or (v_kind = 'following' and f.follower = p_profile))
        and (p_before is null or f.created_at < p_before)
        and not public.profile_blocked_between(p_actor, s.id)
      order by f.created_at desc
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Blocking
-- ---------------------------------------------------------------------------
create function public.block_set(p_actor uuid, p_target uuid, p_blocked boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_ka uuid;
  v_kb uuid;
begin
  perform public.profile_require_actor(p_actor);
  if p_target is null or p_blocked is null then raise exception 'Say which profile.'; end if;
  if p_target = p_actor or public.profile_is_mine(p_target) then raise exception 'You cannot block your own profile.'; end if;
  if not exists (select 1 from public.site_profiles s where s.id = p_target) then raise exception 'This profile isn''t available.'; end if;

  v_ka := public.profile_key(p_actor);
  v_kb := public.profile_key(p_target);
  if p_blocked then
    insert into public.site_blocks (blocker, blocked, blocker_key, blocked_key) values (p_actor, p_target, v_ka, v_kb) on conflict do nothing;
    -- Every follow between the two PEOPLE goes, whichever of their profiles it was made with.
    delete from public.site_follows f
    where (f.follower in (select s.id from public.site_profiles s where s.id = v_ka or s.user_id = v_ka)
           and f.followed in (select s.id from public.site_profiles s where s.id = v_kb or s.user_id = v_kb))
       or (f.follower in (select s.id from public.site_profiles s where s.id = v_kb or s.user_id = v_kb)
           and f.followed in (select s.id from public.site_profiles s where s.id = v_ka or s.user_id = v_ka));
  else
    delete from public.site_blocks where blocker_key = v_ka and blocked_key = v_kb;
  end if;
  return jsonb_build_object('blocked', p_blocked);
end;
$$;

-- The profiles the actor has blocked, newest first (header only).
create function public.block_list(p_actor uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.profile_card(p_actor, b.blocked) || jsonb_build_object('blocked_at', b.created_at) order by b.created_at desc)
    from (
      -- One row for each blocked PERSON, whichever of the actor's profiles blocked them: the profile blocked first, so the list does not change when another of their profiles
      -- is blocked as well.
      select d.blocked, d.created_at
      from (select distinct on (x.blocked_key) x.blocked, x.created_at from public.site_blocks x
            where x.blocker_key = public.profile_key(p_actor) order by x.blocked_key, x.created_at) d
      order by d.created_at desc limit 200
    ) b
  ), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- 8. Who may call what
-- ---------------------------------------------------------------------------
revoke all on function
  public.handle_reserved(text), public.profile_is_owner(uuid), public.profile_is_mine(uuid), public.profile_has_permission(uuid, text), public.profile_can_act_as(uuid), public.profile_key(uuid), public.profile_blocked_between(uuid, uuid),
  public.profile_visible(uuid, uuid), public.profile_content_visible(uuid, uuid), public.profile_badge(uuid), public.profile_card(uuid, uuid), public.profile_require_actor(uuid), public.profile_require_permission(uuid, text),
  public.profile_clean_interests(text[]), public.profile_my_ids(),
  public.site_handles_follow_profile(),
  public.handle_available(text), public.profile_save_personal(text, text[]),
  public.profile_create_business(text, text, text, text, text, uuid, uuid, text),
  public.profile_update_business(uuid, text, text, text, text, text, jsonb), public.profile_my_profiles(),
  public.profile_get(uuid, text, uuid), public.profile_search(uuid, text, int),
  public.follow_set(uuid, uuid, boolean), public.follow_respond(uuid, uuid, text), public.follow_requests(uuid),
  public.follow_list(uuid, uuid, text, int, timestamptz),
  public.block_set(uuid, uuid, boolean), public.block_list(uuid)
from public, anon, authenticated;
grant execute on function
  public.handle_available(text), public.profile_save_personal(text, text[]),
  public.profile_create_business(text, text, text, text, text, uuid, uuid, text),
  public.profile_update_business(uuid, text, text, text, text, text, jsonb), public.profile_my_profiles(),
  public.profile_get(uuid, text, uuid), public.profile_search(uuid, text, int),
  public.follow_set(uuid, uuid, boolean), public.follow_respond(uuid, uuid, text), public.follow_requests(uuid),
  public.follow_list(uuid, uuid, text, int, timestamptz),
  public.block_set(uuid, uuid, boolean), public.block_list(uuid)
to authenticated, service_role;
commit;

-- ====================================================================================================
-- 20261102100000_social_posts
-- ====================================================================================================
begin;
-- Posts, reels, stories, comments, likes, saves and Members Only (customer app completion plan, M2; client plan pages 4 and 5).
--
--   * WHO SEES A POST is worked out from the viewer's CURRENT standing on every read, never from a stored list of viewers:
--       public    - everyone the author's profile is visible to (a public profile: anyone; a private one: its approved followers);
--       followers - people who follow the author now;
--       members   - people on the author's Members Only list who ALSO follow the author now. Taking someone off the list, or their unfollowing, ends
--                   their access at once. Nobody is told either way, and a post a person cannot see is simply absent (no lock, no count).
--     The author, and anyone who may act as the author, always sees their own. A blocked pair sees nothing of each other. A story is also hidden 24 hours
--     after it was posted. A suspended author's content is hidden.
--   * MEDIA is in a PRIVATE bucket (`social-media`). A file is readable only through a signed address that storage hands out when the same visibility rule
--     says the caller (as any profile they may act as) can see the post it belongs to; guessing a path reaches nothing. Files are uploaded into the folder of
--     the profile posting (`<profile id>/<name>`), BEFORE the post is made; post_create then checks each file really exists, is an image or a video as said,
--     and is within the size limits: images 10 MB, videos 100 MB (the bucket itself refuses more). Video length (60 s) is as the phone reports it: nothing here
--     opens the file. A file that never got a post is listed by social_media_orphans() for a clean-up job; deleting a post returns the files to remove.
--   * RULES AND SAFETY come first: nobody posts or comments before accepting the community rules (the text is written by BottlesUp in the CMS, and publishing a new version makes everyone accept again), text is
--     checked against a list of banned terms BottlesUp keeps, posting is slowed (20 an hour), commenting is slowed (20 a minute), and stories, reels and Members
--     Only each refuse until their feature switch (20261101100000) is on.
--   * Counts (likes, comments) are counted when read, from rows that still belong to active profiles.
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

-- ---------------------------------------------------------------------------
-- 1. The private media bucket
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('social-media', 'social-media', false, 104857600, array['image/jpeg', 'image/png', 'image/webp', 'video/mp4', 'video/quicktime'])
on conflict (id) do nothing;

-- The profile a file path belongs to (`<profile id>/<name>`), or null when the path is not of that shape.
create function public.social_media_profile(p_name text)
returns uuid
language sql
immutable
set search_path = public
as $$
  select case when p_name ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[A-Za-z0-9._-]{1,100}$' then split_part(p_name, '/', 1)::uuid end
$$;

-- May the caller put a file at this path? Only into the folder of a profile they may act as. (The storage policies call these two, so they are the only
-- ones callable by the app.)
create function public.social_media_can_add(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  return auth.uid() is not null and public.social_media_profile(p_name) is not null and public.profile_can_act_as(public.social_media_profile(p_name));
end;
$$;

-- ...and may the caller read it? Their own uploads, and the files of any post one of their profiles can see. (Written as plpgsql so this can come before the tables.)
create function public.social_media_visible(p_name text)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then return false; end if;
  if public.social_media_profile(p_name) is not null and public.profile_can_act_as(public.social_media_profile(p_name)) then return true; end if;
  return exists (
    select 1
    from public.site_post_media m
    where (m.storage_path = p_name or m.poster_path = p_name)
      and exists (
        select 1
        from public.profile_my_ids() as me(id)
        join public.site_profiles sp on sp.id = me.id and sp.status = 'active'
        where public.post_visible(me.id, m.post)
      )
  );
end;
$$;

create policy "social media readable by those who may see the post" on storage.objects
  for select to authenticated
  using (bucket_id = 'social-media' and public.social_media_visible(name));
create policy "profiles add their own social media" on storage.objects
  for insert to authenticated
  with check (bucket_id = 'social-media' and public.social_media_can_add(name));
create policy "profiles remove their own social media" on storage.objects
  for delete to authenticated
  using (bucket_id = 'social-media' and public.social_media_can_add(name));

-- ---------------------------------------------------------------------------
-- 2. Tables
-- ---------------------------------------------------------------------------
create table public.site_posts (
  id uuid primary key default gen_random_uuid(),
  author uuid not null references public.site_profiles (id) on delete cascade,
  kind text not null check (kind in ('post', 'reel', 'story')),
  caption text check (caption is null or char_length(caption) <= 2200),
  audience text not null default 'public' check (audience in ('public', 'followers', 'members')),
  comments_enabled boolean not null default true,
  status text not null default 'active' check (status in ('active', 'removed')),
  -- The moment it was written, so a page ordered by it has no ties.
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz,
  constraint site_posts_story_expiry check ((kind = 'story') = (expires_at is not null))
);
create index site_posts_author_idx on public.site_posts (author, created_at desc, id desc) where status = 'active';
create index site_posts_feed_idx on public.site_posts (created_at desc, id desc) where status = 'active' and kind in ('post', 'reel');
create index site_posts_story_idx on public.site_posts (expires_at) where kind = 'story';

create table public.site_post_media (
  id uuid primary key default gen_random_uuid(),
  post uuid not null references public.site_posts (id) on delete cascade,
  position smallint not null check (position between 0 and 9),
  media_type text not null check (media_type in ('image', 'video')),
  storage_path text not null unique check (char_length(storage_path) <= 200),
  poster_path text check (poster_path is null or char_length(poster_path) <= 200),
  width int check (width is null or width between 1 and 20000),
  height int check (height is null or height between 1 and 20000),
  duration_ms int check (duration_ms is null or duration_ms between 1 and 60000),
  bytes bigint check (bytes is null or bytes > 0),
  unique (post, position),
  constraint site_post_media_video_only check (media_type = 'video' or (poster_path is null and duration_ms is null))
);
create unique index site_post_media_poster_idx on public.site_post_media (poster_path) where poster_path is not null;

create table public.site_post_tags (
  id uuid primary key default gen_random_uuid(),
  post uuid not null references public.site_posts (id) on delete cascade,
  profile_id uuid references public.site_profiles (id) on delete cascade,
  event_id uuid references public.site_events (id) on delete cascade,
  venue_id uuid references public.site_venues (id) on delete cascade,
  check (num_nonnulls(profile_id, event_id, venue_id) = 1)
);
create unique index site_post_tags_profile_idx on public.site_post_tags (post, profile_id) where profile_id is not null;
create unique index site_post_tags_event_idx on public.site_post_tags (post, event_id) where event_id is not null;
create unique index site_post_tags_venue_idx on public.site_post_tags (post, venue_id) where venue_id is not null;
create index site_post_tags_target_idx on public.site_post_tags (profile_id) where profile_id is not null;

create table public.site_post_likes (
  post uuid not null references public.site_posts (id) on delete cascade,
  profile uuid not null references public.site_profiles (id) on delete cascade,
  created_at timestamptz not null default clock_timestamp(),
  primary key (post, profile)
);
create index site_post_likes_profile_idx on public.site_post_likes (profile, created_at desc);

create table public.site_post_saves (
  post uuid not null references public.site_posts (id) on delete cascade,
  profile uuid not null references public.site_profiles (id) on delete cascade,
  created_at timestamptz not null default clock_timestamp(),
  primary key (post, profile)
);
create index site_post_saves_profile_idx on public.site_post_saves (profile, created_at desc);

create table public.site_comments (
  id uuid primary key default gen_random_uuid(),
  post uuid not null references public.site_posts (id) on delete cascade,
  author uuid not null references public.site_profiles (id) on delete cascade,
  reply_to uuid references public.site_comments (id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 1000),
  status text not null default 'active' check (status in ('active', 'removed')),
  created_at timestamptz not null default clock_timestamp()
);
create index site_comments_post_idx on public.site_comments (post, created_at, id) where status = 'active';
create index site_comments_author_idx on public.site_comments (author, created_at desc);
create index site_comments_reply_idx on public.site_comments (reply_to) where reply_to is not null;

create table public.site_member_lists (
  owner uuid not null references public.site_profiles (id) on delete cascade,
  member uuid not null references public.site_profiles (id) on delete cascade,
  created_at timestamptz not null default clock_timestamp(),
  primary key (owner, member),
  check (owner <> member)
);
create index site_member_lists_member_idx on public.site_member_lists (member);

create table public.site_story_views (
  story uuid not null references public.site_posts (id) on delete cascade,
  viewer uuid not null references public.site_profiles (id) on delete cascade,
  viewed_at timestamptz not null default clock_timestamp(),
  primary key (story, viewer)
);

-- Words and phrases (letters, digits and spaces) that may not appear in a caption or a comment. BottlesUp keeps this list; it starts empty.
create table public.site_banned_terms (
  term text primary key check (term ~ '^[a-z0-9 ]{2,40}$')
);

-- The community rules, one row for each version BottlesUp has published (the text is written in the CMS). Until a first one is published the current version is 1 and
-- there is no text: the app shows its own draft. Publishing a new version makes everyone accept again before they post.
create table public.site_community_rules (
  version int primary key check (version >= 2),
  body text not null check (char_length(btrim(body)) between 20 and 8000),
  published_at timestamptz not null default now(),
  published_by uuid references auth.users (id) on delete set null
);

-- Each time a person asks for caption ideas (to keep it to a sensible number a day: every request costs BottlesUp money).
create table public.site_ai_caption_uses (
  id bigint generated always as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at timestamptz not null default now()
);
create index site_ai_caption_uses_user_idx on public.site_ai_caption_uses (user_id, created_at desc);

-- Who has accepted which version of the community rules.
create table public.site_rules_acceptance (
  user_id uuid primary key references auth.users (id) on delete cascade,
  version int not null,
  accepted_at timestamptz not null default now()
);

alter table public.site_posts enable row level security;
alter table public.site_post_media enable row level security;
alter table public.site_post_tags enable row level security;
alter table public.site_post_likes enable row level security;
alter table public.site_post_saves enable row level security;
alter table public.site_comments enable row level security;
alter table public.site_member_lists enable row level security;
alter table public.site_story_views enable row level security;
alter table public.site_banned_terms enable row level security;
alter table public.site_community_rules enable row level security;
alter table public.site_ai_caption_uses enable row level security;
alter table public.site_rules_acceptance enable row level security;
revoke all on table
  public.site_posts, public.site_post_media, public.site_post_tags, public.site_post_likes, public.site_post_saves, public.site_comments,
  public.site_member_lists, public.site_story_views, public.site_banned_terms, public.site_community_rules, public.site_ai_caption_uses, public.site_rules_acceptance
from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. Internal helpers (the app cannot call these)
-- ---------------------------------------------------------------------------
-- May the profile p_viewer see this post right now? (See the header for the rules.)
create function public.post_visible(p_viewer uuid, p_post uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.site_posts p
    join public.site_profiles a on a.id = p.author
    where p.id = p_post
      and p.status = 'active'
      and a.status = 'active'
      and (p.kind <> 'story' or p.expires_at > now())
      and (
        public.profile_is_mine(p.author)
        or (
          p_viewer is not null
          and not public.profile_blocked_between(p_viewer, p.author)
          and (
            (p.audience = 'public' and public.profile_content_visible(p_viewer, p.author))
            or (p.audience = 'followers'
                and exists (select 1 from public.site_follows f where f.follower = p_viewer and f.followed = p.author and f.status = 'active'))
            or (p.audience = 'members'
                and exists (select 1 from public.site_follows f where f.follower = p_viewer and f.followed = p.author and f.status = 'active')
                and exists (select 1 from public.site_member_lists l where l.owner = p.author and l.member = p_viewer))
          )
        )
      )
  )
$$;

-- A profile in a feed, comment or tag: enough to show a name, a picture and a tick.
create function public.profile_mini(p_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', p.id,
    'kind', p.kind,
    'handle', case p.kind when 'personal' then pr.username else p.handle end,
    'display_name', case p.kind when 'personal' then coalesce(nullif(btrim(pr.name), ''), pr.username) else p.display_name end,
    'category', p.category,
    'avatar_url', case p.kind when 'personal' then pr.avatar_url else p.avatar_url end,
    'verified', (public.profile_badge(p.id) ->> 'verified')::boolean,
    'rank', public.profile_badge(p.id) -> 'rank',
    'privacy', p.privacy
  )
  from public.site_profiles p
  left join public.profiles pr on pr.id = p.user_id and p.kind = 'personal'
  where p.id = p_id
$$;

-- One post as the app shows it, for the profile p_viewer. Does not check that the viewer may see it: the callers do.
create function public.post_card(p_viewer uuid, p_post uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  p public.site_posts;
begin
  select * into p from public.site_posts where id = p_post;
  if not found then return null; end if;
  return jsonb_build_object(
    'id', p.id,
    'kind', p.kind,
    'caption', p.caption,
    'audience', p.audience,
    'comments_enabled', p.comments_enabled,
    'created_at', p.created_at,
    'expires_at', p.expires_at,
    'author', public.profile_mini(p.author),
    'media', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', m.id, 'position', m.position, 'type', m.media_type, 'path', m.storage_path, 'poster_path', m.poster_path,
        'width', m.width, 'height', m.height, 'duration_ms', m.duration_ms) order by m.position)
      from public.site_post_media m where m.post = p.id), '[]'::jsonb),
    'tags', coalesce((
      select jsonb_agg(t.tag order by t.ord)
      from (
        select row_number() over (order by x.id) as ord,
               case
                 when x.profile_id is not null then jsonb_build_object('kind', 'profile', 'id', x.profile_id, 'profile', public.profile_mini(x.profile_id))
                 when x.event_id is not null then jsonb_build_object('kind', 'event', 'id', x.event_id, 'name', e.title)
                 else jsonb_build_object('kind', 'venue', 'id', x.venue_id, 'name', v.name)
               end as tag
        from public.site_post_tags x
        left join public.site_events e on e.id = x.event_id and e.status = 'published'
        left join public.site_venues v on v.id = x.venue_id and v.status = 'published'
        where x.post = p.id
          and (
            (x.profile_id is not null and public.profile_visible(p_viewer, x.profile_id))
            or (x.event_id is not null and e.id is not null)
            or (x.venue_id is not null and v.id is not null)
          )
      ) t), '[]'::jsonb),
    'likes', (select count(*) from public.site_post_likes l join public.site_profiles s on s.id = l.profile and s.status = 'active' where l.post = p.id),
    'comments', (select count(*) from public.site_comments c join public.site_profiles s on s.id = c.author and s.status = 'active' where c.post = p.id and c.status = 'active'),
    'liked', p_viewer is not null and exists (select 1 from public.site_post_likes l where l.post = p.id and l.profile = p_viewer),
    'saved', p_viewer is not null and exists (select 1 from public.site_post_saves sv where sv.post = p.id and sv.profile = p_viewer),
    'is_mine', public.profile_is_mine(p.author)
  );
end;
$$;

-- The community rules: what version is current, and has the caller accepted it?
create function public.social_rules_version()
returns int
language sql
stable
security definer
set search_path = public
as $$ select coalesce((select max(r.version) from public.site_community_rules r), 1) $$;

create function public.social_require_rules()
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not exists (select 1 from public.site_rules_acceptance a where a.user_id = auth.uid() and a.version >= public.social_rules_version()) then
    raise exception 'Read and accept the community rules first.';
  end if;
end;
$$;

-- Is this text free of every banned term?
create function public.social_text_ok(p_text text)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select not exists (
    select 1 from public.site_banned_terms t
    where lower(coalesce(p_text, '')) ~ ('(^|[^a-z0-9])' || t.term || '($|[^a-z0-9])')
  )
$$;

-- A number out of a json field that may hold anything.
create function public.social_json_int(p_value jsonb, p_key text)
returns int
language sql
immutable
set search_path = public
as $$
  select case when (p_value ->> p_key) ~ '^[0-9]{1,9}$' then (p_value ->> p_key)::int end
$$;

-- ---------------------------------------------------------------------------
-- 4. The community rules and the banned terms
-- ---------------------------------------------------------------------------
create function public.rules_status()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  return jsonb_build_object(
    'version', public.social_rules_version(),
    'accepted', exists (select 1 from public.site_rules_acceptance a where a.user_id = auth.uid() and a.version >= public.social_rules_version())
  );
end;
$$;

create function public.rules_accept(p_version int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if p_version is distinct from public.social_rules_version() then raise exception 'The community rules have changed. Read them again.'; end if;
  insert into public.site_rules_acceptance (user_id, version) values (auth.uid(), p_version)
  on conflict (user_id) do update set version = excluded.version, accepted_at = now();
  return public.rules_status();
end;
$$;

-- The rules as they stand: the version everyone must have accepted and the text (null until BottlesUp has published one). Anyone may read them, signed in or not.
create function public.rules_current()
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'version', public.social_rules_version(),
    'body', (select r.body from public.site_community_rules r order by r.version desc limit 1)
  )
$$;

-- A BottlesUp admin publishes new rules. It becomes the next version, so everyone accepts again before they post, comment or send.
create function public.cms_publish_rules(p_body text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text := btrim(coalesce(p_body, ''));
  v_version int;
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can change this.'; end if;
  if char_length(v_body) < 20 or char_length(v_body) > 8000 then raise exception 'The rules need between 20 and 8000 characters.'; end if;
  v_version := public.social_rules_version() + 1;
  insert into public.site_community_rules (version, body, published_by) values (v_version, v_body, auth.uid());
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'rules_published', 'community_rules', v_version::text,
          jsonb_build_object('version', v_version, 'characters', char_length(v_body)));
  return public.rules_current();
end;
$$;

-- The edge function `suggest-caption` calls this AS the person, before it asks the model for anything: caption ideas must be switched on, the person must have accepted the
-- community rules, and at most 20 requests a day. One request is counted here; the function then calls the model. Answers how many are left today.
create function public.ai_caption_begin()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_used int;
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if not public.feature_enabled('social') or not public.feature_enabled('ai_captions') then raise exception 'Caption ideas are not open yet.'; end if;
  perform public.social_require_rules();
  select count(*) into v_used from public.site_ai_caption_uses u where u.user_id = auth.uid() and u.created_at > now() - interval '1 day';
  if v_used >= 20 then raise exception 'You have used all of today''s caption ideas. Try again tomorrow.'; end if;
  insert into public.site_ai_caption_uses (user_id) values (auth.uid());
  return jsonb_build_object('left', 19 - v_used);
end;
$$;

-- A BottlesUp admin adds or removes a banned term.
create function public.cms_set_banned_term(p_term text, p_banned boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_term text := lower(regexp_replace(btrim(coalesce(p_term, '')), '\s+', ' ', 'g'));
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can change this.'; end if;
  if v_term !~ '^[a-z0-9 ]{2,40}$' then raise exception 'A banned term is 2 to 40 letters, numbers or spaces.'; end if;
  if p_banned is null then raise exception 'Choose add or remove.'; end if;
  if p_banned then
    insert into public.site_banned_terms (term) values (v_term) on conflict do nothing;
  else
    delete from public.site_banned_terms where term = v_term;
  end if;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), case when p_banned then 'banned_term_added' else 'banned_term_removed' end, 'banned_term', v_term, '{}'::jsonb);
  return jsonb_build_object('terms', (select count(*) from public.site_banned_terms));
end;
$$;

create function public.cms_list_banned_terms()
returns table (term text)
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  return query select t.term from public.site_banned_terms t order by t.term;
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Making, changing and removing a post
-- ---------------------------------------------------------------------------
-- Make a post, a reel or a story. p_media is a list of {path, type: 'image'|'video', width, height, duration_ms, poster_path}, every file already uploaded into
-- the posting profile's folder; p_tags a list of {kind: 'profile'|'event'|'venue', id}.
create function public.post_create(
  p_actor uuid,
  p_kind text,
  p_caption text,
  p_audience text,
  p_media jsonb,
  p_tags jsonb default '[]'::jsonb,
  p_comments_enabled boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_aud text := lower(btrim(coalesce(p_audience, '')));
  v_caption text := nullif(btrim(coalesce(p_caption, '')), '');
  v_post uuid;
  v_item jsonb;
  v_pos int := 0;
  v_type text;
  v_path text;
  v_poster text;
  v_size bigint;
  v_mime text;
  v_dur int;
  v_images int := 0;
  v_videos int := 0;
  v_tag jsonb;
  v_tag_kind text;
  v_tag_id uuid;
  v_tag_text text;
  v_seen text[] := '{}';
begin
  perform public.profile_require_permission(p_actor, 'content');
  perform public.social_require_rules();
  if v_kind not in ('post', 'reel', 'story') then raise exception 'Choose post, reel or story.'; end if;
  if not public.feature_enabled('social') then raise exception 'Posting is not open yet.'; end if;
  if v_kind = 'reel' and not public.feature_enabled('reels') then raise exception 'Reels are not open yet.'; end if;
  if v_kind = 'story' and not public.feature_enabled('stories') then raise exception 'Stories are not open yet.'; end if;
  if v_aud not in ('public', 'followers', 'members') then raise exception 'Choose who can see this.'; end if;
  if v_aud = 'members' and not public.feature_enabled('members_only') then raise exception 'Members Only is not open yet.'; end if;
  if p_comments_enabled is null then raise exception 'Choose whether people can comment.'; end if;
  if v_caption is not null and char_length(v_caption) > 2200 then raise exception 'The caption can be 2200 characters at most.'; end if;
  if not public.social_text_ok(v_caption) then raise exception 'That text goes against our community rules.'; end if;
  if (select count(*) from public.site_posts x where x.author = p_actor and x.created_at > now() - interval '1 hour') >= 20 then
    raise exception 'You are posting too quickly. Try again later.';
  end if;
  if p_media is null or jsonb_typeof(p_media) <> 'array' or jsonb_array_length(p_media) = 0 then raise exception 'Add a photo or a video.'; end if;
  if jsonb_array_length(p_media) > 10 then raise exception 'You can add up to 10 photos.'; end if;

  insert into public.site_posts (author, kind, caption, audience, comments_enabled, expires_at)
  values (p_actor, v_kind, v_caption, v_aud, p_comments_enabled, case when v_kind = 'story' then now() + interval '24 hours' end)
  returning id into v_post;

  for v_item in select e.value from jsonb_array_elements(p_media) e loop
    if jsonb_typeof(v_item) <> 'object' then raise exception 'Something is wrong with that photo or video.'; end if;
    v_type := v_item ->> 'type';
    v_path := v_item ->> 'path';
    v_poster := nullif(v_item ->> 'poster_path', '');
    if v_type not in ('image', 'video') or v_path is null then raise exception 'Something is wrong with that photo or video.'; end if;
    if public.social_media_profile(v_path) is distinct from p_actor then raise exception 'Something is wrong with that photo or video.'; end if;

    select (o.metadata ->> 'size')::bigint, o.metadata ->> 'mimetype' into v_size, v_mime
    from storage.objects o where o.bucket_id = 'social-media' and o.name = v_path;
    if not found then raise exception 'That photo or video did not finish uploading. Try again.'; end if;
    if v_type = 'image' then
      if v_mime is null or v_mime not like 'image/%' then raise exception 'Something is wrong with that photo.'; end if;
      if v_size is null or v_size > 10485760 then raise exception 'A photo can be 10 MB at most.'; end if;
      v_images := v_images + 1;
      v_dur := null;
      v_poster := null;
    else
      if v_mime is null or v_mime not like 'video/%' then raise exception 'Something is wrong with that video.'; end if;
      if v_size is null or v_size > 104857600 then raise exception 'A video can be 100 MB at most.'; end if;
      v_dur := public.social_json_int(v_item, 'duration_ms');
      if v_dur is null or v_dur < 1 or v_dur > 60000 then raise exception 'A video can be up to 60 seconds.'; end if;
      v_videos := v_videos + 1;
      if v_poster is not null then
        if public.social_media_profile(v_poster) is distinct from p_actor then raise exception 'Something is wrong with that video.'; end if;
        if not exists (
          select 1 from storage.objects o
          where o.bucket_id = 'social-media' and o.name = v_poster and o.metadata ->> 'mimetype' like 'image/%' and (o.metadata ->> 'size')::bigint <= 10485760
        ) then
          raise exception 'Something is wrong with that video.';
        end if;
      end if;
    end if;

    begin
      insert into public.site_post_media (post, position, media_type, storage_path, poster_path, width, height, duration_ms, bytes)
      values (v_post, v_pos, v_type, v_path, v_poster, public.social_json_int(v_item, 'width'), public.social_json_int(v_item, 'height'), v_dur, v_size);
    exception when unique_violation then
      raise exception 'That photo or video is already in a post.';
    when check_violation then
      raise exception 'Something is wrong with that photo or video.';
    end;
    v_pos := v_pos + 1;
  end loop;

  if v_kind = 'post' and (v_videos > 0 or v_images < 1) then raise exception 'A post is 1 to 10 photos. Use a reel for a video.'; end if;
  if v_kind = 'reel' and (v_videos <> 1 or v_images <> 0) then raise exception 'A reel is one video.'; end if;
  if v_kind = 'story' and v_images + v_videos <> 1 then raise exception 'A story is one photo or one video.'; end if;

  if p_tags is not null and jsonb_typeof(p_tags) <> 'array' then raise exception 'Something is wrong with the tags.'; end if;
  if jsonb_array_length(coalesce(p_tags, '[]'::jsonb)) > 10 then raise exception 'You can tag up to 10.'; end if;
  for v_tag in select e.value from jsonb_array_elements(coalesce(p_tags, '[]'::jsonb)) e loop
    if jsonb_typeof(v_tag) <> 'object' then raise exception 'Something is wrong with the tags.'; end if;
    v_tag_kind := v_tag ->> 'kind';
    v_tag_text := v_tag ->> 'id';
    if v_tag_kind not in ('profile', 'event', 'venue') or v_tag_text is null
       or v_tag_text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception 'Something is wrong with the tags.';
    end if;
    v_tag_id := v_tag_text::uuid;
    if (v_tag_kind || ':' || v_tag_text) = any (v_seen) then raise exception 'You tagged the same one twice.'; end if;
    v_seen := v_seen || (v_tag_kind || ':' || v_tag_text);
    if v_tag_kind = 'profile' then
      if v_tag_id = p_actor or public.profile_is_mine(v_tag_id) or not public.profile_visible(p_actor, v_tag_id) then raise exception 'You cannot tag that profile.'; end if;
      insert into public.site_post_tags (post, profile_id) values (v_post, v_tag_id);
    elsif v_tag_kind = 'event' then
      if not exists (select 1 from public.site_events e where e.id = v_tag_id and e.status = 'published') then raise exception 'You cannot tag that event.'; end if;
      insert into public.site_post_tags (post, event_id) values (v_post, v_tag_id);
    else
      if not exists (select 1 from public.site_venues v where v.id = v_tag_id and v.status = 'published') then raise exception 'You cannot tag that venue.'; end if;
      insert into public.site_post_tags (post, venue_id) values (v_post, v_tag_id);
    end if;
  end loop;

  return public.post_card(p_actor, v_post);
end;
$$;

-- Change the words, who can see it, or whether people can comment. The photos and tags stay.
create function public.post_edit(p_actor uuid, p_post uuid, p_caption text, p_audience text, p_comments_enabled boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_author uuid;
  v_aud text := lower(btrim(coalesce(p_audience, '')));
  v_caption text := nullif(btrim(coalesce(p_caption, '')), '');
begin
  perform public.profile_require_actor(p_actor);
  select p.author into v_author from public.site_posts p where p.id = p_post and p.status = 'active';
  if v_author is null or not public.profile_can_act_as(v_author) then raise exception 'You can only change your own posts.'; end if;
  if v_aud not in ('public', 'followers', 'members') then raise exception 'Choose who can see this.'; end if;
  if v_aud = 'members' and not public.feature_enabled('members_only') then raise exception 'Members Only is not open yet.'; end if;
  if p_comments_enabled is null then raise exception 'Choose whether people can comment.'; end if;
  if v_caption is not null and char_length(v_caption) > 2200 then raise exception 'The caption can be 2200 characters at most.'; end if;
  if not public.social_text_ok(v_caption) then raise exception 'That text goes against our community rules.'; end if;
  update public.site_posts set caption = v_caption, audience = v_aud, comments_enabled = p_comments_enabled where id = p_post;
  return public.post_card(p_actor, p_post);
end;
$$;

-- Delete a post. Answers the files that belonged to it, for the app to remove from storage.
create function public.post_delete(p_actor uuid, p_post uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_author uuid;
  v_paths jsonb;
begin
  perform public.profile_require_actor(p_actor);
  select p.author into v_author from public.site_posts p where p.id = p_post;
  if v_author is null or not public.profile_can_act_as(v_author) then raise exception 'You can only delete your own posts.'; end if;
  select coalesce(jsonb_agg(x.path), '[]'::jsonb) into v_paths
  from (
    select m.storage_path as path from public.site_post_media m where m.post = p_post
    union all
    select m.poster_path from public.site_post_media m where m.post = p_post and m.poster_path is not null
  ) x;
  delete from public.site_posts where id = p_post;
  return v_paths;
end;
$$;

-- One post, if the profile may see it.
create function public.post_get(p_actor uuid, p_post uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_post is null or not public.post_visible(p_actor, p_post) then raise exception 'This post isn''t available.'; end if;
  return public.post_card(p_actor, p_post);
end;
$$;

-- A tagged profile takes its own tag off a post.
create function public.post_untag(p_actor uuid, p_post uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  delete from public.site_post_tags where post = p_post and profile_id = p_actor;
  return jsonb_build_object('untagged', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. Reading: a profile's posts, the home feed, reels, stories
-- ---------------------------------------------------------------------------
-- A profile's posts and reels (not stories) that p_actor may see, newest first, with how many there are. p_kind 'post' or 'reel' narrows it.
create function public.profile_posts(p_actor uuid, p_profile uuid, p_kind text default null, p_limit int default 30, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_kind text := lower(btrim(coalesce(p_kind, '')));
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if v_kind not in ('', 'post', 'reel') then raise exception 'Choose posts or reels.'; end if;
  if not (public.profile_visible(p_actor, p_profile) or public.profile_is_mine(p_profile)) then raise exception 'This profile isn''t available.'; end if;
  if not (public.profile_content_visible(p_actor, p_profile) or public.profile_is_mine(p_profile)) then raise exception 'Follow this profile to see its posts.'; end if;
  return jsonb_build_object(
    'total', (select count(*) from public.site_posts p
              where p.author = p_profile and p.kind in ('post', 'reel') and p.status = 'active' and (v_kind = '' or p.kind = v_kind) and public.post_visible(p_actor, p.id)),
    'items', coalesce((
      select jsonb_agg(public.post_card(p_actor, r.id) order by r.created_at desc, r.id desc)
      from (
        select p.id, p.created_at
        from public.site_posts p
        where p.author = p_profile and p.kind in ('post', 'reel') and p.status = 'active' and (v_kind = '' or p.kind = v_kind)
          and (p_before is null or (p.created_at, p.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
          and public.post_visible(p_actor, p.id)
        order by p.created_at desc, p.id desc
        limit v_limit
      ) r
    ), '[]'::jsonb)
  );
end;
$$;

-- The home feed: posts and reels from the profiles p_actor follows, and its own, newest first. Page with the created_at and id of the last one seen.
create function public.feed_home(p_actor uuid, p_limit int default 20, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 20), 1), 40);
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.post_card(p_actor, r.id) order by r.created_at desc, r.id desc)
    from (
      select p.id, p.created_at
      from public.site_posts p
      where p.kind in ('post', 'reel') and p.status = 'active'
        and (p.author = p_actor or p.author in (select f.followed from public.site_follows f where f.follower = p_actor and f.status = 'active'))
        and (p_before is null or (p.created_at, p.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        and public.post_visible(p_actor, p.id)
      order by p.created_at desc, p.id desc
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- A few popular public posts from profiles p_actor does not follow, from the last two weeks: more likes and comments first. No machine ranking beyond that.
create function public.feed_suggested(p_actor uuid, p_limit int default 10)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 10), 1), 20);
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.post_card(p_actor, r.id) order by r.score desc, r.created_at desc, r.id desc)
    from (
      select p.id, p.created_at,
             (select count(*) from public.site_post_likes l where l.post = p.id)
             + 2 * (select count(*) from public.site_comments c where c.post = p.id and c.status = 'active') as score
      from public.site_posts p
      where p.kind in ('post', 'reel') and p.status = 'active' and p.audience = 'public'
        and p.created_at > now() - interval '14 days'
        and p.author <> p_actor
        and not public.profile_is_mine(p.author)
        and p.author not in (select f.followed from public.site_follows f where f.follower = p_actor)
        and public.post_visible(p_actor, p.id)
      order by score desc, p.created_at desc, p.id desc
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- Reels from anyone p_actor may see, newest first, for the reels viewer.
create function public.feed_reels(p_actor uuid, p_limit int default 10, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 10), 1), 20);
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.post_card(p_actor, r.id) order by r.created_at desc, r.id desc)
    from (
      select p.id, p.created_at
      from public.site_posts p
      where p.kind = 'reel' and p.status = 'active'
        and (p_before is null or (p.created_at, p.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        and public.post_visible(p_actor, p.id)
      order by p.created_at desc, p.id desc
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- The row of stories: p_actor's own and those of the profiles it follows, with a story still up that it may see. Own first, then unseen, then newest.
-- members_only is true when any of them is for the author's Members Only list (the app draws the orange ring).
create function public.story_rail(p_actor uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
             'profile', public.profile_mini(g.author), 'latest_at', g.latest, 'unseen', g.unseen, 'members_only', g.members_only, 'count', g.n, 'is_mine', g.author = p_actor)
           order by (g.author = p_actor) desc, g.unseen desc, g.latest desc, g.author)
    from (
      select s.author, max(s.created_at) as latest, count(*) as n,
             bool_or(s.audience = 'members') as members_only,
             bool_or(s.author <> p_actor and not exists (select 1 from public.site_story_views v where v.story = s.id and v.viewer = p_actor)) as unseen
      from public.site_posts s
      where s.kind = 'story' and s.status = 'active' and s.expires_at > now()
        and (s.author = p_actor or s.author in (select f.followed from public.site_follows f where f.follower = p_actor and f.status = 'active'))
        and public.post_visible(p_actor, s.id)
      group by s.author
      order by max(s.created_at) desc
      limit 60
    ) g
  ), '[]'::jsonb);
end;
$$;

-- One profile's stories that are up and that p_actor may see, oldest first (the order they are watched in).
create function public.stories_of(p_actor uuid, p_profile uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not (public.profile_visible(p_actor, p_profile) or public.profile_is_mine(p_profile)) then raise exception 'This profile isn''t available.'; end if;
  return coalesce((
    select jsonb_agg(public.post_card(p_actor, r.id) || jsonb_build_object('seen', exists (select 1 from public.site_story_views v where v.story = r.id and v.viewer = p_actor))
                     order by r.created_at, r.id)
    from (
      select s.id, s.created_at from public.site_posts s
      where s.author = p_profile and s.kind = 'story' and s.status = 'active' and s.expires_at > now() and public.post_visible(p_actor, s.id)
      order by s.created_at, s.id
      limit 50
    ) r
  ), '[]'::jsonb);
end;
$$;

-- p_actor has watched a story. Nobody is told; this only turns the ring grey for them.
create function public.story_seen(p_actor uuid, p_story uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not exists (select 1 from public.site_posts s where s.id = p_story and s.kind = 'story') or not public.post_visible(p_actor, p_story) then
    raise exception 'This story isn''t available.';
  end if;
  insert into public.site_story_views (story, viewer) values (p_story, p_actor) on conflict do nothing;
  return jsonb_build_object('seen', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Likes, saves and comments
-- ---------------------------------------------------------------------------
create function public.post_like(p_actor uuid, p_post uuid, p_liked boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_liked is null then raise exception 'Choose like or unlike.'; end if;
  if p_liked then
    if not public.feature_enabled('social') then raise exception 'Posting is not open yet.'; end if;
    if p_post is null or not public.post_visible(p_actor, p_post) then raise exception 'This post isn''t available.'; end if;
    insert into public.site_post_likes (post, profile) values (p_post, p_actor) on conflict do nothing;
  else
    delete from public.site_post_likes where post = p_post and profile = p_actor;
  end if;
  return jsonb_build_object(
    'liked', p_liked,
    'likes', (select count(*) from public.site_post_likes l join public.site_profiles s on s.id = l.profile and s.status = 'active' where l.post = p_post)
  );
end;
$$;

create function public.post_save(p_actor uuid, p_post uuid, p_saved boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_saved is null then raise exception 'Choose save or unsave.'; end if;
  if p_saved then
    if not public.feature_enabled('social') then raise exception 'Posting is not open yet.'; end if;
    if p_post is null or not public.post_visible(p_actor, p_post) then raise exception 'This post isn''t available.'; end if;
    insert into public.site_post_saves (post, profile) values (p_post, p_actor) on conflict do nothing;
  else
    delete from public.site_post_saves where post = p_post and profile = p_actor;
  end if;
  return jsonb_build_object('saved', p_saved);
end;
$$;

-- What p_actor saved, newest save first, that it can still see. p_before is the time of the last save seen.
create function public.saved_posts(p_actor uuid, p_limit int default 30, p_before timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.post_card(p_actor, r.post) || jsonb_build_object('saved_at', r.created_at) order by r.created_at desc, r.post desc)
    from (
      select sv.post, sv.created_at
      from public.site_post_saves sv
      where sv.profile = p_actor and (p_before is null or sv.created_at < p_before) and public.post_visible(p_actor, sv.post)
      order by sv.created_at desc, sv.post desc
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- One comment as the app shows it.
create function public.comment_card(p_viewer uuid, p_comment uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', c.id,
    'post', c.post,
    'reply_to', c.reply_to,
    'body', c.body,
    'created_at', c.created_at,
    'author', public.profile_mini(c.author),
    'replies', (select count(*) from public.site_comments r join public.site_profiles s on s.id = r.author and s.status = 'active'
                where r.reply_to = c.id and r.status = 'active' and not public.profile_blocked_between(p_viewer, r.author)),
    'is_mine', public.profile_is_mine(c.author),
    'can_delete', public.profile_is_mine(c.author) or public.profile_is_mine(p.author)
  )
  from public.site_comments c
  join public.site_posts p on p.id = c.post
  where c.id = p_comment
$$;

-- Add a comment (or a reply to a top-level comment) to a post p_actor can see.
create function public.comment_add(p_actor uuid, p_post uuid, p_body text, p_reply_to uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text := btrim(coalesce(p_body, ''));
  v_comments_on boolean;
  v_id uuid;
begin
  perform public.profile_require_actor(p_actor);
  perform public.social_require_rules();
  if not public.feature_enabled('social') then raise exception 'Posting is not open yet.'; end if;
  if p_post is null or not public.post_visible(p_actor, p_post) then raise exception 'This post isn''t available.'; end if;
  select s.comments_enabled into v_comments_on from public.site_posts s where s.id = p_post;
  if not v_comments_on then raise exception 'Comments are turned off for this post.'; end if;
  if char_length(v_body) < 1 then raise exception 'Write something first.'; end if;
  if char_length(v_body) > 1000 then raise exception 'A comment can be 1000 characters at most.'; end if;
  if not public.social_text_ok(v_body) then raise exception 'That text goes against our community rules.'; end if;
  if p_reply_to is not null and not exists (select 1 from public.site_comments c where c.id = p_reply_to and c.post = p_post and c.reply_to is null and c.status = 'active') then
    raise exception 'That comment is not there any more.';
  end if;
  if (select count(*) from public.site_comments c where c.author = p_actor and c.created_at > now() - interval '1 minute') >= 20 then
    raise exception 'You are commenting too quickly. Try again in a moment.';
  end if;
  insert into public.site_comments (post, author, reply_to, body) values (p_post, p_actor, p_reply_to, v_body) returning id into v_id;
  return public.comment_card(p_actor, v_id);
end;
$$;

-- A page of comments on a post, oldest first: the top-level ones, or the replies to p_parent. p_after is the created_at of the last one seen.
create function public.comment_list(p_actor uuid, p_post uuid, p_parent uuid default null, p_limit int default 30, p_after timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if p_post is null or not public.post_visible(p_actor, p_post) then raise exception 'This post isn''t available.'; end if;
  return coalesce((
    select jsonb_agg(public.comment_card(p_actor, r.id) order by r.created_at, r.id)
    from (
      select c.id, c.created_at
      from public.site_comments c
      join public.site_profiles s on s.id = c.author and s.status = 'active'
      where c.post = p_post and c.status = 'active'
        and ((p_parent is null and c.reply_to is null) or c.reply_to = p_parent)
        and (p_after is null or c.created_at > p_after)
        and not public.profile_blocked_between(p_actor, c.author)
      order by c.created_at, c.id
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- Delete a comment: its writer, or whoever may act as the post's author.
create function public.comment_delete(p_actor uuid, p_comment uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_author uuid;
  v_post_author uuid;
begin
  perform public.profile_require_actor(p_actor);
  select c.author, p.author into v_author, v_post_author
  from public.site_comments c join public.site_posts p on p.id = c.post where c.id = p_comment;
  if v_author is null or not (public.profile_can_act_as(v_author) or public.profile_can_act_as(v_post_author)) then
    raise exception 'You can only delete your own comments, or comments on your own posts.';
  end if;
  delete from public.site_comments where id = p_comment;
  return jsonb_build_object('deleted', true);
end;
$$;

-- ---------------------------------------------------------------------------
-- 8. Members Only
-- ---------------------------------------------------------------------------
-- The people on p_actor's Members Only list, newest first. still_following is false for someone who has since unfollowed: they are on the list but see nothing.
create function public.members_list(p_actor uuid, p_limit int default 100, p_before timestamptz default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 100), 1), 200);
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(public.profile_mini(r.member) || jsonb_build_object(
             'added_at', r.created_at,
             'still_following', exists (select 1 from public.site_follows f where f.follower = r.member and f.followed = p_actor and f.status = 'active'))
           order by r.created_at desc, r.member)
    from (
      select l.member, l.created_at
      from public.site_member_lists l
      join public.site_profiles s on s.id = l.member and s.status = 'active'
      where l.owner = p_actor and (p_before is null or l.created_at < p_before)
      order by l.created_at desc, l.member
      limit v_limit
    ) r
  ), '[]'::jsonb);
end;
$$;

-- Put someone on the list (they must follow p_actor already) or take them off.
create function public.members_set(p_actor uuid, p_member uuid, p_in boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_member is null or p_in is null then raise exception 'Say which profile.'; end if;
  if p_in then
    if not public.feature_enabled('members_only') then raise exception 'Members Only is not open yet.'; end if;
    if p_member = p_actor or public.profile_is_mine(p_member) then raise exception 'You cannot add your own profile.'; end if;
    if not public.profile_visible(p_actor, p_member) then raise exception 'This profile isn''t available.'; end if;
    if not exists (select 1 from public.site_follows f where f.follower = p_member and f.followed = p_actor and f.status = 'active') then
      raise exception 'They need to follow you first.';
    end if;
    if (select count(*) from public.site_member_lists l where l.owner = p_actor) >= 2000 and not exists (select 1 from public.site_member_lists l where l.owner = p_actor and l.member = p_member) then
      raise exception 'Your Members Only list is full (2000 people).';
    end if;
    insert into public.site_member_lists (owner, member) values (p_actor, p_member) on conflict do nothing;
  else
    delete from public.site_member_lists where owner = p_actor and member = p_member;
  end if;
  return jsonb_build_object('members', (select count(*) from public.site_member_lists l where l.owner = p_actor), 'is_member', p_in);
end;
$$;

-- ---------------------------------------------------------------------------
-- 9. Clean-up
-- ---------------------------------------------------------------------------
-- Files in the bucket that no post uses and that are more than a day old (an upload whose post was never made). For a scheduled job running as the service
-- role, which removes them through the storage API (deleting the row alone would leave the file).
create function public.social_media_orphans()
returns table (name text)
language sql
stable
security definer
set search_path = public
as $$
  select o.name
  from storage.objects o
  where o.bucket_id = 'social-media'
    and o.created_at < now() - interval '1 day'
    and not exists (select 1 from public.site_post_media m where m.storage_path = o.name or m.poster_path = o.name)
$$;

-- ---------------------------------------------------------------------------
-- 10. Who may call what
-- ---------------------------------------------------------------------------
revoke all on function
  public.social_media_profile(text), public.social_media_can_add(text), public.social_media_visible(text),
  public.post_visible(uuid, uuid), public.profile_mini(uuid), public.post_card(uuid, uuid), public.social_rules_version(), public.social_require_rules(),
  public.social_text_ok(text), public.social_json_int(jsonb, text), public.comment_card(uuid, uuid),
  public.rules_status(), public.rules_accept(int), public.rules_current(), public.cms_publish_rules(text), public.cms_set_banned_term(text, boolean), public.cms_list_banned_terms(), public.ai_caption_begin(),
  public.post_create(uuid, text, text, text, jsonb, jsonb, boolean), public.post_edit(uuid, uuid, text, text, boolean), public.post_delete(uuid, uuid),
  public.post_get(uuid, uuid), public.post_untag(uuid, uuid),
  public.profile_posts(uuid, uuid, text, int, timestamptz, uuid), public.feed_home(uuid, int, timestamptz, uuid), public.feed_suggested(uuid, int),
  public.feed_reels(uuid, int, timestamptz, uuid), public.story_rail(uuid), public.stories_of(uuid, uuid), public.story_seen(uuid, uuid),
  public.post_like(uuid, uuid, boolean), public.post_save(uuid, uuid, boolean), public.saved_posts(uuid, int, timestamptz),
  public.comment_add(uuid, uuid, text, uuid), public.comment_list(uuid, uuid, uuid, int, timestamptz), public.comment_delete(uuid, uuid),
  public.members_list(uuid, int, timestamptz), public.members_set(uuid, uuid, boolean), public.social_media_orphans()
from public, anon, authenticated;

-- The storage policies run as the person asking, so these two must be callable by them.
grant execute on function public.social_media_can_add(text), public.social_media_visible(text) to authenticated;

grant execute on function
  public.rules_status(), public.rules_accept(int), public.cms_publish_rules(text), public.cms_set_banned_term(text, boolean), public.cms_list_banned_terms(), public.ai_caption_begin(),
  public.post_create(uuid, text, text, text, jsonb, jsonb, boolean), public.post_edit(uuid, uuid, text, text, boolean), public.post_delete(uuid, uuid),
  public.post_get(uuid, uuid), public.post_untag(uuid, uuid),
  public.profile_posts(uuid, uuid, text, int, timestamptz, uuid), public.feed_home(uuid, int, timestamptz, uuid), public.feed_suggested(uuid, int),
  public.feed_reels(uuid, int, timestamptz, uuid), public.story_rail(uuid), public.stories_of(uuid, uuid), public.story_seen(uuid, uuid),
  public.post_like(uuid, uuid, boolean), public.post_save(uuid, uuid, boolean), public.saved_posts(uuid, int, timestamptz),
  public.comment_add(uuid, uuid, text, uuid), public.comment_list(uuid, uuid, uuid, int, timestamptz), public.comment_delete(uuid, uuid),
  public.members_list(uuid, int, timestamptz), public.members_set(uuid, uuid, boolean)
to authenticated, service_role;
grant execute on function public.social_media_orphans() to service_role;
-- The rules are public: a guest can read them before signing up.
grant execute on function public.rules_current() to anon, authenticated, service_role;
commit;

-- ====================================================================================================
-- 20261103100000_explore_reviews
-- ====================================================================================================
begin;
-- Explore, venue facts and reviews (customer app completion plan, M3; client plan pages 6 and 14).
--
--   * VENUE FACTS the plan asks for and the database lacked: amenities, parking, age and ID rules, last entry, kitchen hours, a menu link. They are plain columns of
--     site_venues (so they travel with the venue the apps already read) and are changed only through save_venue_facts(), by the venue's owner or manager.
--   * REVIEWS of a venue or an event are by a person (never a business profile) who actually went: a paid table booking at the venue on a night that is over, or a paid
--     ticket to an event that is over (a ticket to an event at that venue counts for the venue too), matched by the signed-in e-mail address. One review per person per
--     venue / event; they may change or delete it. The venue's own profile (its owner or manager) may reply once to each review. Text goes through the banned-terms check; a
--     person is slowed to 10 reviews a day. Reviews refuse until the `reviews` switch is on. Reading is open to any signed-in profile; a blocked pair do not see each other's.
--   * EXPLORE: "what's hot" is counted from what really happened in the last two weeks (paid table bookings, paid tickets, public posts tagged with the venue or event),
--     and only the order and a score are returned, never anyone's booking. A directory of professionals (DJs, photographers...) by category, city and name.
--
-- Reached only through the functions below; the new tables cannot be read or written by a client. Plain CREATE, never CREATE OR REPLACE; the new columns are additive.

-- ---------------------------------------------------------------------------
-- 1. Venue facts
-- ---------------------------------------------------------------------------
alter table public.site_venues
  add column amenities text[] not null default '{}',
  add column parking_info text,
  add column min_age smallint,
  add column id_required boolean not null default false,
  add column last_entry text,
  add column kitchen_hours text,
  add column menu_url text;

alter table public.site_venues
  add constraint site_venues_amenities_known check (
    amenities <@ array['parking', 'valet', 'coat_check', 'wifi', 'accessible', 'outdoor', 'vip_area', 'food', 'smoking_area', 'private_rooms', 'live_music', 'dance_floor', 'bottle_service']::text[]
  ),
  add constraint site_venues_facts_lengths check (
    (parking_info is null or char_length(parking_info) <= 300)
    and (last_entry is null or char_length(last_entry) <= 40)
    and (kitchen_hours is null or char_length(kitchen_hours) <= 100)
    and (menu_url is null or (menu_url ~ '^https://' and char_length(menu_url) <= 500))
    and (min_age is null or min_age between 13 and 25)
  );

-- The venue's owner or manager sets the facts customers see. Every field is replaced (a form saves them all); an empty text clears it.
create function public.save_venue_facts(
  p_venue uuid,
  p_amenities text[],
  p_parking text,
  p_min_age int,
  p_id_required boolean,
  p_last_entry text,
  p_kitchen_hours text,
  p_menu_url text
)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_amenities text[];
  v_parking text := nullif(btrim(coalesce(p_parking, '')), '');
  v_last text := nullif(btrim(coalesce(p_last_entry, '')), '');
  v_kitchen text := nullif(btrim(coalesce(p_kitchen_hours, '')), '');
  v_menu text := nullif(btrim(coalesce(p_menu_url, '')), '');
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if p_venue is null or not public.can_access_venue(p_venue, array['owner', 'manager']) then
    raise exception 'You can only change the details of a venue you own or manage.';
  end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v_amenities from unnest(coalesce(p_amenities, '{}')) x;
  if not (v_amenities <@ array['parking', 'valet', 'coat_check', 'wifi', 'accessible', 'outdoor', 'vip_area', 'food', 'smoking_area', 'private_rooms', 'live_music', 'dance_floor', 'bottle_service']::text[]) then
    raise exception 'One of those features is not one we know.';
  end if;
  if v_parking is not null and char_length(v_parking) > 300 then raise exception 'The parking note can be 300 characters at most.'; end if;
  if v_last is not null and char_length(v_last) > 40 then raise exception 'Last entry can be 40 characters at most.'; end if;
  if v_kitchen is not null and char_length(v_kitchen) > 100 then raise exception 'Kitchen hours can be 100 characters at most.'; end if;
  if v_menu is not null and (v_menu !~ '^https://' or char_length(v_menu) > 500) then raise exception 'The menu link must start with https://.'; end if;
  if p_min_age is not null and p_min_age not between 13 and 25 then raise exception 'The minimum age must be between 13 and 25.'; end if;
  if p_id_required is null then raise exception 'Say whether ID is required.'; end if;

  update public.site_venues set
    amenities = v_amenities, parking_info = v_parking, min_age = p_min_age, id_required = p_id_required,
    last_entry = v_last, kitchen_hours = v_kitchen, menu_url = v_menu
  where id = p_venue;
  perform public.venue_setup_log('venue_facts_saved', 'venue', p_venue, p_venue, jsonb_build_object('amenities', v_amenities));
  return jsonb_build_object('amenities', v_amenities, 'parking_info', v_parking, 'min_age', p_min_age, 'id_required', p_id_required,
                            'last_entry', v_last, 'kitchen_hours', v_kitchen, 'menu_url', v_menu);
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. Reviews
-- ---------------------------------------------------------------------------
create table public.site_reviews (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('venue', 'event')),
  venue_id uuid references public.site_venues (id) on delete cascade,
  event_id uuid references public.site_events (id) on delete cascade,
  author uuid not null references public.site_profiles (id) on delete cascade,
  rating smallint not null check (rating between 1 and 5),
  body text check (body is null or char_length(btrim(body)) between 1 and 1000),
  status text not null default 'active' check (status in ('active', 'removed')),
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  constraint site_reviews_target check ((kind = 'venue' and venue_id is not null and event_id is null) or (kind = 'event' and event_id is not null and venue_id is null))
);
create unique index site_reviews_one_per_venue on public.site_reviews (author, venue_id) where venue_id is not null;
create unique index site_reviews_one_per_event on public.site_reviews (author, event_id) where event_id is not null;
create index site_reviews_venue_idx on public.site_reviews (venue_id, created_at desc, id desc) where venue_id is not null and status = 'active';
create index site_reviews_event_idx on public.site_reviews (event_id, created_at desc, id desc) where event_id is not null and status = 'active';

create table public.site_review_replies (
  review uuid primary key references public.site_reviews (id) on delete cascade,
  author uuid not null references public.site_profiles (id) on delete cascade,
  body text not null check (char_length(btrim(body)) between 1 and 1000),
  created_at timestamptz not null default clock_timestamp()
);

alter table public.site_reviews enable row level security;
alter table public.site_review_replies enable row level security;
revoke all on table public.site_reviews, public.site_review_replies from public, anon, authenticated;

-- Has the signed-in person been to this venue (a paid table booking on a night that is over, or a paid ticket to a finished event there) or to this event?
create function public.review_visited(p_kind text, p_target uuid)
returns boolean
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_email text := lower(coalesce(auth.email(), ''));
begin
  if v_email = '' then return false; end if;
  if p_kind = 'venue' then
    return exists (
      select 1 from public.site_table_bookings b
      join public.site_venues v on v.id = b.venue_id
      where b.venue_id = p_target and b.status = 'paid' and lower(b.customer_email) = v_email
        and b.booking_date < (now() at time zone coalesce(nullif(v.time_zone, ''), 'UTC'))::date
    ) or exists (
      select 1 from public.site_orders o
      join public.site_events e on e.id = o.event_id
      where e.venue_id = p_target and o.status = 'paid' and lower(o.customer_email) = v_email and coalesce(e.end_date, e.start_date) < now()
    );
  elsif p_kind = 'event' then
    return exists (
      select 1 from public.site_orders o
      join public.site_events e on e.id = o.event_id
      where o.event_id = p_target and o.status = 'paid' and lower(o.customer_email) = v_email and coalesce(e.end_date, e.start_date) < now()
    );
  end if;
  return false;
end;
$$;

-- May this profile review this venue or event right now? Answers {eligible, reason, mine} where mine is the review it already wrote (to edit).
create function public.review_eligibility(p_actor uuid, p_kind text, p_target uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_mine uuid;
begin
  perform public.profile_require_actor(p_actor);
  if p_kind not in ('venue', 'event') or p_target is null then raise exception 'Choose a venue or an event.'; end if;
  if p_kind = 'venue' then
    select r.id into v_mine from public.site_reviews r where r.author = p_actor and r.venue_id = p_target;
  else
    select r.id into v_mine from public.site_reviews r where r.author = p_actor and r.event_id = p_target;
  end if;
  if not public.feature_enabled('reviews') then return jsonb_build_object('eligible', false, 'reason', 'Reviews are not open yet.', 'mine', v_mine); end if;
  if exists (select 1 from public.site_profiles s where s.id = p_actor and s.kind = 'business') then
    return jsonb_build_object('eligible', false, 'reason', 'Only a person''s own profile can write a review.', 'mine', v_mine);
  end if;
  if not public.review_visited(p_kind, p_target) then
    return jsonb_build_object('eligible', false,
      'reason', case p_kind when 'venue' then 'You can review a venue after a night you booked there.' else 'You can review an event after you went to it.' end,
      'mine', v_mine);
  end if;
  return jsonb_build_object('eligible', true, 'reason', null, 'mine', v_mine);
end;
$$;

-- Write a review, or change the one already written for this venue / event.
create function public.review_save(p_actor uuid, p_kind text, p_target uuid, p_rating int, p_body text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_elig jsonb;
  v_id uuid;
begin
  perform public.profile_require_actor(p_actor);
  perform public.social_require_rules();
  v_elig := public.review_eligibility(p_actor, p_kind, p_target);
  if (v_elig ->> 'eligible')::boolean is not true then raise exception '%', v_elig ->> 'reason'; end if;
  if p_rating is null or p_rating not between 1 and 5 then raise exception 'Choose 1 to 5 stars.'; end if;
  if v_body is not null and char_length(v_body) > 1000 then raise exception 'A review can be 1000 characters at most.'; end if;
  if not public.social_text_ok(v_body) then raise exception 'That text goes against our community rules.'; end if;
  if (v_elig ->> 'mine') is null
     and (select count(*) from public.site_reviews r where r.author = p_actor and r.created_at > now() - interval '1 day') >= 10 then
    raise exception 'You are writing reviews too quickly. Try again later.';
  end if;

  if (v_elig ->> 'mine') is not null then
    update public.site_reviews set rating = p_rating, body = v_body, updated_at = clock_timestamp() where id = (v_elig ->> 'mine')::uuid returning id into v_id;
  else
    insert into public.site_reviews (kind, venue_id, event_id, author, rating, body)
    values (p_kind, case when p_kind = 'venue' then p_target end, case when p_kind = 'event' then p_target end, p_actor, p_rating, v_body)
    returning id into v_id;
  end if;
  return public.review_card(p_actor, v_id);
end;
$$;

create function public.review_delete(p_actor uuid, p_review uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_author uuid;
begin
  perform public.profile_require_actor(p_actor);
  select r.author into v_author from public.site_reviews r where r.id = p_review;
  if v_author is null or not public.profile_can_act_as(v_author) then raise exception 'You can only delete your own reviews.'; end if;
  delete from public.site_reviews where id = p_review;
  return jsonb_build_object('deleted', true);
end;
$$;

-- Who may answer a review: the venue's own profile (its owner or manager), or the profile of the business that runs the event.
create function public.review_can_reply(p_actor uuid, p_review uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_can_act_as(p_actor)
     and exists (
       select 1
       from public.site_reviews r
       join public.site_profiles me on me.id = p_actor and me.kind = 'business'
       left join public.site_events e on e.id = r.event_id
       where r.id = p_review
         and ((r.venue_id is not null and me.venue_id = r.venue_id) or (r.event_id is not null and me.org_id is not null and me.venue_id is null and me.org_id = e.org_id))
     )
$$;

create function public.review_reply(p_actor uuid, p_review uuid, p_body text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_body text := btrim(coalesce(p_body, ''));
begin
  perform public.profile_require_actor(p_actor);
  perform public.social_require_rules();
  if not public.feature_enabled('reviews') then raise exception 'Reviews are not open yet.'; end if;
  if not public.review_can_reply(p_actor, p_review) then raise exception 'Only the venue or the organizer it is about can reply.'; end if;
  if char_length(v_body) < 1 then raise exception 'Write something first.'; end if;
  if char_length(v_body) > 1000 then raise exception 'A reply can be 1000 characters at most.'; end if;
  if not public.social_text_ok(v_body) then raise exception 'That text goes against our community rules.'; end if;
  insert into public.site_review_replies (review, author, body) values (p_review, p_actor, v_body)
  on conflict (review) do update set author = excluded.author, body = excluded.body;
  return public.review_card(p_actor, p_review);
end;
$$;

create function public.review_reply_delete(p_actor uuid, p_review uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not public.review_can_reply(p_actor, p_review) then raise exception 'Only the venue or the organizer it is about can reply.'; end if;
  delete from public.site_review_replies where review = p_review;
  return jsonb_build_object('deleted', true);
end;
$$;

-- One review as the app shows it.
create function public.review_card(p_viewer uuid, p_review uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', r.id,
    'kind', r.kind,
    'venue_id', r.venue_id,
    'event_id', r.event_id,
    'rating', r.rating,
    'body', r.body,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'author', public.profile_mini(r.author),
    'is_mine', public.profile_is_mine(r.author),
    'can_reply', public.review_can_reply(p_viewer, r.id),
    'reply', (select jsonb_build_object('body', y.body, 'created_at', y.created_at, 'author', public.profile_mini(y.author))
              from public.site_review_replies y where y.review = r.id)
  )
  from public.site_reviews r
  where r.id = p_review
$$;

-- The average, the count and how many of each star, for one venue or event. Counted over reviews by profiles in good standing.
create function public.review_summary(p_kind text, p_target uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'count', count(*),
    'average', coalesce(round(avg(r.rating)::numeric, 1), 0),
    'stars', jsonb_build_array(
      count(*) filter (where r.rating = 1), count(*) filter (where r.rating = 2), count(*) filter (where r.rating = 3),
      count(*) filter (where r.rating = 4), count(*) filter (where r.rating = 5))
  )
  from public.site_reviews r
  join public.site_profiles s on s.id = r.author and s.status = 'active'
  where r.status = 'active' and r.kind = p_kind and ((p_kind = 'venue' and r.venue_id = p_target) or (p_kind = 'event' and r.event_id = p_target))
$$;

-- A page of reviews (newest first) with the summary. p_before / p_before_id are the created_at and id of the last review seen.
create function public.reviews_list(p_actor uuid, p_kind text, p_target uuid, p_limit int default 20, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 20), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if p_kind not in ('venue', 'event') or p_target is null then raise exception 'Choose a venue or an event.'; end if;
  return jsonb_build_object(
    'summary', public.review_summary(p_kind, p_target),
    'items', coalesce((
      select jsonb_agg(public.review_card(p_actor, x.id) order by x.created_at desc, x.id desc)
      from (
        select r.id, r.created_at
        from public.site_reviews r
        join public.site_profiles s on s.id = r.author and s.status = 'active'
        where r.status = 'active' and r.kind = p_kind
          and ((p_kind = 'venue' and r.venue_id = p_target) or (p_kind = 'event' and r.event_id = p_target))
          and not public.profile_blocked_between(p_actor, r.author)
          and (p_before is null or (r.created_at, r.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        order by r.created_at desc, r.id desc
        limit v_limit
      ) x
    ), '[]'::jsonb)
  );
end;
$$;

-- Average and count for many venues at once, for a list of venue cards. Open to visitors; it holds nothing but the two numbers. Empty while reviews are off.
create function public.venue_ratings(p_venues uuid[])
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when not public.feature_enabled('reviews') then '{}'::jsonb else coalesce((
    select jsonb_object_agg(g.venue_id, jsonb_build_object('count', g.n, 'average', g.avg))
    from (
      select r.venue_id, count(*) as n, round(avg(r.rating)::numeric, 1) as avg
      from public.site_reviews r
      join public.site_profiles s on s.id = r.author and s.status = 'active'
      where r.status = 'active' and r.kind = 'venue' and r.venue_id = any (coalesce(p_venues, '{}'::uuid[]))
      group by r.venue_id
    ) g
  ), '{}'::jsonb) end
$$;

-- ---------------------------------------------------------------------------
-- 3. Explore
-- ---------------------------------------------------------------------------
-- The venues with the most going on, busiest first: 3 points for each paid table booking made in the last 14 days, 1 for each paid ticket to an event there, 2 for each
-- public post tagged with the venue. Only published venues; only the id and the score are answered. Open to visitors (the venues themselves are public).
create function public.explore_hot_venues(p_limit int default 10)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'score', h.score) order by h.score desc, h.id), '[]'::jsonb)
  from (
    select v.id,
           3 * (select count(*) from public.site_table_bookings b where b.venue_id = v.id and b.status = 'paid' and b.created_at > now() - interval '14 days')
         + (select count(*) from public.site_orders o join public.site_events e on e.id = o.event_id where e.venue_id = v.id and o.status = 'paid' and o.created_at > now() - interval '14 days')
         + 2 * (select count(*) from public.site_post_tags t join public.site_posts p on p.id = t.post join public.site_profiles a on a.id = p.author
                where t.venue_id = v.id and p.status = 'active' and p.audience = 'public' and p.kind <> 'story' and a.status = 'active' and a.privacy = 'public'
                  and p.created_at > now() - interval '14 days') as score
    from public.site_venues v
    where v.status = 'published'
    order by score desc, v.id
    limit least(greatest(coalesce(p_limit, 10), 1), 30)
  ) h
  where h.score > 0
$$;

-- The same for upcoming events: 2 points for each paid ticket order in the last 7 days, 2 for each public post tagged with it, 3 more when it starts within a week.
create function public.explore_hot_events(p_limit int default 10)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', h.id, 'score', h.score) order by h.score desc, h.id), '[]'::jsonb)
  from (
    select e.id,
           2 * (select count(*) from public.site_orders o where o.event_id = e.id and o.status = 'paid' and o.created_at > now() - interval '7 days')
         + 2 * (select count(*) from public.site_post_tags t join public.site_posts p on p.id = t.post join public.site_profiles a on a.id = p.author
                where t.event_id = e.id and p.status = 'active' and p.audience = 'public' and p.kind <> 'story' and a.status = 'active' and a.privacy = 'public'
                  and p.created_at > now() - interval '14 days')
         + case when e.start_date < now() + interval '7 days' then 3 else 0 end as score
    from public.site_events e
    where e.status = 'published' and coalesce(e.end_date, e.start_date) >= now()
    order by score desc, e.id
    limit least(greatest(coalesce(p_limit, 10), 1), 30)
  ) h
  where h.score > 0
$$;

-- A directory of professionals and event groups. Narrow it by category, city (whole word start) and name; best known first. p_offset pages it.
create function public.explore_professionals(p_actor uuid, p_category text default null, p_city text default null, p_query text default null, p_limit int default 20, p_offset int default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_category text := nullif(lower(btrim(coalesce(p_category, ''))), '');
  v_city text := nullif(lower(btrim(coalesce(p_city, ''))), '');
  v_query text := nullif(lower(btrim(coalesce(p_query, ''))), '');
  v_limit int := least(greatest(coalesce(p_limit, 20), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if v_category is not null and v_category not in ('event_group', 'dj', 'mc', 'artist', 'instrumentalist', 'photographer', 'videographer', 'influencer', 'promoter', 'other') then
    raise exception 'Choose a kind of professional from the list.';
  end if;
  if v_query is not null and char_length(v_query) > 40 then raise exception 'That search is too long.'; end if;
  return coalesce((
    select jsonb_agg(public.profile_card(p_actor, x.id) order by x.followers desc, x.name, x.id)
    from (
      select s.id,
             (select count(*) from public.site_follows f where f.followed = s.id and f.status = 'active') as followers,
             lower(s.display_name) as name
      from public.site_profiles s
      where s.kind = 'business' and s.status = 'active' and s.category <> 'venue'
        and (v_category is null or s.category = v_category)
        and (v_city is null or lower(coalesce(s.city, '')) like replace(replace(replace(v_city, '\', '\\'), '%', '\%'), '_', '\_') || '%')
        and (v_query is null or s.handle like replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%'
             or lower(s.display_name) like replace(replace(replace(v_query, '\', '\\'), '%', '\%'), '_', '\_') || '%')
        and not public.profile_blocked_between(p_actor, s.id)
      order by followers desc, name, s.id
      offset greatest(coalesce(p_offset, 0), 0)
      limit v_limit
    ) x
  ), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Who may call what
-- ---------------------------------------------------------------------------
revoke all on function
  public.save_venue_facts(uuid, text[], text, int, boolean, text, text, text),
  public.review_visited(text, uuid), public.review_eligibility(uuid, text, uuid), public.review_save(uuid, text, uuid, int, text), public.review_delete(uuid, uuid),
  public.review_can_reply(uuid, uuid), public.review_reply(uuid, uuid, text), public.review_reply_delete(uuid, uuid), public.review_card(uuid, uuid),
  public.review_summary(text, uuid), public.reviews_list(uuid, text, uuid, int, timestamptz, uuid), public.venue_ratings(uuid[]),
  public.explore_hot_venues(int), public.explore_hot_events(int), public.explore_professionals(uuid, text, text, text, int, int)
from public, anon, authenticated;
grant execute on function
  public.save_venue_facts(uuid, text[], text, int, boolean, text, text, text),
  public.review_eligibility(uuid, text, uuid), public.review_save(uuid, text, uuid, int, text), public.review_delete(uuid, uuid),
  public.review_reply(uuid, uuid, text), public.review_reply_delete(uuid, uuid), public.reviews_list(uuid, text, uuid, int, timestamptz, uuid),
  public.explore_professionals(uuid, text, text, text, int, int)
to authenticated, service_role;
grant execute on function public.venue_ratings(uuid[]), public.explore_hot_venues(int), public.explore_hot_events(int) to anon, authenticated, service_role;
commit;

-- ====================================================================================================
-- 20261104100000_inbox_notifications
-- ====================================================================================================
begin;
-- Inbox and notifications (customer app completion plan, M4; client plan page 5 and 17).
--
--   * CONVERSATIONS between profiles: direct, group, and about a booking (the customer and the venue's own profile, with a safe card of the booking). A member is a PROFILE, so
--     a business conversation is read by whoever may act as that business RIGHT NOW (revoke a manager and they are out at once), exactly as the staff chat works.
--   * MESSAGE REQUESTS: someone who is not followed by the person they write to lands in that person's Requests box. The writer may send three messages before an answer; replying
--     accepts. Declining hides the conversation quietly (the writer is not told). A blocked pair cannot write to each other.
--   * A MESSAGE is text (1 to 2000 characters) or a shared post, event, venue or booking with an optional note. A shared post shows only to people who may see it; a booking card
--     shows the venue, the night, the table and the party size and NEVER the confirmation code or any payment. At most 30 messages a minute from one profile to one conversation, and
--     a retried send with the same client key is one message. Sending needs the community rules accepted and the `inbox` switch on; text goes through the banned-terms check.
--   * NOTIFICATIONS in the app: someone followed, asked to follow, accepted your request, liked or commented on your post, replied to your comment, tagged you, answered your review.
--     Written by triggers on those events (never for yourself, never between a blocked pair, a tag only when the tagged profile can see the post); a notification is read through the
--     profile it is for, so a business's team sees the business's. A profile can switch off any kind (notification_prefs_set), and none is written for it afterwards. Push delivery is a separate step that needs the owner's Firebase account.
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table public.site_dm_conversations (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('direct', 'group', 'booking')),
  title text check (title is null or char_length(btrim(title)) between 1 and 60),
  pair_key text,
  booking_id uuid references public.site_table_bookings (id) on delete cascade,
  created_by uuid references public.site_profiles (id) on delete set null,
  created_at timestamptz not null default clock_timestamp(),
  last_message_at timestamptz not null default clock_timestamp(),
  constraint site_dm_shape check (
    (kind = 'direct' and pair_key is not null and booking_id is null and title is null)
    or (kind = 'group' and title is not null and pair_key is null and booking_id is null)
    or (kind = 'booking' and booking_id is not null and pair_key is null)
  )
);
create unique index site_dm_one_direct on public.site_dm_conversations (pair_key) where kind = 'direct';
create unique index site_dm_one_per_booking on public.site_dm_conversations (booking_id) where kind = 'booking';

create table public.site_dm_members (
  conversation uuid not null references public.site_dm_conversations (id) on delete cascade,
  profile uuid not null references public.site_profiles (id) on delete cascade,
  role text not null default 'member' check (role in ('member', 'admin')),
  status text not null default 'active' check (status in ('active', 'request', 'left')),
  joined_at timestamptz not null default clock_timestamp(),
  last_read_at timestamptz not null default clock_timestamp(),
  muted boolean not null default false,
  primary key (conversation, profile)
);
create index site_dm_members_profile_idx on public.site_dm_members (profile, status);

create table public.site_dm_messages (
  id uuid primary key default gen_random_uuid(),
  conversation uuid not null references public.site_dm_conversations (id) on delete cascade,
  sender uuid not null references public.site_profiles (id) on delete cascade,
  kind text not null check (kind in ('text', 'post', 'event', 'venue', 'booking')),
  body text check (body is null or char_length(btrim(body)) between 1 and 2000),
  ref_id uuid,
  client_key text check (client_key is null or char_length(client_key) <= 64),
  -- The moment it was written, so "unread" and a page ordered by it have no ties.
  created_at timestamptz not null default clock_timestamp(),
  deleted_at timestamptz,
  constraint site_dm_message_shape check ((kind = 'text' and body is not null and ref_id is null) or (kind <> 'text' and ref_id is not null))
);
create index site_dm_messages_conversation_idx on public.site_dm_messages (conversation, created_at desc, id desc);
create unique index site_dm_messages_client_key_idx on public.site_dm_messages (conversation, sender, client_key) where client_key is not null;

create table public.site_notifications (
  id uuid primary key default gen_random_uuid(),
  recipient uuid not null references public.site_profiles (id) on delete cascade,
  kind text not null check (kind in ('follow', 'follow_request', 'follow_accepted', 'like', 'comment', 'reply', 'tag', 'review_reply')),
  actor uuid not null references public.site_profiles (id) on delete cascade,
  post uuid references public.site_posts (id) on delete cascade,
  comment uuid references public.site_comments (id) on delete cascade,
  review uuid references public.site_reviews (id) on delete cascade,
  dedupe_key text not null,
  created_at timestamptz not null default clock_timestamp(),
  read_at timestamptz,
  unique (recipient, dedupe_key)
);
create index site_notifications_recipient_idx on public.site_notifications (recipient, created_at desc, id desc);
create index site_notifications_unread_idx on public.site_notifications (recipient) where read_at is null;

-- A kind of notification a profile has switched off. Every kind is on until a row says otherwise.
create table public.site_notification_opt_outs (
  profile uuid not null references public.site_profiles (id) on delete cascade,
  kind text not null check (kind in ('follow', 'follow_request', 'follow_accepted', 'like', 'comment', 'reply', 'tag', 'review_reply')),
  primary key (profile, kind)
);

alter table public.site_dm_conversations enable row level security;
alter table public.site_dm_members enable row level security;
alter table public.site_dm_messages enable row level security;
alter table public.site_notifications enable row level security;
alter table public.site_notification_opt_outs enable row level security;
revoke all on table public.site_dm_conversations, public.site_dm_members, public.site_dm_messages, public.site_notifications, public.site_notification_opt_outs from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Internal helpers (the app cannot call these)
-- ---------------------------------------------------------------------------
-- Is this profile a member of the conversation who has not left, and may the caller act as it?
create function public.dm_is_member(p_actor uuid, p_conversation uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_can_act_as(p_actor)
     and exists (select 1 from public.site_dm_members m where m.conversation = p_conversation and m.profile = p_actor and m.status in ('active', 'request'))
$$;

-- Is this a one-to-one conversation with someone who is blocked either way or suspended? Such a conversation is gone: not listed, not counted, not readable, not written to.
create function public.dm_direct_closed(p_actor uuid, p_conversation uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.site_dm_conversations c
    join public.site_dm_members o on o.conversation = c.id and o.profile <> p_actor
    join public.site_profiles s on s.id = o.profile
    where c.id = p_conversation and c.kind = 'direct'
      and (s.status <> 'active' or public.profile_blocked_between(p_actor, o.profile))
  )
$$;

-- How a new member is received: straight into the inbox when they follow the person adding them, otherwise as a request.
create function public.dm_new_member_status(p_inviter uuid, p_member uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case when exists (select 1 from public.site_follows f where f.follower = p_member and f.followed = p_inviter and f.status = 'active') then 'active' else 'request' end
$$;

-- What a message refers to, as the viewer may see it. A post only if the viewer may see it; a booking only a safe summary (never the code, never money).
create function public.dm_ref_card(p_viewer uuid, p_kind text, p_ref uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if p_kind = 'post' then
    if p_ref is not null and public.post_visible(p_viewer, p_ref) then return jsonb_build_object('available', true, 'post', public.post_card(p_viewer, p_ref)); end if;
    return jsonb_build_object('available', false);
  elsif p_kind = 'event' then
    return coalesce((select jsonb_build_object('available', true, 'id', e.id, 'title', e.title, 'starts_at', e.start_date, 'venue_name', e.venue_name)
                     from public.site_events e where e.id = p_ref and e.status = 'published'), jsonb_build_object('available', false));
  elsif p_kind = 'venue' then
    return coalesce((select jsonb_build_object('available', true, 'id', v.id, 'name', v.name, 'address', v.address)
                     from public.site_venues v where v.id = p_ref and v.status = 'published'), jsonb_build_object('available', false));
  elsif p_kind = 'booking' then
    return coalesce((select jsonb_build_object('available', true, 'id', b.id, 'venue', v.name, 'night', b.booking_date, 'table', t.name, 'guests', b.guest_count, 'status', b.status)
                     from public.site_table_bookings b
                     join public.site_venues v on v.id = b.venue_id
                     left join public.site_table_types t on t.id = b.table_type_id
                     where b.id = p_ref), jsonb_build_object('available', false));
  end if;
  return null;
end;
$$;

-- One message as the app shows it. A removed message keeps its place but loses its words.
create function public.dm_message_card(p_viewer uuid, p_message uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', m.id,
    'conversation', m.conversation,
    'kind', m.kind,
    'body', case when m.deleted_at is null then m.body end,
    'removed', m.deleted_at is not null,
    'created_at', m.created_at,
    'sender', public.profile_mini(m.sender),
    'is_mine', public.profile_is_mine(m.sender),
    'ref', case when m.deleted_at is null and m.kind <> 'text' then public.dm_ref_card(p_viewer, m.kind, m.ref_id) end
  )
  from public.site_dm_messages m
  where m.id = p_message
$$;

-- Put a notification in a profile's list once. Never for oneself, never across a block.
create function public.notify_profile(p_recipient uuid, p_kind text, p_actor uuid, p_post uuid default null, p_comment uuid default null, p_review uuid default null)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_recipient is null or p_actor is null or p_recipient = p_actor then return; end if;
  if public.profile_blocked_between(p_recipient, p_actor) then return; end if;
  if not exists (select 1 from public.site_profiles s where s.id = p_recipient and s.status = 'active') then return; end if;
  if exists (select 1 from public.site_notification_opt_outs o where o.profile = p_recipient and o.kind = p_kind) then return; end if;
  insert into public.site_notifications (recipient, kind, actor, post, comment, review, dedupe_key)
  values (p_recipient, p_kind, p_actor, p_post, p_comment, p_review,
          p_kind || ':' || p_actor::text || ':' || coalesce(p_post::text, '') || ':' || coalesce(p_comment::text, '') || ':' || coalesce(p_review::text, ''))
  on conflict (recipient, dedupe_key) do nothing;
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Triggers that write notifications
-- ---------------------------------------------------------------------------
create function public.notify_on_follow()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if tg_op = 'INSERT' then
    perform public.notify_profile(new.followed, case new.status when 'active' then 'follow' else 'follow_request' end, new.follower);
  elsif tg_op = 'UPDATE' and old.status = 'pending' and new.status = 'active' then
    perform public.notify_profile(new.follower, 'follow_accepted', new.followed);
  end if;
  return new;
end;
$$;
create trigger site_follows_notify after insert or update of status on public.site_follows for each row execute function public.notify_on_follow();

create function public.notify_on_like()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.notify_profile((select p.author from public.site_posts p where p.id = new.post and p.kind <> 'story'), 'like', new.profile, new.post);
  return new;
end;
$$;
create trigger site_post_likes_notify after insert on public.site_post_likes for each row execute function public.notify_on_like();

create function public.notify_on_comment()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.reply_to is null then
    perform public.notify_profile((select p.author from public.site_posts p where p.id = new.post), 'comment', new.author, new.post, new.id);
  else
    perform public.notify_profile((select c.author from public.site_comments c where c.id = new.reply_to), 'reply', new.author, new.post, new.id);
  end if;
  return new;
end;
$$;
create trigger site_comments_notify after insert on public.site_comments for each row execute function public.notify_on_comment();

create function public.notify_on_tag()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_author uuid;
begin
  if new.profile_id is null then return new; end if;
  select p.author into v_author from public.site_posts p where p.id = new.post;
  -- A tagged profile that could not see the post is not told about it.
  if public.post_visible(new.profile_id, new.post) then
    perform public.notify_profile(new.profile_id, 'tag', v_author, new.post);
  end if;
  return new;
end;
$$;
create trigger site_post_tags_notify after insert on public.site_post_tags for each row execute function public.notify_on_tag();

create function public.notify_on_review_reply()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.notify_profile((select r.author from public.site_reviews r where r.id = new.review), 'review_reply', new.author, null, null, new.review);
  return new;
end;
$$;
create trigger site_review_replies_notify after insert on public.site_review_replies for each row execute function public.notify_on_review_reply();

-- ---------------------------------------------------------------------------
-- 4. Starting a conversation
-- ---------------------------------------------------------------------------
create function public.dm_require_inbox()
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if not public.feature_enabled('social') or not public.feature_enabled('inbox') then raise exception 'Messages are not open yet.'; end if;
end;
$$;

-- A direct conversation with one profile: the one that exists, or a new one (a request when they do not follow you).
create function public.dm_start_direct(p_actor uuid, p_other uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_key text;
  v_id uuid;
begin
  perform public.profile_require_actor(p_actor);
  perform public.dm_require_inbox();
  if p_other is null or p_other = p_actor or public.profile_is_mine(p_other) then raise exception 'You cannot message your own profile.'; end if;
  if not public.profile_visible(p_actor, p_other) then raise exception 'This profile isn''t available.'; end if;
  v_key := least(p_actor::text, p_other::text) || ':' || greatest(p_actor::text, p_other::text);
  select c.id into v_id from public.site_dm_conversations c where c.kind = 'direct' and c.pair_key = v_key;
  if v_id is null then
    begin
      insert into public.site_dm_conversations (kind, pair_key, created_by) values ('direct', v_key, p_actor) returning id into v_id;
      insert into public.site_dm_members (conversation, profile, status) values (v_id, p_actor, 'active');
      insert into public.site_dm_members (conversation, profile, status) values (v_id, p_other, public.dm_new_member_status(p_actor, p_other));
    exception when unique_violation then
      select c.id into v_id from public.site_dm_conversations c where c.kind = 'direct' and c.pair_key = v_key;
    end;
  end if;
  -- Writing again to someone who had left a conversation does not bring it back for them.
  update public.site_dm_members set status = 'active' where conversation = v_id and profile = p_actor and status = 'left';
  return jsonb_build_object('id', v_id);
end;
$$;

-- A group: a name and up to 49 other profiles (each one who follows you joins; the rest get a request).
create function public.dm_start_group(p_actor uuid, p_title text, p_members uuid[])
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_title text := btrim(coalesce(p_title, ''));
  v_members uuid[];
  v_id uuid;
  v_m uuid;
begin
  perform public.profile_require_actor(p_actor);
  perform public.dm_require_inbox();
  if char_length(v_title) < 1 or char_length(v_title) > 60 then raise exception 'Give the group a name (60 characters at most).'; end if;
  if not public.social_text_ok(v_title) then raise exception 'That text goes against our community rules.'; end if;
  select coalesce(array_agg(distinct x), '{}') into v_members from unnest(coalesce(p_members, '{}')) x where x is not null and x <> p_actor;
  if cardinality(v_members) < 1 then raise exception 'Choose at least one person to add.'; end if;
  if cardinality(v_members) > 49 then raise exception 'A group can have 50 people at most.'; end if;
  foreach v_m in array v_members loop
    if public.profile_is_mine(v_m) or not public.profile_visible(p_actor, v_m) then raise exception 'One of those profiles isn''t available.'; end if;
  end loop;
  insert into public.site_dm_conversations (kind, title, created_by) values ('group', v_title, p_actor) returning id into v_id;
  insert into public.site_dm_members (conversation, profile, role, status) values (v_id, p_actor, 'admin', 'active');
  foreach v_m in array v_members loop
    insert into public.site_dm_members (conversation, profile, status) values (v_id, v_m, public.dm_new_member_status(p_actor, v_m));
  end loop;
  return jsonb_build_object('id', v_id);
end;
$$;

create function public.dm_group_add(p_actor uuid, p_conversation uuid, p_member uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  perform public.dm_require_inbox();
  if not exists (select 1 from public.site_dm_conversations c join public.site_dm_members m on m.conversation = c.id
                 where c.id = p_conversation and c.kind = 'group' and m.profile = p_actor and m.role = 'admin' and m.status = 'active') then
    raise exception 'Only a group''s admin can add people.';
  end if;
  if p_member is null or public.profile_is_mine(p_member) or not public.profile_visible(p_actor, p_member) then raise exception 'This profile isn''t available.'; end if;
  if (select count(*) from public.site_dm_members m where m.conversation = p_conversation and m.status <> 'left') >= 50 then raise exception 'A group can have 50 people at most.'; end if;
  insert into public.site_dm_members (conversation, profile, status) values (p_conversation, p_member, public.dm_new_member_status(p_actor, p_member))
  on conflict (conversation, profile) do update set status = excluded.status, joined_at = clock_timestamp(), last_read_at = clock_timestamp() where public.site_dm_members.status = 'left';
  return jsonb_build_object('members', (select count(*) from public.site_dm_members m where m.conversation = p_conversation and m.status <> 'left'));
end;
$$;

create function public.dm_group_remove(p_actor uuid, p_conversation uuid, p_member uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not exists (select 1 from public.site_dm_conversations c join public.site_dm_members m on m.conversation = c.id
                 where c.id = p_conversation and c.kind = 'group' and m.profile = p_actor and m.role = 'admin' and m.status = 'active') then
    raise exception 'Only a group''s admin can remove people.';
  end if;
  if p_member = p_actor or public.profile_is_mine(p_member) then raise exception 'Use Leave to leave a group yourself.'; end if;
  update public.site_dm_members set status = 'left' where conversation = p_conversation and profile = p_member and status <> 'left';
  return jsonb_build_object('members', (select count(*) from public.site_dm_members m where m.conversation = p_conversation and m.status <> 'left'));
end;
$$;

create function public.dm_group_rename(p_actor uuid, p_conversation uuid, p_title text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_title text := btrim(coalesce(p_title, ''));
begin
  perform public.profile_require_actor(p_actor);
  if not exists (select 1 from public.site_dm_conversations c join public.site_dm_members m on m.conversation = c.id
                 where c.id = p_conversation and c.kind = 'group' and m.profile = p_actor and m.role = 'admin' and m.status = 'active') then
    raise exception 'Only a group''s admin can rename it.';
  end if;
  if char_length(v_title) < 1 or char_length(v_title) > 60 then raise exception 'Give the group a name (60 characters at most).'; end if;
  if not public.social_text_ok(v_title) then raise exception 'That text goes against our community rules.'; end if;
  update public.site_dm_conversations set title = v_title where id = p_conversation;
  return jsonb_build_object('title', v_title);
end;
$$;

-- Leave a group. When the last admin leaves, the member who joined first takes over.
create function public.dm_leave(p_actor uuid, p_conversation uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_next uuid;
begin
  perform public.profile_require_actor(p_actor);
  if not exists (select 1 from public.site_dm_conversations c where c.id = p_conversation and c.kind = 'group') then raise exception 'You can only leave a group.'; end if;
  update public.site_dm_members set status = 'left', role = 'member' where conversation = p_conversation and profile = p_actor and status <> 'left';
  if not exists (select 1 from public.site_dm_members m where m.conversation = p_conversation and m.role = 'admin' and m.status = 'active') then
    select m.profile into v_next from public.site_dm_members m where m.conversation = p_conversation and m.status = 'active' order by m.joined_at, m.profile limit 1;
    if v_next is not null then update public.site_dm_members set role = 'admin' where conversation = p_conversation and profile = v_next; end if;
  end if;
  return jsonb_build_object('left', true);
end;
$$;

-- A conversation between the customer and the venue about their booking. Only the person the booking was made for (matched by e-mail) can start it.
create function public.dm_start_booking(p_actor uuid, p_booking uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_venue uuid;
  v_venue_profile uuid;
  v_id uuid;
begin
  perform public.profile_require_actor(p_actor);
  perform public.dm_require_inbox();
  if exists (select 1 from public.site_profiles s where s.id = p_actor and s.kind = 'business') then raise exception 'Only a person''s own profile can message about a booking.'; end if;
  select b.venue_id into v_venue from public.site_table_bookings b
  where b.id = p_booking and b.status = 'paid' and lower(b.customer_email) = lower(coalesce(auth.email(), '')) and coalesce(auth.email(), '') <> '';
  if v_venue is null then raise exception 'You can only message about a booking you made.'; end if;
  select s.id into v_venue_profile from public.site_profiles s where s.venue_id = v_venue and s.status = 'active';
  if v_venue_profile is null then raise exception 'This venue has not set up messages yet.'; end if;
  select c.id into v_id from public.site_dm_conversations c where c.kind = 'booking' and c.booking_id = p_booking;
  if v_id is null then
    begin
      insert into public.site_dm_conversations (kind, booking_id, created_by) values ('booking', p_booking, p_actor) returning id into v_id;
      insert into public.site_dm_members (conversation, profile, status) values (v_id, p_actor, 'active'), (v_id, v_venue_profile, 'active');
      insert into public.site_dm_messages (conversation, sender, kind, ref_id) values (v_id, p_actor, 'booking', p_booking);
    exception when unique_violation then
      select c.id into v_id from public.site_dm_conversations c where c.kind = 'booking' and c.booking_id = p_booking;
    end;
  end if;
  return jsonb_build_object('id', v_id);
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Sending, reading, and the inbox
-- ---------------------------------------------------------------------------
-- Send a message: p_ref_kind / p_ref_id share a post, event, venue or booking (p_body is then an optional note).
create function public.dm_send(p_actor uuid, p_conversation uuid, p_body text default null, p_client_key text default null, p_ref_kind text default null, p_ref_id uuid default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_kind text := coalesce(nullif(lower(btrim(coalesce(p_ref_kind, ''))), ''), 'text');
  v_body text := nullif(btrim(coalesce(p_body, '')), '');
  v_conv public.site_dm_conversations;
  v_my_status text;
  v_other_status text;
  v_id uuid;
begin
  perform public.profile_require_actor(p_actor);
  perform public.social_require_rules();
  perform public.dm_require_inbox();
  select * into v_conv from public.site_dm_conversations where id = p_conversation;
  if not found or not public.dm_is_member(p_actor, p_conversation) then raise exception 'This conversation isn''t available.'; end if;
  select m.status into v_my_status from public.site_dm_members m where m.conversation = p_conversation and m.profile = p_actor;
  if public.dm_direct_closed(p_actor, p_conversation) then
    raise exception 'This conversation isn''t available.';
  end if;

  -- a retried send is the same message
  if p_client_key is not null then
    select m.id into v_id from public.site_dm_messages m where m.conversation = p_conversation and m.sender = p_actor and m.client_key = p_client_key;
    if v_id is not null then return public.dm_message_card(p_actor, v_id); end if;
  end if;

  if v_kind not in ('text', 'post', 'event', 'venue', 'booking') then raise exception 'You cannot send that.'; end if;
  if v_kind = 'text' then
    if v_body is null then raise exception 'Write something first.'; end if;
  else
    if p_ref_id is null then raise exception 'You cannot send that.'; end if;
    if v_kind = 'post' and not public.post_visible(p_actor, p_ref_id) then raise exception 'You cannot share that post.'; end if;
    if v_kind = 'event' and not exists (select 1 from public.site_events e where e.id = p_ref_id and e.status = 'published') then raise exception 'You cannot share that event.'; end if;
    if v_kind = 'venue' and not exists (select 1 from public.site_venues v where v.id = p_ref_id and v.status = 'published') then raise exception 'You cannot share that venue.'; end if;
    if v_kind = 'booking' and not (v_conv.kind = 'booking' and v_conv.booking_id = p_ref_id) then raise exception 'A booking can only be shared in its own conversation.'; end if;
  end if;
  if v_body is not null and char_length(v_body) > (case when v_kind = 'text' then 2000 else 500 end) then
    raise exception 'A message can be % characters at most.', case when v_kind = 'text' then 2000 else 500 end;
  end if;
  if not public.social_text_ok(v_body) then raise exception 'That text goes against our community rules.'; end if;
  if (select count(*) from public.site_dm_messages m where m.sender = p_actor and m.conversation = p_conversation and m.created_at > now() - interval '1 minute') >= 30 then
    raise exception 'You are sending messages too fast. Wait a moment.';
  end if;
  -- Until the person you wrote to answers, three messages are all they get.
  if v_conv.kind = 'direct' and v_my_status = 'active' then
    select m.status into v_other_status from public.site_dm_members m where m.conversation = p_conversation and m.profile <> p_actor;
    if v_other_status <> 'active' and (select count(*) from public.site_dm_messages m where m.conversation = p_conversation and m.sender = p_actor) >= 3 then
      raise exception 'Wait for them to reply before sending more.';
    end if;
  end if;

  insert into public.site_dm_messages (conversation, sender, kind, body, ref_id, client_key)
  values (p_conversation, p_actor, v_kind, v_body, case when v_kind = 'text' then null else p_ref_id end, p_client_key)
  returning id into v_id;
  update public.site_dm_conversations set last_message_at = clock_timestamp() where id = p_conversation;
  -- Replying to a request accepts it; the sender has read what they wrote.
  update public.site_dm_members set status = 'active', last_read_at = clock_timestamp() where conversation = p_conversation and profile = p_actor;
  return public.dm_message_card(p_actor, v_id);
end;
$$;

-- A page of messages, newest first. p_before / p_before_id are the created_at and id of the last message seen.
create function public.dm_messages(p_actor uuid, p_conversation uuid, p_limit int default 30, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if not public.dm_is_member(p_actor, p_conversation) or public.dm_direct_closed(p_actor, p_conversation) then raise exception 'This conversation isn''t available.'; end if;
  return coalesce((
    select jsonb_agg(public.dm_message_card(p_actor, x.id) order by x.created_at desc, x.id desc)
    from (
      select m.id, m.created_at
      from public.site_dm_messages m
      where m.conversation = p_conversation
        and (p_before is null or (m.created_at, m.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        -- a person who joined a group later does not see what was said before they joined
        and m.created_at >= (select mm.joined_at from public.site_dm_members mm where mm.conversation = p_conversation and mm.profile = p_actor)
      order by m.created_at desc, m.id desc
      limit v_limit
    ) x
  ), '[]'::jsonb);
end;
$$;

-- One conversation as the app lists it, for the profile p_actor (who must be in it).
create function public.dm_conversation_json(p_actor uuid, p_conversation uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', c.id,
    'kind', c.kind,
    'title', c.title,
    'booking_id', c.booking_id,
    'status', m.status,
    'muted', m.muted,
    'last_message_at', c.last_message_at,
    'member_count', (select count(*) from public.site_dm_members mm where mm.conversation = c.id and mm.status <> 'left'),
    'others', coalesce((select jsonb_agg(public.profile_mini(o.profile) order by o.joined_at)
                        from (select mm.profile, mm.joined_at from public.site_dm_members mm
                              where mm.conversation = c.id and mm.profile <> p_actor and mm.status <> 'left' order by mm.joined_at limit 3) o), '[]'::jsonb),
    'last', (select jsonb_build_object('kind', lm.kind, 'body', case when lm.deleted_at is null then left(lm.body, 120) end, 'removed', lm.deleted_at is not null,
                                       'created_at', lm.created_at, 'sender', public.profile_mini(lm.sender), 'is_mine', public.profile_is_mine(lm.sender))
             from public.site_dm_messages lm where lm.conversation = c.id order by lm.created_at desc, lm.id desc limit 1),
    'unread', (select count(*) from public.site_dm_messages um
               where um.conversation = c.id and um.deleted_at is null and um.sender <> p_actor and um.created_at > m.last_read_at and um.created_at >= m.joined_at)
  )
  from public.site_dm_members m
  join public.site_dm_conversations c on c.id = m.conversation
  where m.conversation = p_conversation and m.profile = p_actor
$$;

-- One conversation the profile is in (its title, who is in it), for the top of the conversation screen.
create function public.dm_conversation(p_actor uuid, p_conversation uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not public.dm_is_member(p_actor, p_conversation) or public.dm_direct_closed(p_actor, p_conversation) then raise exception 'This conversation isn''t available.'; end if;
  return public.dm_conversation_json(p_actor, p_conversation);
end;
$$;

-- The inbox: p_box 'main' (conversations you are in) or 'requests' (people you do not follow, waiting). Newest activity first.
create function public.dm_inbox(p_actor uuid, p_box text default 'main', p_limit int default 30, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_box text := lower(btrim(coalesce(p_box, '')));
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  if v_box not in ('main', 'requests') then raise exception 'Choose main or requests.'; end if;
  return coalesce((
    select jsonb_agg(public.dm_conversation_json(p_actor, x.id) order by x.last_message_at desc, x.id desc)
    from (
      select c.id, c.last_message_at
      from public.site_dm_members m
      join public.site_dm_conversations c on c.id = m.conversation
      where m.profile = p_actor
        and ((v_box = 'main' and m.status = 'active') or (v_box = 'requests' and m.status = 'request'))
        and (p_before is null or (c.last_message_at, c.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        and not public.dm_direct_closed(p_actor, c.id)
      order by c.last_message_at desc, c.id desc
      limit v_limit
    ) x
  ), '[]'::jsonb);
end;
$$;

create function public.dm_mark_read(p_actor uuid, p_conversation uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not public.dm_is_member(p_actor, p_conversation) then raise exception 'This conversation isn''t available.'; end if;
  update public.site_dm_members set last_read_at = clock_timestamp() where conversation = p_conversation and profile = p_actor;
  return jsonb_build_object('read', true);
end;
$$;

create function public.dm_mute(p_actor uuid, p_conversation uuid, p_muted boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_muted is null then raise exception 'Choose mute or unmute.'; end if;
  if not public.dm_is_member(p_actor, p_conversation) then raise exception 'This conversation isn''t available.'; end if;
  update public.site_dm_members set muted = p_muted where conversation = p_conversation and profile = p_actor;
  return jsonb_build_object('muted', p_muted);
end;
$$;

-- Accept a request, or decline it (the conversation just disappears for you; the other person is not told).
create function public.dm_answer_request(p_actor uuid, p_conversation uuid, p_accept boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_accept is null then raise exception 'Choose accept or decline.'; end if;
  if not exists (select 1 from public.site_dm_members m where m.conversation = p_conversation and m.profile = p_actor and m.status = 'request') then
    raise exception 'There is no request here.';
  end if;
  update public.site_dm_members set status = case when p_accept then 'active' else 'left' end, last_read_at = clock_timestamp() where conversation = p_conversation and profile = p_actor;
  return jsonb_build_object('accepted', p_accept);
end;
$$;

-- Take back a message you sent. It stays in the list as "removed".
create function public.dm_delete_message(p_actor uuid, p_message uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_sender uuid;
  v_conv uuid;
begin
  perform public.profile_require_actor(p_actor);
  select m.sender, m.conversation into v_sender, v_conv from public.site_dm_messages m where m.id = p_message;
  if v_sender is null or v_sender <> p_actor or not public.dm_is_member(p_actor, v_conv) then raise exception 'You can only remove your own messages.'; end if;
  update public.site_dm_messages set deleted_at = coalesce(deleted_at, clock_timestamp()) where id = p_message;
  return jsonb_build_object('removed', true);
end;
$$;

-- The people in a conversation (for the group's page), with who is an admin and who has not accepted yet.
create function public.dm_people(p_actor uuid, p_conversation uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if not public.dm_is_member(p_actor, p_conversation) then raise exception 'This conversation isn''t available.'; end if;
  return coalesce((
    select jsonb_agg(public.profile_mini(m.profile) || jsonb_build_object('role', m.role, 'status', m.status) order by m.joined_at, m.profile)
    from public.site_dm_members m where m.conversation = p_conversation and m.status <> 'left'
  ), '[]'::jsonb);
end;
$$;

-- How many conversations have something new, and how many requests are waiting, for the badge on the Inbox tab. A muted conversation does not count.
create function public.dm_unread(p_actor uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  return jsonb_build_object(
    'conversations', (select count(*) from public.site_dm_members m
                      where m.profile = p_actor and m.status = 'active' and not m.muted and not public.dm_direct_closed(p_actor, m.conversation)
                        and exists (select 1 from public.site_dm_messages um where um.conversation = m.conversation and um.deleted_at is null and um.sender <> p_actor
                                    and um.created_at > m.last_read_at and um.created_at >= m.joined_at)),
    'requests', (select count(*) from public.site_dm_members m where m.profile = p_actor and m.status = 'request' and not public.dm_direct_closed(p_actor, m.conversation))
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. Reading notifications
-- ---------------------------------------------------------------------------
create function public.notifications_list(p_actor uuid, p_limit int default 30, p_before timestamptz default null, p_before_id uuid default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 30), 1), 50);
begin
  perform public.profile_require_actor(p_actor);
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', n.id,
      'kind', n.kind,
      'created_at', n.created_at,
      'read', n.read_at is not null,
      'actor', public.profile_mini(n.actor),
      'post', case when n.post is not null and public.post_visible(p_actor, n.post) then public.post_card(p_actor, n.post) end,
      'comment_body', (select left(c.body, 140) from public.site_comments c where c.id = n.comment and c.status = 'active'),
      'review_id', n.review,
      'follows_back', n.kind = 'follow' and exists (select 1 from public.site_follows f where f.follower = p_actor and f.followed = n.actor and f.status = 'active')
    ) order by n.created_at desc, n.id desc)
    from (
      select x.*
      from public.site_notifications x
      join public.site_profiles s on s.id = x.actor and s.status = 'active'
      where x.recipient = p_actor
        and (p_before is null or (x.created_at, x.id) < (p_before, coalesce(p_before_id, 'ffffffff-ffff-ffff-ffff-ffffffffffff'::uuid)))
        and not public.profile_blocked_between(p_actor, x.actor)
      order by x.created_at desc, x.id desc
      limit v_limit
    ) n
  ), '[]'::jsonb);
end;
$$;

create function public.notifications_unread(p_actor uuid)
returns int
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  return (select count(*) from public.site_notifications n join public.site_profiles s on s.id = n.actor and s.status = 'active'
          where n.recipient = p_actor and n.read_at is null and not public.profile_blocked_between(p_actor, n.actor));
end;
$$;

-- Mark everything up to a moment (or everything) as read.
create function public.notifications_read(p_actor uuid, p_up_to timestamptz default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  update public.site_notifications set read_at = clock_timestamp() where recipient = p_actor and read_at is null and (p_up_to is null or created_at <= p_up_to);
  return jsonb_build_object('unread', public.notifications_unread(p_actor));
end;
$$;

-- Which kinds of notification the profile gets: {"like": true, "comment": false, ...} for every kind.
create function public.notification_prefs(p_actor uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  return (
    select jsonb_object_agg(k.kind, not exists (select 1 from public.site_notification_opt_outs o where o.profile = p_actor and o.kind = k.kind))
    from unnest(array['follow', 'follow_request', 'follow_accepted', 'like', 'comment', 'reply', 'tag', 'review_reply']) as k(kind)
  );
end;
$$;

-- Switch some kinds on or off for the profile (it is the profile's own choice, and each profile has its own). Answers all of them as they now stand.
create function public.notification_prefs_set(p_actor uuid, p_kinds text[], p_enabled boolean)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.profile_require_actor(p_actor);
  if p_enabled is null then raise exception 'Choose on or off.'; end if;
  if p_kinds is null or cardinality(p_kinds) < 1 or cardinality(p_kinds) > 8
     or not (p_kinds <@ array['follow', 'follow_request', 'follow_accepted', 'like', 'comment', 'reply', 'tag', 'review_reply']) then
    raise exception 'Choose what to change.';
  end if;
  if p_enabled then
    delete from public.site_notification_opt_outs where profile = p_actor and kind = any(p_kinds);
  else
    insert into public.site_notification_opt_outs (profile, kind) select p_actor, k from unnest(p_kinds) as k on conflict do nothing;
  end if;
  return public.notification_prefs(p_actor);
end;
$$;

-- Old read notifications are deleted by a scheduled job running as the service role (nothing in the database runs it on a timer yet).
create function public.notifications_purge(p_days int default 90)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  n int;
begin
  delete from public.site_notifications where read_at is not null and created_at < now() - make_interval(days => greatest(coalesce(p_days, 90), 7));
  get diagnostics n = row_count;
  return n;
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Who may call what
-- ---------------------------------------------------------------------------
revoke all on function
  public.dm_is_member(uuid, uuid), public.dm_direct_closed(uuid, uuid), public.dm_new_member_status(uuid, uuid), public.dm_ref_card(uuid, text, uuid), public.dm_message_card(uuid, uuid),
  public.notify_profile(uuid, text, uuid, uuid, uuid, uuid), public.notify_on_follow(), public.notify_on_like(), public.notify_on_comment(), public.notify_on_tag(),
  public.notify_on_review_reply(), public.dm_require_inbox(),
  public.dm_start_direct(uuid, uuid), public.dm_start_group(uuid, text, uuid[]), public.dm_group_add(uuid, uuid, uuid), public.dm_group_remove(uuid, uuid, uuid),
  public.dm_group_rename(uuid, uuid, text), public.dm_leave(uuid, uuid), public.dm_start_booking(uuid, uuid),
  public.dm_send(uuid, uuid, text, text, text, uuid), public.dm_messages(uuid, uuid, int, timestamptz, uuid), public.dm_inbox(uuid, text, int, timestamptz, uuid),
  public.dm_mark_read(uuid, uuid), public.dm_mute(uuid, uuid, boolean), public.dm_answer_request(uuid, uuid, boolean), public.dm_delete_message(uuid, uuid),
  public.dm_people(uuid, uuid), public.dm_unread(uuid), public.dm_conversation_json(uuid, uuid), public.dm_conversation(uuid, uuid),
  public.notifications_list(uuid, int, timestamptz, uuid), public.notifications_unread(uuid), public.notifications_read(uuid, timestamptz), public.notifications_purge(int),
  public.notification_prefs(uuid), public.notification_prefs_set(uuid, text[], boolean)
from public, anon, authenticated;
grant execute on function
  public.dm_start_direct(uuid, uuid), public.dm_start_group(uuid, text, uuid[]), public.dm_group_add(uuid, uuid, uuid), public.dm_group_remove(uuid, uuid, uuid),
  public.dm_group_rename(uuid, uuid, text), public.dm_leave(uuid, uuid), public.dm_start_booking(uuid, uuid),
  public.dm_send(uuid, uuid, text, text, text, uuid), public.dm_messages(uuid, uuid, int, timestamptz, uuid), public.dm_inbox(uuid, text, int, timestamptz, uuid),
  public.dm_mark_read(uuid, uuid), public.dm_mute(uuid, uuid, boolean), public.dm_answer_request(uuid, uuid, boolean), public.dm_delete_message(uuid, uuid),
  public.dm_people(uuid, uuid), public.dm_unread(uuid), public.dm_conversation(uuid, uuid),
  public.notifications_list(uuid, int, timestamptz, uuid), public.notifications_unread(uuid), public.notifications_read(uuid, timestamptz),
  public.notification_prefs(uuid), public.notification_prefs_set(uuid, text[], boolean)
to authenticated, service_role;
grant execute on function public.notifications_purge(int) to service_role;
commit;

-- ====================================================================================================
-- 20261105100000_safety_moderation
-- ====================================================================================================
begin;
-- Safety and moderation (customer app completion plan, M5; the stores require reporting, blocking and removal of user content).
--
--   * REPORTING: a person reports a post, a story, a comment, a profile, a message, a review or a job listing they can SEE, with a reason and optional words. One report from one profile for
--     one thing (a second one is the same report, said back as "already"); 20 reports a day from one profile; never your own. The words the reported thing said are
--     copied into the report, so BottlesUp can still read it after it is deleted. Reporting never asks for the community rules, and the person is never told what happened.
--   * THE QUEUE is for BottlesUp admins (cms_admins) only: reports are grouped by the thing reported, oldest first, with how many people reported it and why. Reporters are
--     counted, never named. An admin dismisses the reports, removes the content, suspends the person, or restores what was removed or suspended; each choice is written to
--     the audit log with a note. Nothing is removed automatically: a number of reports is a reason to look, not a verdict.
--   * SUSPENDING a person suspends every profile that login owns (the personal profile and the professional ones), because blocking works the same way (20261101110000).
--     A suspended profile is hidden from everyone else and cannot act; the login itself keeps working for tickets and bookings. A venue's or an event group's profile is
--     run by a team, so it is suspended on its own.
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

create table public.site_reports (
  id uuid primary key default gen_random_uuid(),
  -- The profile that reported; kept as null if that account is deleted, so the report survives.
  reporter uuid references public.site_profiles (id) on delete set null,
  kind text not null check (kind in ('post', 'comment', 'profile', 'message', 'review', 'job')),
  target uuid not null,
  -- Whose content it is (or the profile itself); null once that account is deleted.
  target_profile uuid references public.site_profiles (id) on delete set null,
  reason text not null check (reason in ('spam', 'harassment', 'hate', 'sexual', 'violence', 'scam', 'impersonation', 'self_harm', 'other')),
  details text check (details is null or char_length(btrim(details)) between 1 and 500),
  -- What the reported thing said when it was reported.
  excerpt text check (excerpt is null or char_length(excerpt) <= 500),
  status text not null default 'open' check (status in ('open', 'actioned', 'dismissed')),
  action text check (action in ('removed', 'suspended', 'dismissed', 'restored')),
  note text check (note is null or char_length(note) <= 500),
  handled_by uuid references auth.users (id) on delete set null,
  handled_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  constraint site_reports_handled check ((status = 'open') = (handled_at is null))
);
create unique index site_reports_one_per_reporter on public.site_reports (reporter, kind, target) where reporter is not null;
create index site_reports_open_idx on public.site_reports (created_at, id) where status = 'open';
create index site_reports_target_idx on public.site_reports (kind, target);
create index site_reports_reporter_day_idx on public.site_reports (reporter, created_at desc);

alter table public.site_reports enable row level security;
revoke all on table public.site_reports from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 1. Reporting
-- ---------------------------------------------------------------------------
create function public.report_create(p_actor uuid, p_kind text, p_target uuid, p_reason text, p_details text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_details text := nullif(btrim(coalesce(p_details, '')), '');
  v_owner uuid;
  v_excerpt text;
  v_id uuid;
begin
  perform public.profile_require_actor(p_actor);
  if not public.feature_enabled('social') then raise exception 'Reporting is not open yet.'; end if;
  if p_kind is null or p_kind not in ('post', 'comment', 'profile', 'message', 'review', 'job') then raise exception 'Say what you are reporting.'; end if;
  if p_reason is null or p_reason not in ('spam', 'harassment', 'hate', 'sexual', 'violence', 'scam', 'impersonation', 'self_harm', 'other') then raise exception 'Choose a reason.'; end if;
  if v_details is not null and char_length(v_details) > 500 then raise exception 'Keep it to 500 characters.'; end if;
  if p_target is null then raise exception 'This isn''t available.'; end if;

  -- Only what the reporter can see can be reported, and the answer for anything else is one sentence.
  if p_kind = 'post' then
    if not public.post_visible(p_actor, p_target) then raise exception 'This isn''t available.'; end if;
    select p.author, coalesce(left(p.caption, 500), '(' || p.kind || ' with no caption)') into v_owner, v_excerpt from public.site_posts p where p.id = p_target;
  elsif p_kind = 'comment' then
    select c.author, left(c.body, 500) into v_owner, v_excerpt
    from public.site_comments c
    where c.id = p_target and c.status = 'active' and public.post_visible(p_actor, c.post) and public.profile_visible(p_actor, c.author);
  elsif p_kind = 'profile' then
    if public.profile_visible(p_actor, p_target) then
      v_owner := p_target;
      select left((public.profile_mini(p_target) ->> 'display_name') || ' (@' || (public.profile_mini(p_target) ->> 'handle') || ')', 500) into v_excerpt;
    end if;
  elsif p_kind = 'message' then
    select m.sender, left(case when m.kind = 'text' then m.body else '[shared ' || m.kind || '] ' || coalesce(m.body, '') end, 500) into v_owner, v_excerpt
    from public.site_dm_messages m
    where m.id = p_target and m.deleted_at is null and public.dm_is_member(p_actor, m.conversation);
  elsif p_kind = 'job' then
    select j.poster, left(j.title || ': ' || j.description, 500) into v_owner, v_excerpt
    from public.site_jobs j
    where j.id = p_target and public.job_visible(p_actor, j.id);
  else
    select r.author, left('Rating ' || r.rating || '/5: ' || coalesce(r.body, ''), 500) into v_owner, v_excerpt
    from public.site_reviews r
    where r.id = p_target and r.status = 'active' and public.profile_visible(p_actor, r.author);
  end if;
  if v_owner is null then raise exception 'This isn''t available.'; end if;
  if public.profile_is_mine(v_owner) then raise exception 'You can''t report your own profile or what you wrote.'; end if;

  select r.id into v_id from public.site_reports r where r.reporter = p_actor and r.kind = p_kind and r.target = p_target;
  if v_id is not null then return jsonb_build_object('id', v_id, 'already', true); end if;

  if (select count(*) from public.site_reports r where r.reporter = p_actor and r.created_at > now() - interval '1 day') >= 20 then
    raise exception 'You have sent a lot of reports today. Our team is looking at them.';
  end if;

  insert into public.site_reports (reporter, kind, target, target_profile, reason, details, excerpt)
  values (p_actor, p_kind, p_target, v_owner, p_reason, v_details, v_excerpt)
  on conflict (reporter, kind, target) where reporter is not null do nothing
  returning id into v_id;
  if v_id is null then
    -- The same report arrived a moment ago from this profile.
    select r.id into v_id from public.site_reports r where r.reporter = p_actor and r.kind = p_kind and r.target = p_target;
    return jsonb_build_object('id', v_id, 'already', true);
  end if;
  return jsonb_build_object('id', v_id, 'already', false);
end;
$$;

-- ---------------------------------------------------------------------------
-- 2. The queue (BottlesUp admins only)
-- ---------------------------------------------------------------------------
-- p_status is 'open', 'actioned', 'dismissed' or 'all'. Open ones come oldest first; the others newest handled first.
create function public.cms_reports_list(p_status text default 'open', p_limit int default 50, p_offset int default 0)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_limit int := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_offset int := greatest(coalesce(p_offset, 0), 0);
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  if p_status is null or p_status not in ('open', 'actioned', 'dismissed', 'all') then raise exception 'Choose open, actioned, dismissed or all.'; end if;
  return coalesce((
    select jsonb_agg(g.item order by g.sort_key)
    from (
      select
        case when x.status = 'open' then extract(epoch from x.first_at) else -extract(epoch from x.handled_at) end as sort_key,
        jsonb_build_object(
          'kind', x.kind,
          'target', x.target,
          'status', x.status,
          'action', x.action,
          'note', x.note,
          'handled_at', x.handled_at,
          'reports', x.reports,
          'reporters', x.reporters,
          'reasons', x.reasons,
          'details', x.details,
          'excerpt', x.excerpt,
          'first_at', x.first_at,
          'last_at', x.last_at,
          'profile', case when x.target_profile is null then null else public.profile_mini(x.target_profile) || jsonb_build_object('status', (select s.status from public.site_profiles s where s.id = x.target_profile)) end,
          'state', case x.kind
            when 'post' then coalesce((select p.status from public.site_posts p where p.id = x.target), 'gone')
            when 'comment' then coalesce((select c.status from public.site_comments c where c.id = x.target), 'gone')
            when 'review' then coalesce((select r.status from public.site_reviews r where r.id = x.target), 'gone')
            when 'message' then coalesce((select case when m.deleted_at is null then 'active' else 'removed' end from public.site_dm_messages m where m.id = x.target), 'gone')
            when 'job' then coalesce((select case when j.status = 'removed' then 'removed' else 'active' end from public.site_jobs j where j.id = x.target), 'gone')
            else coalesce((select case when s.status = 'active' then 'active' else 'suspended' end from public.site_profiles s where s.id = x.target), 'gone')
          end
        ) as item
      from (
        select r.kind, r.target, r.status, r.handled_at,
               (array_agg(r.target_profile))[1] as target_profile,
               (array_agg(r.action))[1] as action,
               (array_agg(r.note))[1] as note,
               count(*)::int as reports,
               count(distinct r.reporter)::int as reporters,
               (select coalesce(jsonb_agg(d.reason order by d.reason), '[]'::jsonb) from (select distinct r2.reason from public.site_reports r2
                  where r2.kind = r.kind and r2.target = r.target and r2.status = r.status and r2.handled_at is not distinct from r.handled_at) d) as reasons,
               (select coalesce(jsonb_agg(d.details), '[]'::jsonb) from (select r2.details from public.site_reports r2
                  where r2.kind = r.kind and r2.target = r.target and r2.status = r.status and r2.handled_at is not distinct from r.handled_at and r2.details is not null
                  order by r2.created_at limit 5) d) as details,
               (array_agg(r.excerpt order by r.created_at))[1] as excerpt,
               min(r.created_at) as first_at,
               max(r.created_at) as last_at
        from public.site_reports r
        where p_status = 'all' or r.status = p_status
        group by r.kind, r.target, r.status, r.handled_at
      ) x
      order by 1
      limit v_limit offset v_offset
    ) g
  ), '[]'::jsonb);
end;
$$;

-- Every profile that belongs to the same PERSON as p_profile (see profile_key), or the profile alone for a venue's or an event group's.
create function public.moderation_person_profiles(p_profile uuid)
returns setof uuid
language sql
stable
security definer
set search_path = public
as $$
  select s.id from public.site_profiles s
  where s.id = p_profile or (s.user_id is not null and s.user_id = (select p.user_id from public.site_profiles p where p.id = p_profile))
$$;

-- Decide what happens to everything reported about one thing. p_action: 'dismiss' (nothing to do), 'remove' (a post, comment, message or review disappears for everyone),
-- 'suspend' (the person behind it, or the profile, is suspended) or 'restore' (undo a removal or a suspension). One note, written to the audit log.
create function public.cms_report_resolve(p_kind text, p_target uuid, p_action text, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_profile uuid;
  v_open int;
  v_any int;
  v_n int;
  -- One moment for the whole decision, so the reports it settles stay together in the list.
  v_at timestamptz := clock_timestamp();
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can change this.'; end if;
  if p_kind is null or p_kind not in ('post', 'comment', 'profile', 'message', 'review', 'job') or p_target is null then raise exception 'Say what was reported.'; end if;
  if p_action is null or p_action not in ('dismiss', 'remove', 'suspend', 'restore') then raise exception 'Choose dismiss, remove, suspend or restore.'; end if;
  if v_note is not null and char_length(v_note) > 500 then raise exception 'Keep the note to 500 characters.'; end if;

  select count(*) filter (where r.status = 'open'), count(*), (array_agg(r.target_profile))[1]
  into v_open, v_any, v_profile
  from public.site_reports r where r.kind = p_kind and r.target = p_target;
  if v_any = 0 then raise exception 'Nobody has reported this.'; end if;
  if p_action <> 'restore' and v_open = 0 then raise exception 'These reports have already been handled.'; end if;

  if p_action = 'remove' then
    if p_kind = 'profile' then raise exception 'A profile is suspended, not removed.'; end if;
    if p_kind = 'post' then update public.site_posts set status = 'removed' where id = p_target;
    elsif p_kind = 'comment' then update public.site_comments set status = 'removed' where id = p_target;
    elsif p_kind = 'review' then update public.site_reviews set status = 'removed' where id = p_target;
    elsif p_kind = 'job' then update public.site_jobs set status = 'removed', closed_at = coalesce(closed_at, now()) where id = p_target;
    else update public.site_dm_messages set deleted_at = coalesce(deleted_at, now()) where id = p_target;
    end if;
  elsif p_action = 'suspend' then
    if v_profile is null then raise exception 'There is no profile left to suspend.'; end if;
    update public.site_profiles set status = 'suspended' where id in (select public.moderation_person_profiles(v_profile));
  elsif p_action = 'restore' then
    if p_kind = 'post' then update public.site_posts set status = 'active' where id = p_target;
    elsif p_kind = 'comment' then update public.site_comments set status = 'active' where id = p_target;
    elsif p_kind = 'review' then update public.site_reviews set status = 'active' where id = p_target;
    elsif p_kind = 'job' then update public.site_jobs set status = 'closed' where id = p_target and status = 'removed';
    elsif p_kind = 'message' then update public.site_dm_messages set deleted_at = null where id = p_target;
    end if;
    -- What was done to the person behind it is undone as well, whatever was reported.
    if v_profile is not null then
      update public.site_profiles set status = 'active' where id in (select public.moderation_person_profiles(v_profile));
    end if;
  end if;

  if p_action = 'restore' then
    update public.site_reports set status = 'dismissed', action = 'restored', note = v_note, handled_by = auth.uid(), handled_at = v_at
    where kind = p_kind and target = p_target and status = 'actioned';
  else
    update public.site_reports
    set status = case p_action when 'dismiss' then 'dismissed' else 'actioned' end,
        action = case p_action when 'dismiss' then 'dismissed' when 'remove' then 'removed' else 'suspended' end,
        note = v_note, handled_by = auth.uid(), handled_at = v_at
    where kind = p_kind and target = p_target and status = 'open';
  end if;
  get diagnostics v_n = row_count;

  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'report_' || p_action, 'report', p_target::text,
          jsonb_build_object('kind', p_kind, 'note', v_note, 'reports', v_n));
  return jsonb_build_object('handled', v_n);
end;
$$;

-- Find a profile by its username or name, to suspend or restore it without a report.
create function public.cms_find_profiles(p_query text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_q text := lower(btrim(coalesce(p_query, '')));
  -- What was typed is text to find, not a pattern: a percent sign or underscore matches itself.
  v_like text;
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  if char_length(v_q) < 2 then raise exception 'Type at least 2 letters.'; end if;
  v_like := replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', f.id, 'kind', f.kind, 'handle', f.handle, 'display_name', f.name, 'category', f.category, 'status', f.status) order by f.handle)
    from (
      select p.id, p.kind, p.category, p.status,
             case p.kind when 'personal' then pr.username else p.handle end as handle,
             case p.kind when 'personal' then coalesce(nullif(btrim(pr.name), ''), pr.username) else p.display_name end as name
      from public.site_profiles p
      left join public.profiles pr on pr.id = p.user_id and p.kind = 'personal'
      where lower(case p.kind when 'personal' then pr.username else p.handle end) like v_like
         or lower(case p.kind when 'personal' then pr.name else p.display_name end) like v_like
      limit 20
    ) f
  ), '[]'::jsonb);
end;
$$;

-- Suspend or restore the person behind a profile directly (an appeal, or something a report did not catch).
create function public.cms_profile_set_status(p_profile uuid, p_suspended boolean, p_note text default null)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_n int;
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can change this.'; end if;
  if p_suspended is null then raise exception 'Choose suspend or restore.'; end if;
  if v_note is not null and char_length(v_note) > 500 then raise exception 'Keep the note to 500 characters.'; end if;
  if not exists (select 1 from public.site_profiles s where s.id = p_profile) then raise exception 'There is no such profile.'; end if;
  update public.site_profiles set status = case when p_suspended then 'suspended' else 'active' end where id in (select public.moderation_person_profiles(p_profile));
  get diagnostics v_n = row_count;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), case when p_suspended then 'profile_suspended' else 'profile_restored' end, 'profile', p_profile::text,
          jsonb_build_object('note', v_note, 'profiles', v_n));
  return jsonb_build_object('profiles', v_n, 'suspended', p_suspended);
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. Daily housekeeping (a scheduled job, as the service role)
-- ---------------------------------------------------------------------------
-- Stories that expired more than p_story_days ago are deleted (they are hidden from everyone the moment they expire; this frees the rows, and their files become unused and are
-- removed by sweep-social-media); read notifications older than p_notification_days (never fewer than 7); caption-idea requests older than two days (they only count a day). The delivery address of a plaque that arrived 90 days ago is wiped.
-- Posts, comments, messages and reports are never touched here: reports are the evidence BottlesUp keeps.
create function public.social_housekeeping(p_story_days int default 7, p_notification_days int default 90)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_stories int;
  v_notifications int;
  v_uses int;
  v_plaques int;
begin
  delete from public.site_posts where kind = 'story' and expires_at < now() - make_interval(days => greatest(coalesce(p_story_days, 7), 1));
  get diagnostics v_stories = row_count;
  v_notifications := public.notifications_purge(coalesce(p_notification_days, 90));
  delete from public.site_ai_caption_uses where created_at < now() - interval '2 days';
  get diagnostics v_uses = row_count;
  v_plaques := public.plaque_addresses_wipe();
  return jsonb_build_object('stories', v_stories, 'notifications', v_notifications, 'caption_uses', v_uses, 'plaque_addresses', v_plaques);
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Who may call what
-- ---------------------------------------------------------------------------
revoke all on function
  public.report_create(uuid, text, uuid, text, text), public.cms_reports_list(text, int, int), public.moderation_person_profiles(uuid),
  public.cms_report_resolve(text, uuid, text, text), public.cms_find_profiles(text), public.cms_profile_set_status(uuid, boolean, text), public.social_housekeeping(int, int)
from public, anon, authenticated;
grant execute on function public.social_housekeeping(int, int) to service_role;
grant execute on function
  public.report_create(uuid, text, uuid, text, text), public.cms_reports_list(text, int, int),
  public.cms_report_resolve(text, uuid, text, text), public.cms_find_profiles(text), public.cms_profile_set_status(uuid, boolean, text)
to authenticated, service_role;
commit;

-- ====================================================================================================
-- 20261106100000_split_payments
-- ====================================================================================================
begin;
-- Splitting the bill (customer app completion plan, M6; client plan page 8): the person who booked a table asks friends to pay a share of what is STILL OWED AT THE CLUB. Each friend pays
-- their share online on Stripe's page; the amount is added to what the booking has been paid (exactly as a payment recorded at the club is), so the venue's own screens show the balance
-- going down with no change on their side.
--
--   * WHAT IS SPLIT: only the balance after the booking is confirmed (amount_total_cents - amount_paid_cents), never the first checkout (that keeps its 10-minute hold untouched). The
--     host books and pays as before; splitting is an optional extra on a confirmed booking.
--   * WHO: the host is the person whose verified e-mail is the booking's (the same proof the rest of the site uses); the friends are people with a personal profile who have not blocked
--     the host and whom the host has not blocked. A friend sees only the venue, the night, the host's first name and their own amount: never the booking's code, total or other shares.
--   * HOW MUCH: 1 to 20 shares, each between 5.00 and 5,000.00, adding up to no more than the balance at that moment. Equal or uneven is the app's choice: the database only checks.
--   * WHEN: a deadline chosen by the host, at least an hour away, at most 14 days away and no later than the booking is over (twelve hours after arrival). A share unpaid at the
--     deadline lapses; the host owes the rest at the club as before. Paying is refused after the deadline, so nothing needs to run on a timer.
--   * REFUNDS: a share is paid back IN FULL when the host cancels the split, when the venue cancels or refunds the booking, when the host's account is deleted, or when the money could not
--     be applied (the table was settled at the club in the meantime: the surplus). After the booking is over a paid share stays. The refund itself is done by the website's
--     `process-split-refunds` / `cancel-split` functions through Stripe; the database only says what is due and records what was paid back.
--   * THE MONEY NEVER MOVES TWICE: applying a payment is idempotent by Stripe session; a refund is recorded once per Stripe refund id.
--   * NO FEE: the BottlesUp fee and tax were already part of the booking's total; a share adds nothing on top.
--   * Everything refuses with "Splitting the bill is not open yet." until the `split_payments` switch is on (20261101100000).
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table public.site_splits (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.site_table_bookings (id) on delete cascade,
  -- The person who booked. If their account is deleted the split ends and everything paid is paid back (see split_refunds_due).
  host uuid references auth.users (id) on delete set null,
  status text not null default 'open' check (status in ('open', 'cancelled')),
  deadline timestamptz not null,
  created_at timestamptz not null default clock_timestamp(),
  cancelled_at timestamptz,
  constraint site_splits_cancelled_shape check ((status = 'cancelled') = (cancelled_at is not null))
);
create unique index site_splits_one_open on public.site_splits (booking_id) where status = 'open';
create index site_splits_booking_idx on public.site_splits (booking_id, created_at desc);
create index site_splits_host_idx on public.site_splits (host, created_at desc);

create table public.site_split_shares (
  id uuid primary key default gen_random_uuid(),
  split_id uuid not null references public.site_splits (id) on delete cascade,
  -- The friend's personal profile. Set to nothing if their account is deleted (a share they already paid stays applied; nothing names them).
  payer uuid references public.site_profiles (id) on delete set null,
  amount_cents int not null check (amount_cents between 500 and 500000),
  status text not null default 'unpaid' check (status in ('unpaid', 'pending', 'paid', 'declined', 'void')),
  stripe_session_id text unique,
  stripe_payment_intent_id text,
  -- A started payment page lapses after this; the share may then be started again.
  pending_until timestamptz,
  paid_at timestamptz,
  -- What Stripe took, what of it counts towards the booking, and what of that has been taken back off the booking again (a refund while the booking is still on).
  paid_cents int not null default 0 check (paid_cents >= 0),
  applied_cents int not null default 0 check (applied_cents >= 0),
  reversed_cents int not null default 0 check (reversed_cents >= 0),
  -- What has to be paid back to the friend, and what has been.
  refund_due_cents int not null default 0 check (refund_due_cents >= 0),
  refunded_cents int not null default 0 check (refunded_cents >= 0),
  refund_id text,
  refunded_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  constraint site_split_shares_money check (applied_cents <= paid_cents and reversed_cents <= applied_cents and refund_due_cents <= paid_cents and refunded_cents <= refund_due_cents),
  constraint site_split_shares_paid_shape check ((status = 'paid') = (paid_at is not null))
);
create unique index site_split_shares_one_per_person on public.site_split_shares (split_id, payer) where payer is not null;
create index site_split_shares_payer_idx on public.site_split_shares (payer, created_at desc) where payer is not null;
create index site_split_shares_refund_idx on public.site_split_shares (split_id) where refund_due_cents > refunded_cents;

alter table public.site_splits enable row level security;
alter table public.site_split_shares enable row level security;
revoke all on table public.site_splits, public.site_split_shares from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Helpers (internal)
-- ---------------------------------------------------------------------------
create function public.split_require_on()
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if not public.feature_enabled('split_payments') then raise exception 'Splitting the bill is not open yet.'; end if;
end;
$$;

-- Is the signed-in person the one who made this booking? (Their sign-in e-mail equals the booking's, ignoring case: the same proof the rest of the site uses.)
create function public.split_is_host(p_booking uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select auth.uid() is not null and coalesce(btrim(auth.email()), '') <> '' and exists (
    select 1 from public.site_table_bookings b where b.id = p_booking and lower(btrim(b.customer_email)) = lower(btrim(auth.email()))
  )
$$;

-- What the friend sees of the share's state. Lapsed and cancelled things are said as such, whatever the stored status.
create function public.split_share_state(p_share uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case
    when s.status = 'paid' and s.refund_due_cents > 0 and s.refunded_cents >= s.refund_due_cents then 'refunded'
    when s.status = 'paid' and s.refund_due_cents > s.refunded_cents then 'refunding'
    when s.status = 'paid' then 'paid'
    when s.status = 'declined' then 'declined'
    when s.status = 'void' or sp.status = 'cancelled' or b.status <> 'paid' then 'cancelled'
    when now() > sp.deadline then 'expired'
    when s.status = 'pending' and s.pending_until > now() then 'pending'
    else 'unpaid'
  end
  from public.site_split_shares s
  join public.site_splits sp on sp.id = s.split_id
  join public.site_table_bookings b on b.id = sp.booking_id
  where s.id = p_share
$$;

-- The first word of a person's name, for what a friend is told about the host.
create function public.split_first_name(p_user uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(nullif(split_part(btrim(coalesce(pr.name, '')), ' ', 1), ''), nullif(pr.username, ''), 'A friend') from public.profiles pr where pr.id = p_user
$$;

-- The host's view of one split.
create function public.split_card(p_split uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  sp public.site_splits;
  b public.site_table_bookings;
  v_shares jsonb;
  v_collected int;
  v_outstanding int;
  v_state text;
  v_all_paid boolean;
begin
  select * into sp from public.site_splits where id = p_split;
  if not found then return null; end if;
  select * into b from public.site_table_bookings where id = sp.booking_id;
  select coalesce(jsonb_agg(jsonb_build_object(
           'id', s.id,
           'payer', case when s.payer is null then null else public.profile_mini(s.payer) end,
           'amount_cents', s.amount_cents,
           'status', public.split_share_state(s.id),
           'paid_at', s.paid_at) order by s.created_at, s.id), '[]'::jsonb)
    into v_shares from public.site_split_shares s where s.split_id = p_split;
  select coalesce(sum(s.applied_cents - s.reversed_cents), 0)::int into v_collected from public.site_split_shares s where s.split_id = p_split and s.status = 'paid';
  select coalesce(sum(s.amount_cents), 0)::int into v_outstanding from public.site_split_shares s where s.split_id = p_split and public.split_share_state(s.id) in ('unpaid', 'pending');
  select bool_and(public.split_share_state(s.id) in ('paid', 'refunding', 'refunded')) into v_all_paid from public.site_split_shares s where s.split_id = p_split;
  v_state := case
    when sp.status = 'cancelled' then 'cancelled'
    when coalesce(v_all_paid, false) then 'complete'
    when now() > sp.deadline then 'expired'
    else 'open'
  end;
  return jsonb_build_object(
    'id', sp.id,
    'booking_id', sp.booking_id,
    'state', v_state,
    'deadline', sp.deadline,
    'currency', b.currency,
    'balance_cents', greatest(b.amount_total_cents - b.amount_paid_cents, 0),
    'collected_cents', v_collected,
    'outstanding_cents', v_outstanding,
    'shares', v_shares,
    'created_at', sp.created_at
  );
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. The host: make a split, look at it, cancel it
-- ---------------------------------------------------------------------------
-- p_shares: [{"payer": <personal profile id>, "amount_cents": 2500}, ...]
create function public.split_create(p_booking uuid, p_shares jsonb, p_deadline timestamptz)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_table_bookings;
  v_balance int;
  v_hours numeric;
  v_item jsonb;
  v_payer uuid;
  v_amount int;
  v_payer_user uuid;
  v_total int := 0;
  v_seen uuid[] := '{}';
  v_id uuid;
begin
  perform public.split_require_on();
  if p_booking is null then raise exception 'Choose a booking.'; end if;
  select * into b from public.site_table_bookings where id = p_booking for update;
  if not found or not public.split_is_host(p_booking) then raise exception 'This booking is not yours.'; end if;
  if b.status <> 'paid' then raise exception 'Only a confirmed booking can be split.'; end if;
  v_balance := greatest(b.amount_total_cents - b.amount_paid_cents, 0);
  if v_balance <= 0 then raise exception 'Nothing is left to pay on this booking.'; end if;
  v_hours := public.booking_hours_to_arrival(p_booking);
  if v_hours is null then raise exception 'This booking has no arrival time.'; end if;
  if v_hours <= -12 then raise exception 'This booking is over.'; end if;
  if exists (select 1 from public.site_refund_requests r where r.booking_id = p_booking and r.status in ('requested', 'approved', 'processing')) then
    raise exception 'A refund is being looked at on this booking, so it cannot be split now.';
  end if;
  if exists (select 1 from public.site_splits s where s.booking_id = p_booking and s.status = 'open') then
    raise exception 'This booking already has a split: cancel it before making a new one.';
  end if;
  if (select count(*) from public.site_splits s where s.host = auth.uid() and s.created_at > now() - interval '1 day') >= 5 then
    raise exception 'You have made a lot of splits today. Try again tomorrow.';
  end if;

  if p_deadline is null or p_deadline < now() + interval '1 hour' then raise exception 'Choose a deadline at least an hour from now.'; end if;
  if p_deadline > now() + interval '14 days' then raise exception 'Choose a deadline within 14 days.'; end if;
  if p_deadline > now() + make_interval(secs => (v_hours + 12) * 3600) then raise exception 'The deadline cannot be after the booking is over.'; end if;

  if p_shares is null or jsonb_typeof(p_shares) <> 'array' or jsonb_array_length(p_shares) < 1 then raise exception 'Choose at least one friend.'; end if;
  if jsonb_array_length(p_shares) > 20 then raise exception 'A split can have up to 20 friends.'; end if;

  insert into public.site_splits (booking_id, host, deadline) values (p_booking, auth.uid(), p_deadline) returning id into v_id;
  for v_item in select * from jsonb_array_elements(p_shares) loop
    if jsonb_typeof(v_item) <> 'object' or jsonb_typeof(v_item -> 'payer') is distinct from 'string' or jsonb_typeof(v_item -> 'amount_cents') is distinct from 'number' then
      raise exception 'Each share needs a friend and an amount.';
    end if;
    v_payer := (v_item ->> 'payer')::uuid;
    if (v_item ->> 'amount_cents') !~ '^[0-9]+$' then raise exception 'Each amount must be a whole number of cents.'; end if;
    v_amount := (v_item ->> 'amount_cents')::int;
    if v_amount < 500 then raise exception 'The smallest share is 5.00.'; end if;
    if v_amount > 500000 then raise exception 'The largest share is 5,000.00.'; end if;
    if v_payer = any (v_seen) then raise exception 'Each friend can be asked once.'; end if;
    v_seen := v_seen || v_payer;
    select p.user_id into v_payer_user from public.site_profiles p where p.id = v_payer and p.kind = 'personal' and p.status = 'active';
    if v_payer_user is null then raise exception 'One of the people you chose is not available.'; end if;
    if v_payer_user = auth.uid() then raise exception 'You do not need to ask yourself: your part is what is left at the club.'; end if;
    if exists (select 1 from public.site_blocks k where (k.blocker_key = v_payer_user and k.blocked_key = auth.uid()) or (k.blocker_key = auth.uid() and k.blocked_key = v_payer_user)) then
      raise exception 'One of the people you chose is not available.';
    end if;
    v_total := v_total + v_amount;
    insert into public.site_split_shares (split_id, payer, amount_cents) values (v_id, v_payer, v_amount);
  end loop;
  if v_total > v_balance then
    raise exception 'The shares add up to more than what is left to pay on this booking (% %).', upper(b.currency), to_char(v_balance / 100.0, 'FM999999990.00');
  end if;

  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'guest'), 'split.created', 'site_splits', v_id::text,
          jsonb_build_object('booking_id', p_booking, 'shares', jsonb_array_length(p_shares), 'total_cents', v_total, 'deadline', p_deadline));
  return public.split_card(v_id);
end;
$$;

-- The booking's split as its host sees it: the open one, otherwise the latest. Null when it never had one.
create function public.split_for_booking(p_booking uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_id uuid;
begin
  perform public.split_require_on();
  if not public.split_is_host(p_booking) then raise exception 'This booking is not yours.'; end if;
  select s.id into v_id from public.site_splits s where s.booking_id = p_booking order by (s.status = 'open') desc, s.created_at desc, s.id limit 1;
  if v_id is null then return null; end if;
  return public.split_card(v_id);
end;
$$;

-- Cancels the split. Friends who have not paid are released; those who have are paid back in full (the website does it right after: cancel-split).
create function public.split_cancel(p_split uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  sp public.site_splits;
  b public.site_table_bookings;
  v_refunds int;
begin
  perform public.split_require_on();
  select * into sp from public.site_splits where id = p_split for update;
  if not found then raise exception 'This split is not available.'; end if;
  select * into b from public.site_table_bookings where id = sp.booking_id for update;
  if not public.split_is_host(sp.booking_id) then raise exception 'This split is not available.'; end if;
  if sp.status = 'cancelled' then raise exception 'This split is already cancelled.'; end if;
  if coalesce(public.booking_hours_to_arrival(sp.booking_id), 0) <= -12 then raise exception 'This booking is over, so the split can no longer be cancelled here. Ask the venue.'; end if;
  update public.site_splits set status = 'cancelled', cancelled_at = clock_timestamp() where id = p_split;
  update public.site_split_shares set status = 'void' where split_id = p_split and status in ('unpaid', 'pending');
  update public.site_split_shares set refund_due_cents = paid_cents where split_id = p_split and status = 'paid' and refund_due_cents < paid_cents;
  get diagnostics v_refunds = row_count;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'guest'), 'split.cancelled', 'site_splits', p_split::text, jsonb_build_object('booking_id', sp.booking_id, 'refunds', v_refunds));
  return public.split_card(p_split);
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. The friend: what they are asked to pay, say no, start paying, ask how it went
-- ---------------------------------------------------------------------------
-- The shares the signed-in person has been asked for, newest first. Only what a friend should know.
create function public.split_my_shares()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.split_require_on();
  return coalesce((
    select jsonb_agg(row order by created desc, sid)
      from (
        select s.created_at as created, s.id as sid, jsonb_build_object(
                 'id', s.id,
                 'state', public.split_share_state(s.id),
                 'amount_cents', s.amount_cents,
                 'currency', b.currency,
                 'deadline', sp.deadline,
                 'host', public.split_first_name(sp.host),
                 'venue', v.name,
                 'booking_date', b.booking_date,
                 'start_time', t.start_time,
                 'paid_at', s.paid_at) as row
          from public.site_split_shares s
          join public.site_splits sp on sp.id = s.split_id
          join public.site_table_bookings b on b.id = sp.booking_id
          join public.site_venues v on v.id = b.venue_id
          left join public.site_venue_time_slots t on t.id = b.time_slot_id
          join public.site_profiles me on me.id = s.payer and me.user_id = auth.uid() and me.kind = 'personal'
         where not exists (select 1 from public.site_blocks k where (k.blocker_key = auth.uid() and k.blocked_key = sp.host) or (k.blocker_key = sp.host and k.blocked_key = auth.uid()))
           and s.created_at > now() - interval '60 days'
         limit 100
      ) x
  ), '[]'::jsonb);
end;
$$;

-- One share the signed-in person was asked for, or an error that never says why it is not theirs.
create function public.split_share_status(p_share uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  s public.site_split_shares;
begin
  perform public.split_require_on();
  select x.* into s from public.site_split_shares x
    join public.site_profiles me on me.id = x.payer and me.user_id = auth.uid()
   where x.id = p_share;
  if not found then raise exception 'This request is not available.'; end if;
  return jsonb_build_object('id', s.id, 'state', public.split_share_state(s.id), 'amount_cents', s.amount_cents, 'paid_at', s.paid_at);
end;
$$;

create function public.split_share_decline(p_share uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s public.site_split_shares;
begin
  perform public.split_require_on();
  select x.* into s from public.site_split_shares x
    join public.site_profiles me on me.id = x.payer and me.user_id = auth.uid()
   where x.id = p_share for update of x;
  if not found then raise exception 'This request is not available.'; end if;
  if public.split_share_state(p_share) not in ('unpaid', 'expired') then
    raise exception 'This request can no longer be turned down.';
  end if;
  update public.site_split_shares set status = 'declined' where id = p_share;
  return jsonb_build_object('id', p_share, 'state', 'declined');
end;
$$;

-- Checks that the signed-in person may pay this share NOW and says what to charge. The website's create-split-checkout calls it with the person's own login before it asks Stripe.
-- If a payment page was started less than half an hour ago, its Stripe session is returned so the same page is reopened and nobody pays twice.
create function public.split_share_begin(p_share uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s public.site_split_shares;
  sp public.site_splits;
  b public.site_table_bookings;
  v_state text;
  v_slot text;
begin
  perform public.split_require_on();
  select x.* into s from public.site_split_shares x
    join public.site_profiles me on me.id = x.payer and me.user_id = auth.uid()
   where x.id = p_share;
  if not found then raise exception 'This request is not available.'; end if;
  select * into sp from public.site_splits where id = s.split_id;
  select * into b from public.site_table_bookings where id = sp.booking_id;
  if exists (select 1 from public.site_blocks k where (k.blocker_key = auth.uid() and k.blocked_key = sp.host) or (k.blocker_key = sp.host and k.blocked_key = auth.uid())) then
    raise exception 'This request is not available.';
  end if;
  v_state := public.split_share_state(p_share);
  if v_state = 'paid' or v_state = 'refunding' or v_state = 'refunded' then raise exception 'You already paid this.'; end if;
  if v_state = 'declined' then raise exception 'You turned this request down.'; end if;
  if v_state = 'cancelled' then raise exception 'This request was cancelled.'; end if;
  if v_state = 'expired' then raise exception 'The time to pay this has passed. Ask the host to send a new request.'; end if;
  if greatest(b.amount_total_cents - b.amount_paid_cents, 0) < s.amount_cents then
    raise exception 'The rest of this table has been paid in the meantime, so there is nothing left for you to pay.';
  end if;
  select to_char(t.start_time, 'HH24:MI') into v_slot from public.site_venue_time_slots t where t.id = b.time_slot_id;
  return jsonb_build_object(
    'id', s.id,
    'amount_cents', s.amount_cents,
    'currency', b.currency,
    'booking_id', b.id,
    'venue', (select v.name from public.site_venues v where v.id = b.venue_id),
    'booking_date', b.booking_date,
    'start_time', v_slot,
    'host', public.split_first_name(sp.host),
    'pending_session', case when v_state = 'pending' then s.stripe_session_id else null end);
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. The website's payment functions (the service role only)
-- ---------------------------------------------------------------------------
-- A payment page was created for this share.
create function public.split_share_attach(p_share uuid, p_session text, p_until timestamptz)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_session is null or btrim(p_session) = '' then raise exception 'a Stripe session is needed'; end if;
  update public.site_split_shares set status = 'pending', stripe_session_id = p_session, pending_until = p_until where id = p_share and status in ('unpaid', 'pending');
  if not found then raise exception 'this share cannot be paid now'; end if;
end;
$$;

-- Stripe has taken the money for this session. Idempotent: the same session twice changes nothing the second time. Answers {result, applied_cents, refund_cents}:
--   applied  - the share counts towards the booking (and any surplus is to be paid back)
--   refund   - the money could not be applied (split cancelled, booking no longer on, amount not the share's): all of it is to be paid back
--   already  - this session was recorded before
--   unknown  - no share has this session
create function public.split_share_paid(p_session text, p_payment_intent text, p_amount int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s public.site_split_shares;
  sp public.site_splits;
  b public.site_table_bookings;
  v_apply int;
begin
  select * into s from public.site_split_shares where stripe_session_id = p_session for update;
  if not found then return jsonb_build_object('result', 'unknown'); end if;
  if s.status = 'paid' then return jsonb_build_object('result', 'already', 'applied_cents', s.applied_cents, 'refund_cents', s.refund_due_cents - s.refunded_cents); end if;
  select * into sp from public.site_splits where id = s.split_id for update;
  select * into b from public.site_table_bookings where id = sp.booking_id for update;
  if p_amount is null or p_amount <= 0 then raise exception 'an amount is needed'; end if;

  if sp.status <> 'open' or sp.host is null or b.status <> 'paid' or s.status in ('declined', 'void') or p_amount <> s.amount_cents then
    update public.site_split_shares
       set status = 'paid', paid_at = clock_timestamp(), stripe_payment_intent_id = p_payment_intent, paid_cents = p_amount, applied_cents = 0, refund_due_cents = p_amount
     where id = s.id;
    insert into public.audit_log (actor_email, action, entity_type, entity_id, details)
    values ('stripe', 'split.share_paid_unusable', 'site_split_shares', s.id::text, jsonb_build_object('booking_id', b.id, 'amount_cents', p_amount, 'split_status', sp.status, 'booking_status', b.status));
    return jsonb_build_object('result', 'refund', 'applied_cents', 0, 'refund_cents', p_amount);
  end if;

  v_apply := least(p_amount, greatest(b.amount_total_cents - b.amount_paid_cents, 0));
  update public.site_table_bookings set amount_paid_cents = amount_paid_cents + v_apply where id = b.id;
  update public.site_split_shares
     set status = 'paid', paid_at = clock_timestamp(), stripe_payment_intent_id = p_payment_intent, paid_cents = p_amount, applied_cents = v_apply, refund_due_cents = p_amount - v_apply
   where id = s.id;
  insert into public.audit_log (actor_email, action, entity_type, entity_id, details)
  values ('stripe', 'split.share_paid', 'site_split_shares', s.id::text, jsonb_build_object('booking_id', b.id, 'amount_cents', p_amount, 'applied_cents', v_apply, 'surplus_cents', p_amount - v_apply));
  return jsonb_build_object('result', 'applied', 'applied_cents', v_apply, 'refund_cents', p_amount - v_apply);
end;
$$;

-- What has to be paid back now. First it looks for paid shares that should be paid back in full and are not marked so yet (the booking was cancelled or refunded, or the host's
-- account is gone; a share that only has a surplus due is raised to its whole amount), then lists every share with money due.
create function public.split_refunds_due()
returns table (share_id uuid, split_id uuid, stripe_payment_intent_id text, cents int)
language plpgsql
security definer
set search_path = public
as $$
begin
  update public.site_split_shares s
     set refund_due_cents = s.paid_cents
    from public.site_splits sp, public.site_table_bookings b
   where sp.id = s.split_id and b.id = sp.booking_id and s.status = 'paid' and s.paid_cents > 0 and s.refund_due_cents < s.paid_cents
     and (sp.host is null or b.status in ('cancelled', 'refunded'));
  return query
    select s.id, s.split_id, s.stripe_payment_intent_id, (s.refund_due_cents - s.refunded_cents)::int
      from public.site_split_shares s
     where s.refund_due_cents > s.refunded_cents and s.stripe_payment_intent_id is not null
     order by s.paid_at, s.id;
end;
$$;

-- Stripe has paid back p_cents of this share (p_refund_id is Stripe's). Idempotent by refund id. While the booking is still on, what had been added to it comes off again.
create function public.split_share_refunded(p_share uuid, p_refund_id text, p_cents int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s public.site_split_shares;
  sp public.site_splits;
  b public.site_table_bookings;
  v_take int;
  v_reverse int;
begin
  if p_refund_id is null or btrim(p_refund_id) = '' or p_cents is null or p_cents <= 0 then raise exception 'a refund id and an amount are needed'; end if;
  select * into s from public.site_split_shares where id = p_share for update;
  if not found then raise exception 'this share does not exist'; end if;
  if s.refund_id is not distinct from p_refund_id and s.refunded_cents > 0 then return jsonb_build_object('result', 'already', 'refunded_cents', s.refunded_cents); end if;
  select * into sp from public.site_splits where id = s.split_id for update;
  select * into b from public.site_table_bookings where id = sp.booking_id for update;
  v_take := least(p_cents, s.refund_due_cents - s.refunded_cents);
  if v_take <= 0 then return jsonb_build_object('result', 'nothing_due', 'refunded_cents', s.refunded_cents); end if;
  v_reverse := 0;
  if b.status = 'paid' then
    -- Money paid back goes first against what was never added to the booking (the surplus); only the rest comes off the booking again.
    v_reverse := least(greatest(v_take - greatest((s.paid_cents - s.applied_cents) - s.refunded_cents, 0), 0), s.applied_cents - s.reversed_cents);
    update public.site_table_bookings set amount_paid_cents = greatest(amount_paid_cents - v_reverse, 0) where id = b.id;
  end if;
  update public.site_split_shares
     set refunded_cents = refunded_cents + v_take, reversed_cents = reversed_cents + v_reverse, refund_id = p_refund_id, refunded_at = clock_timestamp()
   where id = p_share;
  insert into public.audit_log (actor_email, action, entity_type, entity_id, details)
  values ('stripe', 'split.share_refunded', 'site_split_shares', p_share::text, jsonb_build_object('booking_id', b.id, 'refund_id', p_refund_id, 'refunded_cents', v_take, 'taken_off_booking_cents', v_reverse));
  return jsonb_build_object('result', 'refunded', 'refunded_cents', s.refunded_cents + v_take, 'taken_off_booking_cents', v_reverse);
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. Who may call what
-- ---------------------------------------------------------------------------
revoke all on function
  public.split_require_on(), public.split_is_host(uuid), public.split_share_state(uuid), public.split_first_name(uuid), public.split_card(uuid),
  public.split_create(uuid, jsonb, timestamptz), public.split_for_booking(uuid), public.split_cancel(uuid), public.split_my_shares(), public.split_share_status(uuid),
  public.split_share_decline(uuid), public.split_share_begin(uuid), public.split_share_attach(uuid, text, timestamptz), public.split_share_paid(text, text, int),
  public.split_refunds_due(), public.split_share_refunded(uuid, text, int)
from public, anon, authenticated;
grant execute on function
  public.split_create(uuid, jsonb, timestamptz), public.split_for_booking(uuid), public.split_cancel(uuid), public.split_my_shares(), public.split_share_status(uuid),
  public.split_share_decline(uuid), public.split_share_begin(uuid)
to authenticated;
grant execute on function
  public.split_share_attach(uuid, text, timestamptz), public.split_share_paid(text, text, int), public.split_refunds_due(), public.split_share_refunded(uuid, text, int)
to service_role;
commit;

-- ====================================================================================================
-- 20261107100000_service_marketplace
-- ====================================================================================================
begin;
-- Hiring professionals (customer app completion plan, M7; client plan page 10): a DJ, photographer, MC or other professional lists services; a customer sends a request for a date; the
-- professional answers with a quote (total, scope, a deposit, when the balance is due); the customer accepts and pays the deposit (or all of it) on Stripe's page; BottlesUp HOLDS the money;
-- after the job it is confirmed (or auto-confirmed) and the professional is paid out by BottlesUp, less the commission.
--
--   * WHO: a professional is a BUSINESS profile whose category is not a venue or an event group; whoever may act as it (profile_can_act_as) runs its services, requests and quotes.
--     A customer is any signed-in person; they cannot hire a profile they run themselves, nor one that blocked them or they blocked.
--   * THE FLOW: request (a date, a place, a message, optionally a service and a budget) -> ONE live quote per request (a new quote withdraws the old) -> accept (the quote must still be valid,
--     the date free) -> a booking that must be paid within 24 hours (the deposit, or everything when the deposit is the whole amount) -> the balance by its due date -> the professional marks it
--     done on or after the date -> the customer confirms (or three days pass) -> the payout is releasable -> BottlesUp pays the professional and records it (cms_pro_payout_paid).
--   * MONEY: the exact amounts are the quote's; the commission is a percentage fixed when the quote is accepted (site_pro_settings, 5% to start); payments are idempotent by Stripe session;
--     refunds are idempotent by Stripe refund id; both are for the website's service role alone (the same discipline as splitting a bill, 20261106100000).
--   * CANCELLING: the professional cancels any time and everything paid is paid back; the customer cancels at least `free_cancel_days` (7) before the date and everything paid is paid back;
--     later, BottlesUp keeps the deposit (at least 30% of the total) for the professional and pays back the rest. Unpaid acceptances lapse after 24 hours; a balance not paid by its due
--     date cancels the booking the same way (the customer lost the deposit).
--   * DISPUTES: the customer may open one from the date until 7 days after it, while the booking is not completed: the payout is held and BottlesUp's staff decide (release, refund in part,
--     refund in full) in the CMS. Everything is in the audit log.
--   * Every function refuses with "Hiring professionals is not open yet." until the `marketplace` switch is on (20261101100000).
--
-- Reached only through the functions below; no table can be read or written by a client. Plain CREATE, never CREATE OR REPLACE.

-- ---------------------------------------------------------------------------
-- 1. Tables
-- ---------------------------------------------------------------------------
create table public.site_pro_settings (
  id int primary key default 1 check (id = 1),
  commission_bps int not null default 500 check (commission_bps between 0 and 5000),
  free_cancel_days int not null default 7 check (free_cancel_days between 0 and 60),
  confirm_days int not null default 3 check (confirm_days between 1 and 30),
  updated_at timestamptz not null default now(),
  updated_by uuid references auth.users (id) on delete set null
);
insert into public.site_pro_settings (id) values (1);

-- A different commission for one professional for a while: a subscription's (written by 20261109100000) or one BottlesUp staff set. The function that fixes a booking's commission reads it.
create table public.site_commission_overrides (
  profile uuid primary key references public.site_profiles (id) on delete cascade,
  commission_bps int not null check (commission_bps between 0 and 5000),
  until timestamptz not null,
  source text not null check (source in ('subscription', 'staff')),
  updated_at timestamptz not null default clock_timestamp()
);

create table public.site_pro_services (
  id uuid primary key default gen_random_uuid(),
  profile uuid not null references public.site_profiles (id) on delete cascade,
  title text not null check (char_length(btrim(title)) between 3 and 80),
  description text check (description is null or char_length(description) <= 1000),
  from_cents int check (from_cents is null or from_cents between 0 and 5000000),
  price_note text check (price_note is null or char_length(price_note) <= 80),
  active boolean not null default true,
  created_at timestamptz not null default clock_timestamp()
);
create index site_pro_services_profile_idx on public.site_pro_services (profile, active, created_at);

-- Days a professional is not free, set by hand (days with an accepted booking are busy too, worked out from the bookings).
create table public.site_pro_busy (
  profile uuid not null references public.site_profiles (id) on delete cascade,
  day date not null,
  primary key (profile, day)
);

create table public.site_pro_requests (
  id uuid primary key default gen_random_uuid(),
  client uuid references auth.users (id) on delete set null,
  provider uuid references public.site_profiles (id) on delete set null,
  service uuid references public.site_pro_services (id) on delete set null,
  event_date date not null,
  time_note text check (time_note is null or char_length(time_note) <= 60),
  location text check (location is null or char_length(location) <= 160),
  guests int check (guests is null or guests between 1 and 100000),
  message text not null check (char_length(btrim(message)) between 3 and 1000),
  budget_cents int check (budget_cents is null or budget_cents between 0 and 50000000),
  status text not null default 'requested' check (status in ('requested', 'quoted', 'declined', 'withdrawn', 'accepted')),
  decline_note text check (decline_note is null or char_length(decline_note) <= 300),
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp()
);
create index site_pro_requests_client_idx on public.site_pro_requests (client, created_at desc);
create index site_pro_requests_provider_idx on public.site_pro_requests (provider, status, created_at desc);

create table public.site_pro_quotes (
  id uuid primary key default gen_random_uuid(),
  request uuid not null references public.site_pro_requests (id) on delete cascade,
  total_cents int not null check (total_cents between 1000 and 5000000),
  deposit_cents int not null check (deposit_cents > 0),
  balance_due_by date,
  scope text not null check (char_length(btrim(scope)) between 10 and 1500),
  valid_until timestamptz not null,
  status text not null default 'sent' check (status in ('sent', 'accepted', 'declined', 'withdrawn')),
  created_at timestamptz not null default clock_timestamp(),
  constraint site_pro_quotes_deposit_le_total check (deposit_cents <= total_cents),
  constraint site_pro_quotes_balance_date check ((deposit_cents = total_cents) = (balance_due_by is null))
);
create unique index site_pro_quotes_one_live on public.site_pro_quotes (request) where status = 'sent';

create table public.site_pro_bookings (
  id uuid primary key default gen_random_uuid(),
  quote uuid not null unique references public.site_pro_quotes (id) on delete restrict,
  request uuid not null references public.site_pro_requests (id) on delete cascade,
  client uuid references auth.users (id) on delete set null,
  provider uuid references public.site_profiles (id) on delete set null,
  title text not null,
  event_date date not null,
  currency text not null default 'cad',
  total_cents int not null check (total_cents > 0),
  deposit_cents int not null check (deposit_cents > 0 and deposit_cents <= total_cents),
  balance_due_by date,
  commission_bps int not null check (commission_bps between 0 and 5000),
  free_cancel_days int not null,
  pay_by timestamptz not null,
  status text not null default 'awaiting_deposit' check (status in ('awaiting_deposit', 'active', 'completed', 'disputed', 'cancelled')),
  paid_cents int not null default 0 check (paid_cents >= 0),
  provider_done_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  cancelled_by text check (cancelled_by in ('client', 'provider', 'system')),
  cancel_reason text check (cancel_reason is null or char_length(cancel_reason) <= 300),
  created_at timestamptz not null default clock_timestamp(),
  constraint site_pro_bookings_cancelled_shape check ((status = 'cancelled') = (cancelled_at is not null and cancelled_by is not null)),
  constraint site_pro_bookings_completed_shape check ((status = 'completed') = (completed_at is not null))
);
create index site_pro_bookings_client_idx on public.site_pro_bookings (client, created_at desc);
create index site_pro_bookings_provider_idx on public.site_pro_bookings (provider, event_date);

create table public.site_pro_payments (
  id uuid primary key default gen_random_uuid(),
  booking uuid not null references public.site_pro_bookings (id) on delete cascade,
  kind text not null check (kind in ('deposit', 'balance', 'full')),
  amount_cents int not null check (amount_cents > 0),
  status text not null default 'created' check (status in ('created', 'pending', 'paid', 'void')),
  stripe_session_id text unique,
  stripe_payment_intent_id text,
  pending_until timestamptz,
  paid_at timestamptz,
  paid_cents int not null default 0 check (paid_cents >= 0),
  refund_due_cents int not null default 0 check (refund_due_cents >= 0),
  refunded_cents int not null default 0 check (refunded_cents >= 0),
  refund_id text,
  created_at timestamptz not null default clock_timestamp(),
  constraint site_pro_payments_money check (refund_due_cents <= paid_cents and refunded_cents <= refund_due_cents),
  constraint site_pro_payments_paid_shape check ((status = 'paid') = (paid_at is not null))
);
create index site_pro_payments_booking_idx on public.site_pro_payments (booking, created_at);
create index site_pro_payments_refund_idx on public.site_pro_payments (booking) where refund_due_cents > refunded_cents;

create table public.site_pro_disputes (
  id uuid primary key default gen_random_uuid(),
  booking uuid not null unique references public.site_pro_bookings (id) on delete cascade,
  opened_by uuid references auth.users (id) on delete set null,
  reason text not null check (char_length(btrim(reason)) between 10 and 1000),
  status text not null default 'open' check (status in ('open', 'resolved')),
  outcome text check (outcome in ('release', 'refund_part', 'refund_full')),
  refund_cents int check (refund_cents is null or refund_cents >= 0),
  note text check (note is null or char_length(note) <= 500),
  decided_by uuid references auth.users (id) on delete set null,
  decided_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  constraint site_pro_disputes_shape check ((status = 'resolved') = (outcome is not null and decided_at is not null))
);

create table public.site_pro_payouts (
  id uuid primary key default gen_random_uuid(),
  booking uuid not null unique references public.site_pro_bookings (id) on delete restrict,
  provider uuid references public.site_profiles (id) on delete set null,
  gross_cents int not null check (gross_cents > 0),
  commission_cents int not null check (commission_cents >= 0),
  net_cents int not null check (net_cents >= 0),
  status text not null default 'releasable' check (status in ('held', 'releasable', 'paid', 'void')),
  reference text check (reference is null or char_length(reference) <= 120),
  paid_at timestamptz,
  paid_by uuid references auth.users (id) on delete set null,
  created_at timestamptz not null default clock_timestamp(),
  constraint site_pro_payouts_net check (net_cents = gross_cents - commission_cents),
  constraint site_pro_payouts_paid_shape check ((status = 'paid') = (paid_at is not null and reference is not null))
);
create index site_pro_payouts_status_idx on public.site_pro_payouts (status, created_at);

alter table public.site_pro_settings enable row level security;
alter table public.site_commission_overrides enable row level security;
alter table public.site_pro_services enable row level security;
alter table public.site_pro_busy enable row level security;
alter table public.site_pro_requests enable row level security;
alter table public.site_pro_quotes enable row level security;
alter table public.site_pro_bookings enable row level security;
alter table public.site_pro_payments enable row level security;
alter table public.site_pro_disputes enable row level security;
alter table public.site_pro_payouts enable row level security;
revoke all on table public.site_pro_settings, public.site_commission_overrides, public.site_pro_services, public.site_pro_busy, public.site_pro_requests, public.site_pro_quotes, public.site_pro_bookings,
  public.site_pro_payments, public.site_pro_disputes, public.site_pro_payouts from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. Helpers (internal)
-- ---------------------------------------------------------------------------
create function public.market_require_on()
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Sign in first.'; end if;
  if not public.feature_enabled('marketplace') then raise exception 'Hiring professionals is not open yet.'; end if;
end;
$$;

-- Is this profile one that can sell services? A business profile that is neither a venue nor an event group, in good standing.
create function public.market_is_provider(p_profile uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.site_profiles p where p.id = p_profile and p.kind = 'business' and p.status = 'active' and p.category not in ('venue', 'event_group'))
$$;

-- May the caller act for this professional on bookings: acting as the profile (in good standing) and allowed the 'bookings' kind of work by their role?
create function public.market_acts(p_provider uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select public.profile_can_act_as(p_provider) and public.profile_has_permission(p_provider, 'bookings')
$$;

-- The professional's side of a request or booking: the actor must be a professional the caller may act as.
create function public.market_require_provider(p_actor uuid)
returns void
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.market_require_on();
  if p_actor is null or not public.profile_can_act_as(p_actor) then raise exception 'You cannot act as this profile.'; end if;
  if not public.profile_has_permission(p_actor, 'bookings') then raise exception 'Your role on this profile does not allow this.'; end if;
  if not public.market_is_provider(p_actor) then raise exception 'Only a professional profile can do this.'; end if;
end;
$$;

create function public.market_commission_bps(p_provider uuid)
returns int
language sql
stable
security definer
set search_path = public
as $$
  select coalesce(
    (select o.commission_bps from public.site_commission_overrides o where o.profile = p_provider and o.until > now()),
    (select s.commission_bps from public.site_pro_settings s where s.id = 1))
$$;

-- Is the day taken? Set by hand, or held by a booking that is waiting for its deposit (still inside its 24 hours), confirmed, done or in dispute.
create function public.market_day_busy(p_provider uuid, p_day date, p_except_booking uuid default null)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from public.site_pro_busy b where b.profile = p_provider and b.day = p_day)
      or exists (select 1 from public.site_pro_bookings k
                  where k.provider = p_provider and k.event_date = p_day and k.id is distinct from p_except_booking
                    and (k.status in ('active', 'disputed') or (k.status = 'awaiting_deposit' and k.pay_by > now())))
$$;

-- What a person sees of a booking's progress, in one word.
create function public.market_booking_state(p_booking uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case
    when b.status = 'cancelled' then 'cancelled'
    when b.status = 'completed' then 'completed'
    when b.status = 'disputed' then 'disputed'
    when b.status = 'awaiting_deposit' and b.pay_by <= now() then 'expired'
    when b.status = 'awaiting_deposit' then 'awaiting_deposit'
    when b.provider_done_at is not null then 'done'
    when b.paid_cents >= b.total_cents then 'paid'
    else 'confirmed'
  end
  from public.site_pro_bookings b where b.id = p_booking
$$;

create function public.market_money(p_cents int)
returns text
language sql
immutable
set search_path = public
as $$
  select to_char(p_cents / 100.0, 'FM999,999,990.00')
$$;

-- A person for the other side to see: their name and username, nothing else.
create function public.market_person(p_user uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select case when pr.id is null then null else jsonb_build_object('name', coalesce(nullif(btrim(pr.name), ''), pr.username, 'A customer'), 'handle', pr.username) end
    from (select 1) x left join public.profiles pr on pr.id = p_user
$$;

create function public.market_quote_json(p_quote uuid)
returns jsonb
language sql
stable
security definer
set search_path = public
as $$
  select jsonb_build_object(
    'id', q.id, 'total_cents', q.total_cents, 'deposit_cents', q.deposit_cents, 'balance_due_by', q.balance_due_by, 'scope', q.scope, 'valid_until', q.valid_until,
    'status', case when q.status = 'sent' and q.valid_until <= now() then 'expired' else q.status end, 'created_at', q.created_at)
    from public.site_pro_quotes q where q.id = p_quote
$$;

-- One booking as either side sees it. `side` says which.
create function public.market_booking_json(p_booking uuid, p_side text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_state text;
begin
  select * into b from public.site_pro_bookings where id = p_booking;
  if not found then return null; end if;
  v_state := public.market_booking_state(p_booking);
  return jsonb_build_object(
    'id', b.id, 'request_id', b.request, 'state', v_state, 'title', b.title, 'event_date', b.event_date, 'currency', b.currency,
    'total_cents', b.total_cents, 'deposit_cents', b.deposit_cents, 'balance_due_by', b.balance_due_by, 'paid_cents', b.paid_cents,
    'owed_cents', greatest(b.total_cents - b.paid_cents, 0),
    'pay_by', b.pay_by, 'provider_done_at', b.provider_done_at, 'completed_at', b.completed_at, 'cancelled_by', b.cancelled_by, 'cancel_reason', b.cancel_reason,
    'free_cancel_days', b.free_cancel_days,
    'provider', case when b.provider is null then null else public.profile_mini(b.provider) end,
    'client', case when p_side = 'provider' then public.market_person(b.client) else null end,
    'net_cents', case when p_side = 'provider' then b.total_cents - (b.total_cents::bigint * b.commission_bps / 10000)::int else null end,
    'commission_bps', case when p_side = 'provider' then b.commission_bps else null end,
    'dispute', (select jsonb_build_object('id', d.id, 'status', d.status, 'outcome', d.outcome, 'reason', d.reason) from public.site_pro_disputes d where d.booking = b.id),
    'created_at', b.created_at);
end;
$$;

-- ---------------------------------------------------------------------------
-- 3. The professional: services and days off
-- ---------------------------------------------------------------------------
create function public.pro_service_save(p_actor uuid, p_id uuid, p_title text, p_description text, p_from_cents int, p_note text, p_active boolean default true)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_title text := btrim(coalesce(p_title, ''));
  v_desc text := nullif(btrim(coalesce(p_description, '')), '');
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_id uuid;
begin
  perform public.market_require_provider(p_actor);
  if char_length(v_title) < 3 or char_length(v_title) > 80 then raise exception 'Give the service a name of 3 to 80 characters.'; end if;
  if v_desc is not null and char_length(v_desc) > 1000 then raise exception 'Keep the description to 1000 characters.'; end if;
  if v_note is not null and char_length(v_note) > 80 then raise exception 'Keep the price note to 80 characters.'; end if;
  if p_from_cents is not null and (p_from_cents < 0 or p_from_cents > 5000000) then raise exception 'Choose a price between 0 and 50,000.00.'; end if;
  if not (public.social_text_ok(v_title) and public.social_text_ok(v_desc) and public.social_text_ok(v_note)) then raise exception 'That wording is not allowed here.'; end if;
  if p_id is null then
    if (select count(*) from public.site_pro_services s where s.profile = p_actor) >= 20 then raise exception 'A profile can list up to 20 services.'; end if;
    insert into public.site_pro_services (profile, title, description, from_cents, price_note, active) values (p_actor, v_title, v_desc, p_from_cents, v_note, coalesce(p_active, true)) returning id into v_id;
  else
    update public.site_pro_services set title = v_title, description = v_desc, from_cents = p_from_cents, price_note = v_note, active = coalesce(p_active, true) where id = p_id and profile = p_actor returning id into v_id;
    if v_id is null then raise exception 'That service is not available.'; end if;
  end if;
  return (select jsonb_build_object('id', s.id, 'title', s.title, 'description', s.description, 'from_cents', s.from_cents, 'price_note', s.price_note, 'active', s.active) from public.site_pro_services s where s.id = v_id);
end;
$$;

create function public.pro_service_remove(p_actor uuid, p_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.market_require_provider(p_actor);
  delete from public.site_pro_services where id = p_id and profile = p_actor;
  if not found then raise exception 'That service is not available.'; end if;
end;
$$;

-- The services of a professional: everyone sees the active ones, the professional's own team sees all.
create function public.pro_services_of(p_profile uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_mine boolean;
begin
  perform public.market_require_on();
  if not public.market_is_provider(p_profile) then return '[]'::jsonb; end if;
  v_mine := public.profile_is_mine(p_profile);
  if not v_mine and exists (select 1 from public.site_profiles me where me.user_id = auth.uid() and me.kind = 'personal' and public.profile_blocked_between(me.id, p_profile)) then return '[]'::jsonb; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id', s.id, 'title', s.title, 'description', s.description, 'from_cents', s.from_cents, 'price_note', s.price_note, 'active', s.active) order by s.created_at, s.id)
                     from public.site_pro_services s where s.profile = p_profile and (s.active or v_mine)), '[]'::jsonb);
end;
$$;

-- Marks a day as not free (or free again).
create function public.pro_busy_set(p_actor uuid, p_day date, p_busy boolean)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  perform public.market_require_provider(p_actor);
  if p_day is null or p_day < current_date or p_day > current_date + 730 then raise exception 'Choose a day within the next two years.'; end if;
  if p_busy then
    insert into public.site_pro_busy (profile, day) values (p_actor, p_day) on conflict do nothing;
  else
    delete from public.site_pro_busy where profile = p_actor and day = p_day;
  end if;
end;
$$;

-- The days a professional is not free in a window of up to 400 days from p_from.
create function public.pro_busy_days(p_profile uuid, p_from date, p_days int default 120)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_from date := coalesce(p_from, current_date);
  v_to date := coalesce(p_from, current_date) + least(greatest(coalesce(p_days, 120), 1), 400);
begin
  perform public.market_require_on();
  if not public.market_is_provider(p_profile) then return '[]'::jsonb; end if;
  return coalesce((
    select jsonb_agg(d order by d) from (
      select b.day as d from public.site_pro_busy b where b.profile = p_profile and b.day >= v_from and b.day < v_to
      union
      select k.event_date from public.site_pro_bookings k
       where k.provider = p_profile and k.event_date >= v_from and k.event_date < v_to
         and (k.status in ('active', 'disputed') or (k.status = 'awaiting_deposit' and k.pay_by > now()))
    ) x), '[]'::jsonb);
end;
$$;

-- ---------------------------------------------------------------------------
-- 4. Requests and quotes
-- ---------------------------------------------------------------------------
create function public.pro_request_create(p_provider uuid, p_service uuid, p_event_date date, p_time_note text, p_location text, p_guests int, p_message text, p_budget_cents int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_msg text := btrim(coalesce(p_message, ''));
  v_time text := nullif(btrim(coalesce(p_time_note, '')), '');
  v_loc text := nullif(btrim(coalesce(p_location, '')), '');
  v_me uuid;
  v_id uuid;
begin
  perform public.market_require_on();
  perform public.social_require_rules();
  if not public.market_is_provider(p_provider) then raise exception 'This professional is not available.'; end if;
  if public.profile_is_mine(p_provider) then raise exception 'You cannot hire yourself.'; end if;
  select p.id into v_me from public.site_profiles p where p.user_id = auth.uid() and p.kind = 'personal';
  if v_me is not null and public.profile_blocked_between(v_me, p_provider) then raise exception 'This professional is not available.'; end if;
  if p_service is not null and not exists (select 1 from public.site_pro_services s where s.id = p_service and s.profile = p_provider and s.active) then raise exception 'That service is not available.'; end if;
  if p_event_date is null or p_event_date <= current_date or p_event_date > current_date + 730 then raise exception 'Choose a date between tomorrow and two years from now.'; end if;
  if char_length(v_msg) < 3 or char_length(v_msg) > 1000 then raise exception 'Tell them about the job in 3 to 1000 characters.'; end if;
  if v_time is not null and char_length(v_time) > 60 then raise exception 'Keep the time to 60 characters.'; end if;
  if v_loc is not null and char_length(v_loc) > 160 then raise exception 'Keep the place to 160 characters.'; end if;
  if p_guests is not null and (p_guests < 1 or p_guests > 100000) then raise exception 'Choose a number of guests between 1 and 100,000.'; end if;
  if p_budget_cents is not null and (p_budget_cents < 0 or p_budget_cents > 50000000) then raise exception 'Choose a budget between 0 and 500,000.00.'; end if;
  if not (public.social_text_ok(v_msg) and public.social_text_ok(v_time) and public.social_text_ok(v_loc)) then raise exception 'That wording is not allowed here.'; end if;
  if public.market_day_busy(p_provider, p_event_date) then raise exception 'This professional is not free on that day.'; end if;
  if (select count(*) from public.site_pro_requests r where r.client = auth.uid() and r.created_at > now() - interval '1 day') >= 5 then raise exception 'You have sent a lot of requests today. Try again tomorrow.'; end if;
  if exists (select 1 from public.site_pro_requests r where r.client = auth.uid() and r.provider = p_provider and r.event_date = p_event_date and r.status in ('requested', 'quoted')) then
    raise exception 'You already have a request open with this professional for that day.';
  end if;
  insert into public.site_pro_requests (client, provider, service, event_date, time_note, location, guests, message, budget_cents)
  values (auth.uid(), p_provider, p_service, p_event_date, v_time, v_loc, p_guests, v_msg, p_budget_cents) returning id into v_id;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.requested', 'site_pro_requests', v_id::text, jsonb_build_object('provider', p_provider, 'event_date', p_event_date));
  return public.pro_request_json(v_id, 'client');
end;
$$;

-- A request with the other side's name, the live quote and the booking if there is one.
create function public.pro_request_json(p_request uuid, p_side text)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
  v_quote uuid;
  v_booking uuid;
begin
  select * into r from public.site_pro_requests where id = p_request;
  if not found then return null; end if;
  select q.id into v_quote from public.site_pro_quotes q where q.request = r.id and q.status in ('sent', 'accepted') order by (q.status = 'accepted') desc, q.created_at desc limit 1;
  select b.id into v_booking from public.site_pro_bookings b where b.request = r.id;
  return jsonb_build_object(
    'id', r.id, 'status', r.status, 'event_date', r.event_date, 'time_note', r.time_note, 'location', r.location, 'guests', r.guests, 'message', r.message,
    'budget_cents', r.budget_cents, 'decline_note', r.decline_note, 'created_at', r.created_at,
    'service', (select jsonb_build_object('id', s.id, 'title', s.title) from public.site_pro_services s where s.id = r.service),
    'provider', case when r.provider is null then null else public.profile_mini(r.provider) end,
    'client', case when p_side = 'provider' then public.market_person(r.client) else null end,
    'quote', case when v_quote is null then null else public.market_quote_json(v_quote) end,
    'booking', case when v_booking is null then null else public.market_booking_json(v_booking, p_side) end);
end;
$$;

-- Which side is the caller on? 'client', 'provider' or null.
create function public.market_side(p_request uuid)
returns text
language sql
stable
security definer
set search_path = public
as $$
  select case when r.client = auth.uid() then 'client' when r.provider is not null and public.market_acts(r.provider) then 'provider' else null end
    from public.site_pro_requests r where r.id = p_request
$$;

create function public.pro_request_get(p_request uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_side text;
begin
  perform public.market_require_on();
  v_side := public.market_side(p_request);
  if v_side is null then raise exception 'This request is not available.'; end if;
  return public.pro_request_json(p_request, v_side);
end;
$$;

create function public.pro_requests_mine()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.market_require_on();
  return coalesce((select jsonb_agg(public.pro_request_json(x.id, 'client') order by x.created_at desc, x.id) from (
    select r.id, r.created_at from public.site_pro_requests r where r.client = auth.uid() order by r.created_at desc, r.id limit 100) x), '[]'::jsonb);
end;
$$;

create function public.pro_requests_for(p_actor uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  perform public.market_require_provider(p_actor);
  return coalesce((select jsonb_agg(public.pro_request_json(x.id, 'provider') order by x.created_at desc, x.id) from (
    select r.id, r.created_at from public.site_pro_requests r where r.provider = p_actor order by r.created_at desc, r.id limit 100) x), '[]'::jsonb);
end;
$$;

create function public.pro_quote_send(p_actor uuid, p_request uuid, p_total_cents int, p_deposit_cents int, p_balance_due_by date, p_scope text, p_valid_days int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
  v_scope text := btrim(coalesce(p_scope, ''));
  v_id uuid;
begin
  perform public.market_require_provider(p_actor);
  select * into r from public.site_pro_requests where id = p_request for update;
  if not found or r.provider is distinct from p_actor then raise exception 'This request is not available.'; end if;
  if r.status not in ('requested', 'quoted') then raise exception 'This request is closed.'; end if;
  if r.event_date <= current_date then raise exception 'The date of this request has passed.'; end if;
  if public.market_day_busy(p_actor, r.event_date) then raise exception 'You are not free on that day: change your days off first.'; end if;
  if p_total_cents is null or p_total_cents < 1000 or p_total_cents > 5000000 then raise exception 'Choose a total between 10.00 and 50,000.00.'; end if;
  if p_deposit_cents is null or p_deposit_cents > p_total_cents or p_deposit_cents < (p_total_cents + 9) / 10 then raise exception 'The deposit must be at least a tenth of the total, and no more than the total.'; end if;
  if p_deposit_cents < p_total_cents then
    if p_balance_due_by is null or p_balance_due_by < current_date or p_balance_due_by >= r.event_date then raise exception 'The balance must be due before the date of the job.'; end if;
  elsif p_balance_due_by is not null then
    raise exception 'There is no balance when the deposit is the whole amount.';
  end if;
  if char_length(v_scope) < 10 or char_length(v_scope) > 1500 then raise exception 'Say what is included in 10 to 1500 characters.'; end if;
  if not public.social_text_ok(v_scope) then raise exception 'That wording is not allowed here.'; end if;
  if p_valid_days is null or p_valid_days < 1 or p_valid_days > 14 then raise exception 'A quote can stay open for 1 to 14 days.'; end if;
  update public.site_pro_quotes set status = 'withdrawn' where request = p_request and status = 'sent';
  insert into public.site_pro_quotes (request, total_cents, deposit_cents, balance_due_by, scope, valid_until)
  values (p_request, p_total_cents, p_deposit_cents, p_balance_due_by, v_scope, now() + make_interval(days => p_valid_days)) returning id into v_id;
  update public.site_pro_requests set status = 'quoted', updated_at = clock_timestamp() where id = p_request;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.quoted', 'site_pro_quotes', v_id::text, jsonb_build_object('request', p_request, 'total_cents', p_total_cents, 'deposit_cents', p_deposit_cents));
  return public.pro_request_json(p_request, 'provider');
end;
$$;

create function public.pro_quote_withdraw(p_actor uuid, p_request uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
begin
  perform public.market_require_provider(p_actor);
  select * into r from public.site_pro_requests where id = p_request for update;
  if not found or r.provider is distinct from p_actor then raise exception 'This request is not available.'; end if;
  update public.site_pro_quotes set status = 'withdrawn' where request = p_request and status = 'sent';
  if not found then raise exception 'There is no open quote to withdraw.'; end if;
  update public.site_pro_requests set status = 'requested', updated_at = clock_timestamp() where id = p_request and status = 'quoted';
  return public.pro_request_json(p_request, 'provider');
end;
$$;

create function public.pro_request_decline(p_actor uuid, p_request uuid, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  perform public.market_require_provider(p_actor);
  if v_note is not null and char_length(v_note) > 300 then raise exception 'Keep the note to 300 characters.'; end if;
  if not public.social_text_ok(v_note) then raise exception 'That wording is not allowed here.'; end if;
  select * into r from public.site_pro_requests where id = p_request for update;
  if not found or r.provider is distinct from p_actor then raise exception 'This request is not available.'; end if;
  if r.status not in ('requested', 'quoted') then raise exception 'This request is closed.'; end if;
  update public.site_pro_quotes set status = 'withdrawn' where request = p_request and status = 'sent';
  update public.site_pro_requests set status = 'declined', decline_note = v_note, updated_at = clock_timestamp() where id = p_request;
  return public.pro_request_json(p_request, 'provider');
end;
$$;

-- The customer takes their request back.
create function public.pro_request_withdraw(p_request uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
begin
  perform public.market_require_on();
  select * into r from public.site_pro_requests where id = p_request for update;
  if not found or r.client is distinct from auth.uid() then raise exception 'This request is not available.'; end if;
  if r.status not in ('requested', 'quoted') then raise exception 'This request is closed.'; end if;
  update public.site_pro_quotes set status = 'withdrawn' where request = p_request and status = 'sent';
  update public.site_pro_requests set status = 'withdrawn', updated_at = clock_timestamp() where id = p_request;
  return public.pro_request_json(p_request, 'client');
end;
$$;

create function public.pro_quote_decline(p_request uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
begin
  perform public.market_require_on();
  select * into r from public.site_pro_requests where id = p_request for update;
  if not found or r.client is distinct from auth.uid() then raise exception 'This request is not available.'; end if;
  update public.site_pro_quotes set status = 'declined' where request = p_request and status = 'sent' and valid_until > now();
  if not found then raise exception 'There is no open quote to turn down.'; end if;
  update public.site_pro_requests set status = 'requested', updated_at = clock_timestamp() where id = p_request and status = 'quoted';
  return public.pro_request_json(p_request, 'client');
end;
$$;

-- The customer accepts the live quote: a booking that must be paid within 24 hours.
create function public.pro_quote_accept(p_request uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  r public.site_pro_requests;
  q public.site_pro_quotes;
  s public.site_pro_settings;
  v_title text;
  v_id uuid;
begin
  perform public.market_require_on();
  select * into r from public.site_pro_requests where id = p_request for update;
  if not found or r.client is distinct from auth.uid() then raise exception 'This request is not available.'; end if;
  select * into q from public.site_pro_quotes where request = p_request and status = 'sent' for update;
  if not found then raise exception 'There is no quote to accept.'; end if;
  if q.valid_until <= now() then raise exception 'This quote has expired. Ask for a new one.'; end if;
  if r.event_date <= current_date then raise exception 'The date of this job has passed.'; end if;
  if q.balance_due_by is not null and q.balance_due_by < current_date then raise exception 'The balance date of this quote has passed. Ask for a new quote.'; end if;
  if r.provider is null or not public.market_is_provider(r.provider) then raise exception 'This professional is not available.'; end if;
  if public.market_day_busy(r.provider, r.event_date) then raise exception 'This professional is no longer free on that day.'; end if;
  select * into s from public.site_pro_settings where id = 1;
  v_title := coalesce((select sv.title from public.site_pro_services sv where sv.id = r.service), 'Booking with ' || coalesce((select pr.display_name from public.site_profiles pr where pr.id = r.provider), 'a professional'));
  insert into public.site_pro_bookings (quote, request, client, provider, title, event_date, total_cents, deposit_cents, balance_due_by, commission_bps, free_cancel_days, pay_by)
  values (q.id, r.id, r.client, r.provider, left(v_title, 120), r.event_date, q.total_cents, q.deposit_cents, q.balance_due_by, public.market_commission_bps(r.provider), s.free_cancel_days, now() + interval '24 hours')
  returning id into v_id;
  update public.site_pro_quotes set status = 'accepted' where id = q.id;
  update public.site_pro_requests set status = 'accepted', updated_at = clock_timestamp() where id = r.id;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.accepted', 'site_pro_bookings', v_id::text, jsonb_build_object('total_cents', q.total_cents, 'deposit_cents', q.deposit_cents));
  return public.market_booking_json(v_id, 'client');
end;
$$;

-- ---------------------------------------------------------------------------
-- 5. Bookings: reading
-- ---------------------------------------------------------------------------
create function public.pro_booking_get(p_booking uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_side text;
begin
  perform public.market_require_on();
  select * into b from public.site_pro_bookings where id = p_booking;
  if not found then raise exception 'This booking is not available.'; end if;
  v_side := case when b.client = auth.uid() then 'client' when b.provider is not null and public.market_acts(b.provider) then 'provider' end;
  if v_side is null then raise exception 'This booking is not available.'; end if;
  return public.market_booking_json(p_booking, v_side);
end;
$$;

-- ---------------------------------------------------------------------------
-- 6. Paying (the website's functions call these)
-- ---------------------------------------------------------------------------
-- The customer may pay NOW: what, how much. Called with the customer's own login by create-service-checkout.
create function public.pro_payment_begin(p_booking uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_owed int;
  v_kind text;
  v_amount int;
  v_open public.site_pro_payments;
  v_pid uuid;
begin
  perform public.market_require_on();
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if not found or b.client is distinct from auth.uid() then raise exception 'This booking is not available.'; end if;
  if b.status = 'awaiting_deposit' then
    if b.pay_by <= now() then raise exception 'The time to pay for this booking has passed. Ask for a new quote.'; end if;
    v_kind := case when b.deposit_cents >= b.total_cents then 'full' else 'deposit' end;
    v_amount := case when v_kind = 'full' then b.total_cents else b.deposit_cents end;
  elsif b.status = 'active' then
    v_owed := b.total_cents - b.paid_cents;
    if v_owed <= 0 then raise exception 'You have paid everything for this booking.'; end if;
    v_kind := 'balance';
    v_amount := v_owed;
  else
    raise exception 'This booking cannot be paid now.';
  end if;
  select * into v_open from public.site_pro_payments p where p.booking = b.id and p.kind = v_kind and p.status in ('created', 'pending') order by p.created_at desc limit 1;
  if found then
    if v_open.status = 'pending' and v_open.pending_until > now() then
      return jsonb_build_object('payment_id', v_open.id, 'kind', v_kind, 'amount_cents', v_open.amount_cents, 'currency', b.currency, 'title', b.title, 'event_date', b.event_date,
                                'provider', (select pr.display_name from public.site_profiles pr where pr.id = b.provider), 'pending_session', v_open.stripe_session_id);
    end if;
    update public.site_pro_payments set status = 'void' where id = v_open.id;
  end if;
  insert into public.site_pro_payments (booking, kind, amount_cents) values (b.id, v_kind, v_amount) returning id into v_pid;
  return jsonb_build_object('payment_id', v_pid, 'kind', v_kind, 'amount_cents', v_amount, 'currency', b.currency, 'title', b.title, 'event_date', b.event_date,
                            'provider', (select pr.display_name from public.site_profiles pr where pr.id = b.provider), 'pending_session', null);
end;
$$;

create function public.pro_payment_attach(p_payment uuid, p_session text, p_until timestamptz)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if p_session is null or btrim(p_session) = '' then raise exception 'a Stripe session is needed'; end if;
  update public.site_pro_payments set status = 'pending', stripe_session_id = p_session, pending_until = p_until where id = p_payment and status in ('created', 'pending');
  if not found then raise exception 'this payment cannot be started now'; end if;
end;
$$;

-- Stripe has taken the money for this session. Idempotent. Answers {result, applied_cents, refund_cents}:
--   applied  - counted towards the booking
--   refund   - could not be used (the booking was cancelled, or the amount is not the payment's): all of it is to be paid back
--   already / unknown
create function public.pro_payment_paid(p_session text, p_payment_intent text, p_amount int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  p public.site_pro_payments;
  b public.site_pro_bookings;
  v_owed int;
  v_apply int;
begin
  select * into p from public.site_pro_payments where stripe_session_id = p_session for update;
  if not found then return jsonb_build_object('result', 'unknown'); end if;
  if p.status = 'paid' then return jsonb_build_object('result', 'already', 'applied_cents', p.paid_cents - p.refund_due_cents, 'refund_cents', p.refund_due_cents - p.refunded_cents); end if;
  if p_amount is null or p_amount <= 0 then raise exception 'an amount is needed'; end if;
  select * into b from public.site_pro_bookings where id = p.booking for update;
  v_owed := greatest(b.total_cents - b.paid_cents, 0);
  if p_amount <> p.amount_cents or b.status not in ('awaiting_deposit', 'active') or (b.status = 'awaiting_deposit' and b.pay_by <= now() - interval '1 hour') or v_owed <= 0 or p.status = 'void' then
    update public.site_pro_payments set status = 'paid', paid_at = clock_timestamp(), stripe_payment_intent_id = p_payment_intent, paid_cents = p_amount, refund_due_cents = p_amount where id = p.id;
    insert into public.audit_log (actor_email, action, entity_type, entity_id, details)
    values ('stripe', 'service.payment_unusable', 'site_pro_payments', p.id::text, jsonb_build_object('booking', b.id, 'amount_cents', p_amount, 'booking_status', b.status));
    return jsonb_build_object('result', 'refund', 'applied_cents', 0, 'refund_cents', p_amount);
  end if;
  v_apply := least(p_amount, v_owed);
  update public.site_pro_payments set status = 'paid', paid_at = clock_timestamp(), stripe_payment_intent_id = p_payment_intent, paid_cents = p_amount, refund_due_cents = p_amount - v_apply where id = p.id;
  update public.site_pro_bookings set paid_cents = paid_cents + v_apply, status = case when status = 'awaiting_deposit' then 'active' else status end where id = b.id;
  insert into public.audit_log (actor_email, action, entity_type, entity_id, details)
  values ('stripe', 'service.payment_taken', 'site_pro_payments', p.id::text, jsonb_build_object('booking', b.id, 'amount_cents', p_amount, 'applied_cents', v_apply));
  return jsonb_build_object('result', 'applied', 'applied_cents', v_apply, 'refund_cents', p_amount - v_apply);
end;
$$;

-- What has to be paid back now.
create function public.pro_refunds_due()
returns table (payment_id uuid, booking_id uuid, stripe_payment_intent_id text, cents int)
language plpgsql
security definer
set search_path = public
as $$
begin
  return query
    select p.id, p.booking, p.stripe_payment_intent_id, (p.refund_due_cents - p.refunded_cents)::int
      from public.site_pro_payments p
     where p.refund_due_cents > p.refunded_cents and p.stripe_payment_intent_id is not null
     order by p.paid_at, p.id;
end;
$$;

create function public.pro_payment_refunded(p_payment uuid, p_refund_id text, p_cents int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  p public.site_pro_payments;
  v_take int;
begin
  if p_refund_id is null or btrim(p_refund_id) = '' or p_cents is null or p_cents <= 0 then raise exception 'a refund id and an amount are needed'; end if;
  select * into p from public.site_pro_payments where id = p_payment for update;
  if not found then raise exception 'this payment does not exist'; end if;
  if p.refund_id is not distinct from p_refund_id and p.refunded_cents > 0 then return jsonb_build_object('result', 'already', 'refunded_cents', p.refunded_cents); end if;
  v_take := least(p_cents, p.refund_due_cents - p.refunded_cents);
  if v_take <= 0 then return jsonb_build_object('result', 'nothing_due', 'refunded_cents', p.refunded_cents); end if;
  update public.site_pro_payments set refunded_cents = refunded_cents + v_take, refund_id = p_refund_id where id = p_payment;
  insert into public.audit_log (actor_email, action, entity_type, entity_id, details)
  values ('stripe', 'service.payment_refunded', 'site_pro_payments', p_payment::text, jsonb_build_object('booking', p.booking, 'refund_id', p_refund_id, 'refunded_cents', v_take));
  return jsonb_build_object('result', 'refunded', 'refunded_cents', p.refunded_cents + v_take);
end;
$$;

-- ---------------------------------------------------------------------------
-- 7. Money out: cancelling, the payout ledger
-- ---------------------------------------------------------------------------
-- Asks for p_cents of what a booking took to be paid back, newest payments first (a payment can only be paid back what it took).
create function public.market_refund_mark(p_booking uuid, p_cents int)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  p record;
  v_left int := p_cents;
  v_room int;
begin
  for p in select * from public.site_pro_payments where booking = p_booking and status = 'paid' order by paid_at desc, id loop
    exit when v_left <= 0;
    v_room := p.paid_cents - p.refund_due_cents;
    if v_room <= 0 then continue; end if;
    update public.site_pro_payments set refund_due_cents = refund_due_cents + least(v_room, v_left) where id = p.id;
    v_left := v_left - least(v_room, v_left);
  end loop;
end;
$$;

-- A payout for p_gross cents kept from a booking (the job done, or a deposit kept), less the commission fixed when the quote was accepted.
create function public.market_payout_make(p_booking uuid, p_gross int, p_status text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_commission int;
begin
  if p_gross <= 0 then return; end if;
  select * into b from public.site_pro_bookings where id = p_booking;
  v_commission := (p_gross::bigint * b.commission_bps / 10000)::int;
  insert into public.site_pro_payouts (booking, provider, gross_cents, commission_cents, net_cents, status)
  values (p_booking, b.provider, p_gross, v_commission, p_gross - v_commission, p_status)
  on conflict (booking) do nothing;
end;
$$;

-- Cancels a booking and works out who gets what. p_by is 'client', 'provider' or 'system'. p_policy: 'full' pays back everything paid; 'by_date' pays back everything when the job is at least
-- free_cancel_days away and otherwise keeps the deposit (at least 30% of the total) for the professional; 'keep' always keeps it (a balance that was never paid).
create function public.market_cancel(p_booking uuid, p_by text, p_reason text, p_policy text)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_keep int := 0;
  v_late boolean;
begin
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if b.status in ('cancelled', 'completed') then return; end if;
  v_late := p_policy = 'keep' or (p_policy = 'by_date' and b.event_date - current_date < b.free_cancel_days);
  if v_late then v_keep := least(b.paid_cents, greatest(b.deposit_cents, (b.total_cents * 30 / 100))); end if;
  update public.site_pro_bookings set status = 'cancelled', cancelled_at = clock_timestamp(), cancelled_by = p_by, cancel_reason = left(nullif(btrim(coalesce(p_reason, '')), ''), 300) where id = p_booking;
  update public.site_pro_payments set status = 'void' where booking = p_booking and status in ('created', 'pending');
  perform public.market_refund_mark(p_booking, b.paid_cents - v_keep);
  if v_keep > 0 then perform public.market_payout_make(p_booking, v_keep, 'releasable'); end if;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'system'), 'service.cancelled', 'site_pro_bookings', p_booking::text,
          jsonb_build_object('by', p_by, 'paid_cents', b.paid_cents, 'kept_cents', v_keep, 'refund_cents', b.paid_cents - v_keep));
end;
$$;

create function public.pro_booking_cancel(p_booking uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_by text;
begin
  perform public.market_require_on();
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if not found then raise exception 'This booking is not available.'; end if;
  v_by := case when b.client = auth.uid() then 'client' when b.provider is not null and public.market_acts(b.provider) then 'provider' end;
  if v_by is null then raise exception 'This booking is not available.'; end if;
  if b.status in ('cancelled', 'completed') then raise exception 'This booking is already closed.'; end if;
  if b.status = 'disputed' then raise exception 'This booking is in dispute: BottlesUp will decide it.'; end if;
  if b.event_date <= current_date and b.status = 'active' then raise exception 'The date has come: if something went wrong, open a dispute instead.'; end if;
  perform public.market_cancel(p_booking, v_by, p_reason, case when v_by = 'provider' then 'full' else 'by_date' end);
  return public.market_booking_json(p_booking, v_by);
end;
$$;

-- ---------------------------------------------------------------------------
-- 8. After the job
-- ---------------------------------------------------------------------------
create function public.pro_booking_done(p_actor uuid, p_booking uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
begin
  perform public.market_require_provider(p_actor);
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if not found or b.provider is distinct from p_actor then raise exception 'This booking is not available.'; end if;
  if b.status <> 'active' then raise exception 'This booking cannot be marked done now.'; end if;
  if b.event_date > current_date then raise exception 'You can mark it done on the day of the job or after.'; end if;
  if b.paid_cents < b.total_cents then raise exception 'It has not been paid in full yet.'; end if;
  if b.provider_done_at is not null then raise exception 'You already marked this done.'; end if;
  update public.site_pro_bookings set provider_done_at = clock_timestamp() where id = p_booking;
  return public.market_booking_json(p_booking, 'provider');
end;
$$;

-- Completed: the payout becomes releasable.
create function public.market_complete(p_booking uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
begin
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if b.status <> 'active' then return; end if;
  update public.site_pro_bookings set status = 'completed', completed_at = clock_timestamp() where id = p_booking;
  perform public.market_payout_make(p_booking, b.paid_cents, 'releasable');
end;
$$;

create function public.pro_booking_confirm(p_booking uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
begin
  perform public.market_require_on();
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if not found or b.client is distinct from auth.uid() then raise exception 'This booking is not available.'; end if;
  if b.status <> 'active' or b.provider_done_at is null then raise exception 'This booking is not waiting for your confirmation.'; end if;
  perform public.market_complete(p_booking);
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.confirmed', 'site_pro_bookings', p_booking::text, '{}'::jsonb);
  return public.market_booking_json(p_booking, 'client');
end;
$$;

create function public.pro_dispute_open(p_booking uuid, p_reason text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  b public.site_pro_bookings;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform public.market_require_on();
  select * into b from public.site_pro_bookings where id = p_booking for update;
  if not found or b.client is distinct from auth.uid() then raise exception 'This booking is not available.'; end if;
  if b.status <> 'active' then raise exception 'This booking cannot be disputed now.'; end if;
  if b.event_date > current_date then raise exception 'You can open a dispute on the day of the job or after.'; end if;
  if b.event_date + 7 < current_date then raise exception 'The time to open a dispute has passed.'; end if;
  if char_length(v_reason) < 10 or char_length(v_reason) > 1000 then raise exception 'Say what went wrong in 10 to 1000 characters.'; end if;
  if not public.social_text_ok(v_reason) then raise exception 'That wording is not allowed here.'; end if;
  insert into public.site_pro_disputes (booking, opened_by, reason) values (p_booking, auth.uid(), v_reason);
  update public.site_pro_bookings set status = 'disputed' where id = p_booking;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.disputed', 'site_pro_bookings', p_booking::text, jsonb_build_object('reason', left(v_reason, 200)));
  return public.market_booking_json(p_booking, 'client');
end;
$$;

-- ---------------------------------------------------------------------------
-- 9. Daily housekeeping (a scheduled job, as the service role)
-- ---------------------------------------------------------------------------
-- Cancels what lapsed (an acceptance never paid, a balance not paid in time, a customer or professional whose account is gone), completes what was done and not disputed in
-- `confirm_days`, and marks old payment pages void. Safe to run any number of times.
create function public.market_housekeeping()
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  s public.site_pro_settings;
  b record;
  v_lapsed int := 0;
  v_balance int := 0;
  v_gone int := 0;
  v_done int := 0;
begin
  select * into s from public.site_pro_settings where id = 1;
  for b in select id from public.site_pro_bookings where status = 'awaiting_deposit' and pay_by <= now() - interval '1 hour' loop
    perform public.market_cancel(b.id, 'system', 'Not paid in time.', 'full');
    v_lapsed := v_lapsed + 1;
  end loop;
  for b in select id from public.site_pro_bookings where status = 'active' and paid_cents < total_cents and balance_due_by is not null and balance_due_by < current_date loop
    perform public.market_cancel(b.id, 'client', 'The balance was not paid by its due date.', 'keep');
    v_balance := v_balance + 1;
  end loop;
  for b in select id, provider from public.site_pro_bookings where status in ('awaiting_deposit', 'active') and (provider is null or client is null) loop
    perform public.market_cancel(b.id, case when b.provider is null then 'provider' else 'client' end, 'An account was closed.', case when b.provider is null then 'full' else 'by_date' end);
    v_gone := v_gone + 1;
  end loop;
  for b in select id from public.site_pro_bookings where status = 'active' and provider_done_at is not null and provider_done_at <= now() - make_interval(days => s.confirm_days) loop
    perform public.market_complete(b.id);
    v_done := v_done + 1;
  end loop;
  update public.site_pro_payments set status = 'void' where status in ('created', 'pending') and created_at < now() - interval '2 days';
  return jsonb_build_object('lapsed', v_lapsed, 'balance_unpaid', v_balance, 'accounts_gone', v_gone, 'completed', v_done);
end;
$$;

-- ---------------------------------------------------------------------------
-- 10. BottlesUp's staff (the CMS)
-- ---------------------------------------------------------------------------
create function public.cms_pro_settings()
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  return (select jsonb_build_object('commission_bps', s.commission_bps, 'free_cancel_days', s.free_cancel_days, 'confirm_days', s.confirm_days, 'updated_at', s.updated_at) from public.site_pro_settings s where s.id = 1);
end;
$$;

create function public.cms_pro_settings_set(p_commission_bps int, p_free_cancel_days int, p_confirm_days int)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can change this.'; end if;
  if p_commission_bps is null or p_commission_bps < 0 or p_commission_bps > 5000 then raise exception 'The commission must be between 0 and 50 percent.'; end if;
  if p_free_cancel_days is null or p_free_cancel_days < 0 or p_free_cancel_days > 60 then raise exception 'Free cancellation must be between 0 and 60 days before the job.'; end if;
  if p_confirm_days is null or p_confirm_days < 1 or p_confirm_days > 30 then raise exception 'Automatic confirmation must be 1 to 30 days after the job is marked done.'; end if;
  update public.site_pro_settings set commission_bps = p_commission_bps, free_cancel_days = p_free_cancel_days, confirm_days = p_confirm_days, updated_at = now(), updated_by = auth.uid() where id = 1;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'marketplace.settings', 'site_pro_settings', '1',
          jsonb_build_object('commission_bps', p_commission_bps, 'free_cancel_days', p_free_cancel_days, 'confirm_days', p_confirm_days));
  return public.cms_pro_settings();
end;
$$;

create function public.cms_pro_disputes(p_status text default 'open')
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  if p_status is null or p_status not in ('open', 'resolved', 'all') then raise exception 'Choose open, resolved or all.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', d.id, 'status', d.status, 'reason', d.reason, 'outcome', d.outcome, 'refund_cents', d.refund_cents, 'note', d.note, 'created_at', d.created_at, 'decided_at', d.decided_at,
      'booking', jsonb_build_object('id', b.id, 'title', b.title, 'event_date', b.event_date, 'total_cents', b.total_cents, 'paid_cents', b.paid_cents, 'currency', b.currency,
                                    'provider', (select pr.display_name from public.site_profiles pr where pr.id = b.provider), 'client', public.market_person(b.client)))
      order by d.created_at, d.id)
    from public.site_pro_disputes d join public.site_pro_bookings b on b.id = d.booking where p_status = 'all' or d.status = p_status), '[]'::jsonb);
end;
$$;

-- Decides a dispute. release: the professional is paid as if confirmed. refund_full: everything paid goes back. refund_part: p_refund_cents goes back and the rest is released.
create function public.cms_pro_dispute_resolve(p_dispute uuid, p_outcome text, p_refund_cents int, p_note text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  d public.site_pro_disputes;
  b public.site_pro_bookings;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_refund int := 0;
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can decide this.'; end if;
  if p_outcome is null or p_outcome not in ('release', 'refund_part', 'refund_full') then raise exception 'Choose release, refund in part or refund in full.'; end if;
  if v_note is null then raise exception 'Write a note: the customer and the professional can be shown it.'; end if;
  if char_length(v_note) > 500 then raise exception 'Keep the note to 500 characters.'; end if;
  select * into d from public.site_pro_disputes where id = p_dispute for update;
  if not found then raise exception 'There is no such dispute.'; end if;
  if d.status = 'resolved' then raise exception 'This dispute is already decided.'; end if;
  select * into b from public.site_pro_bookings where id = d.booking for update;
  if p_outcome = 'refund_full' then v_refund := b.paid_cents;
  elsif p_outcome = 'refund_part' then
    if p_refund_cents is null or p_refund_cents <= 0 or p_refund_cents >= b.paid_cents then raise exception 'A part refund must be more than nothing and less than everything paid (%).', public.market_money(b.paid_cents); end if;
    v_refund := p_refund_cents;
  end if;
  if v_refund > 0 then perform public.market_refund_mark(b.id, v_refund); end if;
  if p_outcome = 'refund_full' then
    update public.site_pro_bookings set status = 'cancelled', cancelled_at = clock_timestamp(), cancelled_by = 'system', cancel_reason = 'Decided in favour of the customer.' where id = b.id;
  else
    update public.site_pro_bookings set status = 'completed', completed_at = clock_timestamp() where id = b.id;
    perform public.market_payout_make(b.id, b.paid_cents - v_refund, 'releasable');
  end if;
  update public.site_pro_disputes set status = 'resolved', outcome = p_outcome, refund_cents = v_refund, note = v_note, decided_by = auth.uid(), decided_at = clock_timestamp() where id = p_dispute;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.dispute_decided', 'site_pro_disputes', p_dispute::text, jsonb_build_object('outcome', p_outcome, 'refund_cents', v_refund, 'note', v_note));
  return jsonb_build_object('id', p_dispute, 'outcome', p_outcome, 'refund_cents', v_refund);
end;
$$;

create function public.cms_pro_payouts(p_status text default 'releasable')
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can see this.'; end if;
  if p_status is null or p_status not in ('releasable', 'paid', 'all') then raise exception 'Choose releasable, paid or all.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object(
      'id', x.id, 'status', x.status, 'gross_cents', x.gross_cents, 'commission_cents', x.commission_cents, 'net_cents', x.net_cents, 'reference', x.reference, 'paid_at', x.paid_at, 'created_at', x.created_at,
      'currency', b.currency, 'title', b.title, 'event_date', b.event_date, 'provider', (select pr.display_name from public.site_profiles pr where pr.id = x.provider))
      order by x.created_at, x.id)
    from public.site_pro_payouts x join public.site_pro_bookings b on b.id = x.booking where p_status = 'all' or x.status = p_status), '[]'::jsonb);
end;
$$;

create function public.cms_pro_payout_paid(p_payout uuid, p_reference text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  x public.site_pro_payouts;
  v_ref text := nullif(btrim(coalesce(p_reference, '')), '');
begin
  if auth.uid() is null or not public.is_cms_admin() then raise exception 'Only a BottlesUp admin can do this.'; end if;
  if v_ref is null or char_length(v_ref) > 120 then raise exception 'Write the transfer reference (up to 120 characters).'; end if;
  select * into x from public.site_pro_payouts where id = p_payout for update;
  if not found then raise exception 'There is no such payout.'; end if;
  if x.status <> 'releasable' then raise exception 'This payout is not waiting to be paid.'; end if;
  update public.site_pro_payouts set status = 'paid', reference = v_ref, paid_at = clock_timestamp(), paid_by = auth.uid() where id = p_payout;
  insert into public.audit_log (actor_id, actor_email, action, entity_type, entity_id, details)
  values (auth.uid(), coalesce(nullif(auth.jwt() ->> 'email', ''), 'unknown'), 'service.payout_paid', 'site_pro_payouts', p_payout::text, jsonb_build_object('net_cents', x.net_cents, 'reference', v_ref));
  return jsonb_build_object('id', p_payout, 'status', 'paid');
end;
$$;

